{"command":"python3 << 'PY'
import subprocess, pathlib, tempfile, json
EXE="/workspace/executable"
d=tempfile.mkdtemp()
(pathlib.Path(d)/"sub").mkdir()
pathlib.Path(d,"a.go").write_text("// Package a x\npackage a\nvar X int\n")
pathlib.Path(d,"sub/c.go").write_text("// Package sub x\npackage sub\nvar Z int\n")
def run(pat):
    # escape for TOML basic string: use single quote literal strings in TOML
    pathlib.Path(d,"c.toml").write_text("[rule.exported]\nexclude=['"+pat+"']\n")
    r=subprocess.run([EXE,"-config","c.toml","-formatter","json","./..."], cwd=d, capture_output=True, text=True)
    try:
        data=json.loads(r.stdout) or []
        return sorted(set(x['Position']['Start']['Filename'] for x in data)), r.stderr
    except Exception as e:
        return (r.stdout, r.stderr)
for pat in ["?", "??", "???", "????", "[","[a-","\\","{}","{a.go,sub/c.go}","{a,sub}","a.go,sub/c.go","*.{go}","x*","*x*","*.go ","**/*.go"]:
    print(repr(pat), run(pat))
PY"}

