	explicit map[string]bool
}

type parseError struct{ msg string }

func (e *parseError) Error() string { return e.msg }

func charDesc(c byte) string {
	if c == '\n' {
		return `'\n'`
	}
	if c == '\r' {
		return `'\r'`
	}
	if c == '\t' {
		return `'\t'`
	}
	return fmt.Sprintf("'%c'", c)
}
func charDescRune(r rune) string {
	if r == '\n' {
		return `'\n'`
	}
	return fmt.Sprintf("'%c'", r)
}

func (p *tomlParser) errAt(line int, lastKey string, format string, args ...interface{}) error {
	msg := fmt.Sprintf(format, args...)
	if lastKey != "" {
		return &parseError{msg: fmt.Sprintf("toml: line %d (last key \"%s\"): %s", line, lastKey, msg)}
	}
	return &parseError{msg: fmt.Sprintf("toml: line %d: %s", line, msg)}
}

func parseTOML(src string) (*TTable, error) {
	p := &tomlParser{src: src, line: 1, root: newTTable(), explicit: map[string]bool{}}
	p.root.Explicit = true
	p.cur = p.root
	for {
		p.skipWhitespaceAndComments(true)
		if p.pos >= len(p.src) {
