func (p *tomlParser) skipSpaces() {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
		p.pos++
	}
}
func (p *tomlParser) skipComment() {
	for p.pos < len(p.src) && p.src[p.pos] != '\n' {
		p.pos++
	}
}
func (p *tomlParser) skipWhitespaceAndComments(newlines bool) {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '\n' {
			p.line++
			p.pos++
		} else if c == '\r' {
			p.pos++
		} else if c == ' ' || c == '\t' {
			p.pos++
		} else if c == '#' {
			p.skipComment()
		} else {
			break
		}
		if !newlines && c == '\n' {
			break
		}
	}
}

// parse a bare or quoted key segment
func (p *tomlParser) parseKeySegment() (string, error) {
	p.skipSpaces()
	if p.pos >= len(p.src) {
		return "", p.errAt(p.line, "", "unexpected EOF; expected key")
	}
	c := p.src[p.pos]
	if c == '"' || c == '\'' {
		v, err := p.parseString()
		if err != nil {
			return "", err
		}
		if v.Kind != TString {
			return "", p.errAt(p.line, "", "invalid key")
		}
		return v.Str, nil
	}
	start := p.pos
	for p.pos < len(p.src) {
		r := rune(p.src[p.pos])
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '-' {
			p.pos++
		} else {
			break
		}
	}
	if start == p.pos {
		if c == '=' {
			return "", p.errAt(p.line, "", "unexpected '=': key name appears blank")
		}
		return "", p.errAt(p.line, "", "unexpected %s: key name appears blank", charDesc(c))
	}
	return p.src[start:p.pos], nil
}

func (p *tomlParser) parseKeyPath() ([]string, error) {
	var parts []string
	for {
		seg, err := p.parseKeySegment()
		if err != nil {
			return nil, err
