	}
	p.explicit[full] = true
	tbl.Explicit = true
	p.cur = tbl
	return nil
}

func (p *tomlParser) parseKeyPathForHeader(startLine int) ([]string, error) {
	var parts []string
	for {
		p.skipSpaces()
		if p.pos >= len(p.src) || p.src[p.pos] == '\n' {
			// unclosed header: line advances
			line := p.line + 1
			return nil, p.errAt(line, "", "expected '.' or ']' to end table name, but got '\\n' instead")
		}
		seg, err := p.parseKeySegment()
		if err != nil {
			return nil, err
		}
		parts = append(parts, seg)
		p.skipSpaces()
		if p.pos < len(p.src) && p.src[p.pos] == '.' {
			p.pos++
			continue
		}
		break
	}
	_ = startLine
	return parts, nil
}

func (p *tomlParser) ensureTable(root *TTable, parts []string) *TTable {
	cur := root
	for _, part := range parts {
		existing := cur.get(part)
		if existing == nil {
			nt := newTTable()
			cur.set(part, &TValue{Kind: TTable, Table: nt, Line: p.line})
			cur = nt
		} else if existing.Kind == TTable {
			cur = existing.Table
