			nt := newTTable()
			cur.set(part, &TValue{Kind: TTable, Table: nt, Line: p.line})
			cur = nt
		}
	}
	return cur
}

func (p *tomlParser) fullKeyFor(cur *TTable, parts []string) string {
	// We don't track path of cur easily; caller passes prefix when needed.
	return joinKey(parts)
}

func (p *tomlParser) parseKeyValue(curTable *TTable, prefix string) error {
