	p.pos++ // =
	// determine full dotted key for lastKey errors: try to reconstruct from root path? We have cur table unknown path.
	// The config decoder knows expected paths; for parse errors original uses full path from document root.
	// We store last parsed full key in parser for errors inside value parsing: compute by searching? Instead approximate:
	// Use prefix param if provided else use a parser field currentPrefix set by table header.
	fullKey := joinKey(parts)
	if p.currentPrefix != "" {
		if fullKey != "" {
			fullKey = p.currentPrefix + "." + fullKey
		} else {
			fullKey = p.currentPrefix
		}
	}
	p.lastKey = fullKey
	p.lastKeyLine = startLine
	val, err := p.parseValue()
	if err != nil {
		return err
	}
	val.Line = startLine
	// insert into curTable navigating dotted parts
	target := curTable
	for i, part := range parts[:len(parts)-1] {
		_ = i
		existing := target.get(part)
		if existing == nil {
			nt := newTTable()
			target.set(part, &TValue{Kind: TTable, Table: nt, Line: startLine})
			target = nt
		} else if existing.Kind == TTable {
			target = existing.Table
		} else {
			// duplicate / conflict handled as already defined?
			full := fullKey
			return p.errAt(startLine, parts[0], "Key '%s' has already been defined.", full)
		}
	}
	last := parts[len(parts)-1]
	if existing := target.get(last); existing != nil {
		// If existing is implicit table created by header, this is a redefinition? Inline dotted duplicates:
		return p.errAt(startLine, fullKeyForError(p, fullKey), "Key '%s' has already been defined.", fullKey)
	}
	target.set(last, val)
	// after value: allow spaces, comment, newline handled by caller loop; but check inline extra here for values parsed as scalars where trailing junk on same line:
	p.skipSpaces()
	if p.pos < len(p.src) && p.src[p.pos] != '\n' && p.src[p.pos] != '\r' && p.src[p.pos] != '#' {
		c := p.src[p.pos]
		// For tables/arrays handled inside parseValue they'll consume closing.
		return p.errAt(p.line, "", "expected a top-level item to end with a newline, comment, or EOF, but got %s instead", charDesc(c))
	}
	return nil
}

func fullKeyForError(p *tomlParser, full string) string { return full }

// fields added via this helper to avoid restructuring struct above (Go doesn't allow, so they are declared in config? ) -- placeholder

func (p *tomlParser) parseValue() (*TValue, error) {
	p.skipSpaces()
	if p.pos >= len(p.src) {
		return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
	}
	c := p.src[p.pos]
	if c == '\n' {
		return nil, p.errAt(p.line, p.lastKey, "expected value but found '\\n' instead")
	}
	switch {
	case c == '"' || c == '\'':
		return p.parseString()
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseInlineTable()
	default:
		return p.parseScalarToken()
	}
}

func (p *tomlParser) parseString() (*TValue, error) {
	startLine := p.line
	quote := p.src[p.pos]
	isMultiline := false
	if p.pos+2 < len(p.src) && p.src[p.pos+1] == quote && p.src[p.pos+2] == quote {
		isMultiline = true
		p.pos += 3
		// first newline is trimmed
		if p.pos < len(p.src) && p.src[p.pos] == '\n' {
			p.pos++
			p.line++
		} else if p.pos+1 < len(p.src) && p.src[p.pos] == '\r' && p.src[p.pos+1] == '\n' {
			p.pos += 2
			p.line++
		}
	} else {
		p.pos++
	}
	var sb strings.Builder
	for p.pos < len(p.src) {
		if isMultiline {
			if p.pos+2 < len(p.src) && p.src[p.pos] == quote && p.src[p.pos+1] == quote && p.src[p.pos+2] == quote {
				p.pos += 3
				return &TValue{Kind: TString, Str: sb.String(), Line: startLine}, nil
			}
		} else {
			if p.src[p.pos] == quote {
				p.pos++
				return &TValue{Kind: TString, Str: sb.String(), Line: startLine}, nil
			}
			if p.src[p.pos] == '\n' {
				return nil, p.errAt(startLine, p.lastKey, "strings cannot contain newlines")
			}
		}
		c := p.src[p.pos]
		if quote == '"' && c == '\\' {
			// escape
			if p.pos+1 >= len(p.src) {
				return nil, p.errAt(p.line, p.lastKey, "strings cannot contain newlines")
			}
			n := p.src[p.pos+1]
			// multiline line-ending backslash
			if isMultiline && (n == '\n' || n == '\r') {
				p.pos++
				// skip newline and leading whitespace on next line
				for p.pos < len(p.src) && (p.src[p.pos] == '\n' || p.src[p.pos] == '\r' || p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
					if p.src[p.pos] == '\n' {
						p.line++
					}
					p.pos++
				}
				continue
			}
			switch n {
			case 'n':
				sb.WriteByte('\n'); p.pos += 2
			case 't':
				sb.WriteByte('\t'); p.pos += 2
			case 'r':
				sb.WriteByte('\r'); p.pos += 2
			case 'b':
				sb.WriteByte('\b'); p.pos += 2
			case 'f':
				sb.WriteByte('\f'); p.pos += 2
			case 'e':
				sb.WriteByte(0x1b); p.pos += 2
			case '"':
				sb.WriteByte('"'); p.pos += 2
			case '\\':
				sb.WriteByte('\\'); p.pos += 2
			case '\'':
				sb.WriteByte('\''); p.pos += 2
			case 'u', 'U':
				nDig := 4
				if n == 'U' {
					nDig = 8
				}
				if p.pos+2+nDig > len(p.src) {
					return nil, p.errAt(p.line, p.lastKey, "invalid escape sequence")
				}
				hex := p.src[p.pos+2 : p.pos+2+nDig]
				num, err := strconv.ParseInt(hex, 16, 32)
				if err != nil {
					return nil, p.errAt(p.line, p.lastKey, "invalid escape sequence")
				}
				sb.WriteRune(rune(num))
				p.pos += 2 + nDig
			default:
				// invalid escape: original would error; approximate by writing char
				sb.WriteByte(n)
				p.pos += 2
			}
			continue
		}
		if c == '\n' {
			p.line++
		}
		// copy one byte (UTF-8 preserved)
		sb.WriteByte(c)
		p.pos++
	}
	// EOF inside string
	if isMultiline {
		return nil, p.errAt(startLine, p.lastKey, "unexpected EOF; expected value")
	}
	return nil, p.errAt(startLine, p.lastKey, "strings cannot contain newlines")
}

func (p *tomlParser) parseArray() (*TValue, error) {
	startLine := p.line
	p.pos++ // [
	arr := &TValue{Kind: TArray, Line: startLine}
	for {
		// skip whitespace, newlines, comments
		for p.pos < len(p.src) {
			c := p.src[p.pos]
			if c == '\n' {
				p.line++; p.pos++
			} else if c == ' ' || c == '\t' || c == '\r' {
				p.pos++
			} else if c == '#' {
				p.skipComment()
			} else {
				break
			}
		}
		if p.pos >= len(p.src) {
			return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		elemLine := p.line
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		v.Line = elemLine
		arr.Arr = append(arr.Arr, v)
		arr.ElemLine = append(arr.ElemLine, elemLine)
		// skip ws
		for p.pos < len(p.src) {
			c := p.src[p.pos]
			if c == '\n' {
				p.line++; p.pos++
			} else if c == ' ' || c == '\t' || c == '\r' {
				p.pos++
			} else if c == '#' {
				p.skipComment()
			} else {
				break
			}
		}
		if p.pos >= len(p.src) {
			return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		return nil, p.errAt(p.line, p.lastKey, "expected a comma or array terminator ']', but got %s instead", charDesc(p.src[p.pos]))
	}
}

func (p *tomlParser) parseInlineTable() (*TValue, error) {
	startLine := p.line
	p.pos++ // {
	tbl := newTTable()
	val := &TValue{Kind: TTable, Table: tbl, Line: startLine}
	p.skipSpaces()
	if p.pos < len(p.src) && p.src[p.pos] == '}' {
		p.pos++
		return val, nil
	}
	for {
		// parse key=value inside, reusing logic but commas separate
		// Save/restore lastKey? Use full handling manually
		if p.pos >= len(p.src) {
			return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
		}
		// inline key value: we can call parseKeyValueInline
		if err := p.parseInlineKeyValue(tbl); err != nil {
			return nil, err
		}
		p.skipSpaces()
		if p.pos < len(p.src) && p.src[p.pos] == ',' {
			p.pos++
			p.skipSpaces()
			continue
		}
		if p.pos < len(p.src) && p.src[p.pos] == '}' {
			p.pos++
			return val, nil
		}
		if p.pos >= len(p.src) {
			return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
		}
		return nil, p.errAt(p.line, p.lastKey, "expected a comma or an inline table terminator '}', but got %s instead", charDesc(p.src[p.pos]))
	}
}

func (p *tomlParser) parseInlineKeyValue(tbl *TTable) error {
	parts, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.skipSpaces()
	if p.pos >= len(p.src) || p.src[p.pos] != '=' {
		if p.pos < len(p.src) {
			return p.errAt(p.line, "", "expected '.' or '=', but got %s instead", charDesc(p.src[p.pos]))
		}
		return p.errAt(p.line, "", "expected '.' or '=', but got '\\n' instead")
	}
	p.pos++
	v, err := p.parseValue()
	if err != nil {
		return err
	}
	target := tbl
	for _, part := range parts[:len(parts)-1] {
		existing := target.get(part)
		if existing == nil {
			nt := newTTable()
			target.set(part, &TValue{Kind: TTable, Table: nt})
			target = nt
		} else if existing.Kind == TTable {
			target = existing.Table
		}
	}
	target.set(parts[len(parts)-1], v)
	return nil
}

func (p *tomlParser) parseScalarToken() (*TValue, error) {
	start := p.pos
	startLine := p.line
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '\n' || c == ' ' || c == '\t' || c == '\r' || c == ',' || c == ']' || c == '}' || c == '#' {
			break
		}
		p.pos++
	}
	tok := p.src[start:p.pos]
	if tok == "" {
		if p.pos < len(p.src) {
			return nil, p.errAt(p.line, p.lastKey, "expected value but found %s instead", charDesc(p.src[p.pos]))
		}
		return nil, p.errAt(p.line, p.lastKey, "unexpected EOF; expected value")
	}
	if tok == "true" {
		return &TValue{Kind: TBool, Bool: true, Line: startLine}, nil
	}
	if tok == "false" {
		return &TValue{Kind: TBool, Bool: false, Line: startLine}, nil
	}
	// datetime detection: contains '-' with digits and (T or date pattern) or ':' time
	if isDateTimeToken(tok) {
		return &TValue{Kind: TDate, Str: tok, Line: startLine}, nil
	}
	// numbers
	if v, ok, err := parseNumberToken(tok, p, startLine); err != nil {
		return nil, err
	} else if ok {
		return v, nil
	}
	// bare token invalid as value
	r, _ := utf8.DecodeRuneInString(tok)
	return nil, p.errAt(startLine, p.lastKey, "expected value but found %s instead", charDescRune(r))
}

func isDateTimeToken(tok string) bool {
	// dates: YYYY-MM-DD ; times: HH:MM:SS ; datetimes contain T
	if len(tok) >= 10 && isDigit(tok[0]) && isDigit(tok[1]) && isDigit(tok[2]) && isDigit(tok[3]) && tok[4] == '-' {
		return true
	}
	if len(tok) >= 8 && isDigit(tok[0]) && isDigit(tok[1]) && tok[2] == ':' && isDigit(tok[3]) {
		return true
	}
	return false
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func parseNumberToken(tok string, p *tomlParser, line int) (*TValue, bool, error) {
	s := tok
	// strip underscores for parsing but validate?
	clean := strings.ReplaceAll(s, "_", "")
	lower := strings.ToLower(clean)
	// hex / oct / bin
	if strings.HasPrefix(lower, "0x") || strings.HasPrefix(lower, "+0x") || strings.HasPrefix(lower, "-0x") {
		sign := int64(1)
		t := lower
		if strings.HasPrefix(t, "+") {
			t = t[1:]
		} else if strings.HasPrefix(t, "-") {
			sign = -1; t = t[1:]
		}
		n, err := strconv.ParseInt(t[2:], 16, 64)
		if err != nil {
			return nil, false, nil
		}
		return &TValue{Kind: TInt, Int: sign * n, Line: line}, true, nil
	}
	if strings.HasPrefix(lower, "0o") {
		n, err := strconv.ParseInt(lower[2:], 8, 64)
		if err != nil {
			return nil, false, nil
		}
		return &TValue{Kind: TInt, Int: n, Line: line}, true, nil
	}
	if strings.HasPrefix(lower, "0b") {
		n, err := strconv.ParseInt(lower[2:], 2, 64)
		if err != nil {
			return nil, false, nil
		}
		return &TValue{Kind: TInt, Int: n, Line: line}, true, nil
	}
	if lower == "inf" || lower == "+inf" || lower == "-inf" || lower == "nan" || lower == "+nan" || lower == "-nan" {
		f, _ := strconv.ParseFloat(clean, 64)
		// Go ParseFloat handles +Inf? Use manual
		if strings.Contains(lower, "nan") {
			f = nanValue()
		} else if strings.HasPrefix(lower, "-") {
			f = negInfValue()
		} else {
			f = infValue()
		}
		return &TValue{Kind: TFloat, Float: f, Line: line}, true, nil
	}
	// integer attempt: all digits/sign
	if isIntegerSyntax(clean) {
		// leading zeroes check
		digits := clean
		if strings.HasPrefix(digits, "+") || strings.HasPrefix(digits, "-") {
			digits = digits[1:]
		}
		if len(digits) > 1 && digits[0] == '0' {
			return nil, true, p.errAt(line, p.lastKey, "Invalid integer \"%s\": cannot have leading zeroes", tok)
		}
		n, err := strconv.ParseInt(clean, 10, 64)
		if err != nil {
			// could be large uint; treat as float? return not ok
			return nil, false, nil
		}
		return &TValue{Kind: TInt, Int: n, Line: line}, true, nil
	}
	// float attempt
	if strings.ContainsAny(clean, ".eE") {
		f, err := strconv.ParseFloat(clean, 64)
		if err == nil {
			return &TValue{Kind: TFloat, Float: f, Line: line}, true, nil
		}
	}
	return nil, false, nil
}

func isIntegerSyntax(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '+' || s[0] == '-' {
		i++
	}
	if i >= len(s) {
		return false
	}
	for ; i < len(s); i++ {
		if !isDigit(s[i]) {
			return false
		}
	}
	return true
}
