			// Determine last key context is hard; top-level items in tables use current table? Original reports (last key ...) for table header extras only when header.
			// For values, parseKeyValue already checks.
			return nil, p.errAt(p.line, "", "expected a top-level item to end with a newline, comment, or EOF, but got %s instead", charDesc(c))
		}
