func (p *tomlParser) skipWhitespaceAndComments(newlines bool) {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '\n' {
			p.line++
			p.pos++
		} else if c == '\r' {
			p.pos++
		} else if c == ' ' || c == '\t' {
