				}
				cfg.Rules[rn] = rc
				cfg.RuleOrder = append(cfg.RuleOrder, rn)
			}
		} else {
			// rule = non-table is silently ignored in original (go-toml quirk)
		}
	}
	cfg.computeRaw()
	return cfg, nil
}

type typeErrFn func(line int, lastKey string, v *TValue, dest string) error

func tomlBool(v *TValue, key string, typeErr typeErrFn) (bool, error) {
	if v.Kind != TKBool {
		return false, typeErr(v.Line, key, v, "boolean")
	}
	return v.Bool, nil
}
func tomlString(v *TValue, key string, typeErr typeErrFn) (string, error) {
	if v.Kind != TKString {
		return "", typeErr(v.Line, key, v, "string")
	}
	return v.Str, nil
}
func tomlFloat(v *TValue, key string, typeErr typeErrFn) (float64, error) {
	if v.Kind == TKFloat {
		return v.Float, nil
	}
	if v.Kind == TKInt {
		return float64(v.Int), nil
	}
	return 0, typeErr(v.Line, key, v, "float")
}
func tomlInt(v *TValue, key string, typeErr typeErrFn) (int64, error) {
	if v.Kind != TKInt {
		return 0, typeErr(v.Line, key, v, "integer")
	}
	return v.Int, nil
}
func tomlStringSlice(v *TValue, key string, typeErr typeErrFn) ([]string, error) {
	if v.Kind != TKArray && v.Kind != TKArrayTable {
		return nil, typeErr(v.Line, key, v, "slice")
	}
	out := []string{}
	for i, e := range v.Arr {
		if e.Kind != TKString {
			line := e.Line
			if line == 0 {
				line = v.Line
			}
			_ = i
			return nil, typeErr(line, key, e, "string")
		}
		out = append(out, e.Str)
	}
	return out, nil
}

