		cfg.RuleOrder = append(cfg.RuleOrder, name)
	}
	cfg.computeRaw()
	return cfg
}

func (c *Config) computeRaw() {
	c.rawSeverity = map[string]string{}
	for name, rc := range c.Rules {
		if rc.Severity != "" {
			c.rawSeverity[name] = rc.Severity
		} else {
			c.rawSeverity[name] = c.Severity
		}
	}
	// for enableAll expansion later, computed further
}

var errCannotReadConfig = fmt.Errorf("cannot read the config file")

func loadConfig(explicit string) (*Config, error) {
	// Determine path
	var path string
	if explicit != "" {
		path = explicit
	} else {
		// search: $XDG_CONFIG_HOME/revive.toml, ./revive.toml, $HOME/revive.toml
		if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
			cand := filepath.Join(xdg, "revive.toml")
			if fileExists(cand) {
				path = cand
			}
		}
		if path == "" {
			if fileExists("revive.toml") {
				path = "revive.toml"
			}
		}
		if path == "" {
			if home, err := os.UserHomeDir(); err == nil && home != "" {
				cand := filepath.Join(home, "revive.toml")
				if fileExists(cand) {
					path = cand
				}
			}
		}
		if path == "" {
			return defaultConfig(), nil
		}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, errCannotReadConfig
	}
	cfg, perr := parseConfigBytes(data)
	if perr != nil {
		return nil, perr
	}
	cfg.FromFile = true
	return cfg, nil
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

func parseConfigBytes(data []byte) (*Config, error) {
	root, err := parseTOML(string(data))
	if err != nil {
		return nil, fmt.Errorf("cannot parse the config file: %s", err.Error())
	}
	cfg := &Config{Rules: map[string]*RuleConfig{}}
	// helper for type mismatch
	typeErr := func(line int, lastKey string, v *TValue, dest string) error {
		return fmt.Errorf("cannot parse the config file: toml: line %d (last key \"%s\"): incompatible types: TOML value has type %s; destination has type %s", line, lastKey, v.typeName(), dest)
	}
	_ = typeErr
	// Known fields
	if v := root.getCI("ignoreGeneratedHeader"); v != nil {
		b, err := tomlBool(v, "ignoreGeneratedHeader", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.IgnoreGeneratedHeader = b
	}
	if v := root.getCI("severity"); v != nil {
		s, err := tomlString(v, "severity", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.Severity = s
	}
	if v := root.getCI("confidence"); v != nil {
		f, err := tomlFloat(v, "confidence", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.Confidence = f
	}
	if v := root.getCI("errorCode"); v != nil {
		n, err := tomlInt(v, "errorCode", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.ErrorCode = int(n)
	}
	if v := root.getCI("warningCode"); v != nil {
		n, err := tomlInt(v, "warningCode", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.WarningCode = int(n)
	}
	if v := root.getCI("enableAllRules"); v != nil {
		b, err := tomlBool(v, "enableAllRules", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.EnableAllRules = b
	}
	if v := root.getCI("exclude"); v != nil {
		ss, err := tomlStringSlice(v, "exclude", typeErr)
		if err != nil {
			return nil, err
		}
		cfg.Exclude = ss
	}
	if v := root.getCI("rule"); v != nil {
		if v.Kind == TKTable {
			for _, rn := range v.Table.Keys {
				rv := v.Table.Map[rn]
				if rv.Kind == TKArrayTable {
					return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key \"rule.%s\"): type mismatch for lint.RuleConfig: expected table but found []map[string]any", rv.Line, rn)
				}
				if rv.Kind != TKTable {
					return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key \"rule.%s\"): type mismatch for lint.RuleConfig: expected table but found %s", rv.Line, rn, rv.typeName())
				}
				rc, err := decodeRuleConfig(rv.Table, rn, typeErr)
				if err != nil {
					return nil, err
				}
				if _, exists := cfg.Rules[rn]; exists {
					// duplicate rule name in different case keys? keep first? Original map overwrite?
				}
				cfg.Rules[rn] = rc
				cfg.RuleOrder = append(cfg.RuleOrder, rn)
			}
		} else {
			// rule = non-table is silently ignored in original (go-toml quirk)
		}
	}
	cfg.computeRaw()
	return cfg, nil
}

type typeErrFn func(line int, lastKey string, v *TValue, dest string) error

func tomlBool(v *TValue, key string, typeErr typeErrFn) (bool, error) {
	if v.Kind != TKBool {
		return false, typeErr(v.Line, key, v, "boolean")
	}
	return v.Bool, nil
}
func tomlString(v *TValue, key string, typeErr typeErrFn) (string, error) {
	if v.Kind != TKString {
		return "", typeErr(v.Line, key, v, "string")
	}
	return v.Str, nil
}
func tomlFloat(v *TValue, key string, typeErr typeErrFn) (float64, error) {
	if v.Kind == TKFloat {
		return v.Float, nil
	}
	if v.Kind == TKInt {
		return float64(v.Int), nil
	}
	return 0, typeErr(v.Line, key, v, "float")
}
func tomlInt(v *TValue, key string, typeErr typeErrFn) (int64, error) {
	if v.Kind != TKInt {
		return 0, typeErr(v.Line, key, v, "integer")
	}
	return v.Int, nil
}
func tomlStringSlice(v *TValue, key string, typeErr typeErrFn) ([]string, error) {
	if v.Kind != TKArray && v.Kind != TKArrayTable {
		return nil, typeErr(v.Line, key, v, "slice")
	}
	out := []string{}
	for i, e := range v.Arr {
		if e.Kind != TKString {
			line := e.Line
			if line == 0 {
				line = v.Line
			}
			_ = i
			return nil, typeErr(line, key, e, "string")
		}
		out = append(out, e.Str)
	}
	return out, nil
}

func decodeRuleConfig(tbl *TomlTable, ruleName string, typeErr typeErrFn) (*RuleConfig, error) {
	rc := &RuleConfig{}
	prefix := "rule." + ruleName
	if v := tbl.getCI("arguments"); v != nil {
		if v.Kind != TKArray && v.Kind != TKArrayTable {
			return nil, typeErr(v.Line, prefix+".arguments", v, "slice")
		}
		args := []interface{}{}
		for _, e := range v.Arr {
			args = append(args, e.generic())
		}
		rc.Arguments = args
	}
	if v := tbl.getCI("severity"); v != nil {
		s, err := tomlString(v, prefix+".severity", typeErr)
		if err != nil {
			// tomlString uses key param for lastKey - we passed full; adjust: it uses provided key directly.
			return nil, err
		}
		rc.Severity = s
	}
	if v := tbl.getCI("disabled"); v != nil {
		// need lastKey lowercase as in file? Original uses canonical field path "rule.exported.disabled" regardless case
		if v.Kind != TKBool {
			return nil, typeErr(v.Line, prefix+".disabled", v, "boolean")
		}
		rc.Disabled = v.Bool
	}
	if v := tbl.getCI("exclude"); v != nil {
		ss, err := tomlStringSliceForRule(v, prefix+".exclude", typeErr)
		if err != nil {
			return nil, err
		}
		rc.Exclude = ss
	}
	return rc, nil
}
func tomlStringSliceForRule(v *TValue, key string, typeErr typeErrFn) ([]string, error) {
	if v.Kind != TKArray && v.Kind != TKArrayTable {
		return nil, typeErr(v.Line, key, v, "slice")
	}
	out := []string{}
	for _, e := range v.Arr {
		if e.Kind != TKString {
			line := e.Line
			if line == 0 {
				line = v.Line
			}
			return nil, typeErr(line, key, e, "string")
		}
		out = append(out, e.Str)
	}
	return out, nil
}

