// resolveDirPattern returns files in a directory (non-recursive), applying build constraints,
// and validating package clause consistency in the style of go/build (errors as strings).
func resolveDirPattern(pat string, dirPath string) ([]ResolvedFile, error) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		return nil, nil
	}
	// display dir for joining
	displayDir := pat
	// trailing slash removed for Join (Join cleans anyway)
	var goFiles []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasSuffix(name, ".go") {
			continue
		}
		if isIgnoredBase(name) {
			continue
		}
		goFiles = append(goFiles, name)
	}
	sort.Strings(goFiles)
	// Header scan for package conflicts / clause errors over all .go files (not only build-matched? original go/build scans all)
	type hdr struct {
		name string
		pkg  string
		err  error
	}
	var hdrs []hdr
	pkgOrder := []string{}
	pkgFirstFile := map[string]string{}
	for _, name := range goFiles {
		full := filepath.Join(dirPath, name)
		data, _ := os.ReadFile(full)
		pkg, perr := scanPackageClause(data, filepath.Join(displayDirForErr(displayDir), name))
		if perr != nil {
			return nil, perr
		}
		hdrs = append(hdrs, hdr{name, pkg, nil})
		if _, ok := pkgFirstFile[pkg]; !ok {
			pkgFirstFile[pkg] = name
			pkgOrder = append(pkgOrder, pkg)
		}
	}
	// conflict detection: distinct package names ignoring foo vs foo_test relationship
	// go/build allows package a and a_test together.
	var nonTestPkgs []string
	for _, pkg := range pkgOrder {
		if strings.HasSuffix(pkg, "_test") {
			base := strings.TrimSuffix(pkg, "_test")
			// allowed if base exists among packages or alone
			_ = base
			continue
		}
		nonTestPkgs = append(nonTestPkgs, pkg)
	}
	if len(nonTestPkgs) > 1 {
		// Also need consider a_test vs b? If packages are a and b_test ??? Simplify: if >1 distinct non-suffix-related
		p1 := nonTestPkgs[0]
		p2 := nonTestPkgs[1]
		return nil, fmt.Errorf("found packages %s (%s) and %s (%s) in %s", p1, pkgFirstFile[p1], p2, pkgFirstFile[p2], displayDirForErr(displayDir))
	}
	// Also case: only a_test and b (different base) would be ? go/build would error "found packages b and a_test"? Ignoring edge.
	var out []ResolvedFile
	for _, h := range hdrs {
