		if ok, _ := build.Default.MatchFile(dirPath, h.name); !ok {
			continue
		}
		abs, _ := filepath.Abs(filepath.Join(dirPath, h.name))
		display := filepath.Join(displayDir, h.name)
		out = append(out, ResolvedFile{Display: display, Abs: abs, Mode: "dir"})
	}
	return out, nil
}

func displayDirForErr(pat string) string {
	// "./sub" -> "sub", "sub" -> "sub", "." -> ".", "./" -> "." computed by Clean except "." preserved
	c := filepath.Clean(pat)
	return c
}

func resolveExcludePatterns(patterns []string) map[string]bool {
	out := map[string]bool{}
	for _, pat := range patterns {
		// use same resolver, ignore errors
		files, _ := resolvePatterns([]string{pat})
		for _, f := range files {
			out[f.Display] = true
		}
	}
	return out
}
