	"fmt"
	"go/parser"
	"go/token"
	"strings"
)

// scanPackageClause extracts package name from file header; returns error formatted like go/build/parser for missing package clause.
func scanPackageClause(data []byte, display string) (string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, display, data, parser.PackageClauseOnly|parser.ParseComments)
	if err != nil {
		// Extract first scanner error message: err string is "display:line:col: msg"
		return "", fmt.Errorf("%s", err.Error())
	}
	if f == nil || f.Name == nil {
		return "", fmt.Errorf("%s:1:1: expected 'package', found EOF", display)
	}
	_ = strings.Contains
	return f.Name.Name, nil
}
