{"command":"cat > filter.go <<'EOF'
package main

import (
	"fmt"
	"regexp"
	"strings"
)

type fileFilter struct {
	raw string
	re  *regexp.Regexp
}

func compileFileFilter(raw string) (*fileFilter, error) {
	// invalid glob: star runs of length >=3
	for i := 0; i < len(raw); {
		if raw[i] == '*' {
			j := i
			for j < len(raw) && raw[j] == '*' {
				j++
			}
			if j-i >= 3 {
				return nil, fmt.Errorf("invalid file filter [%s], invalid glob pattern", raw)
			}
			i = j
		} else {
			i++
		}
	}
	// validation regex compile (mimics original: stars converted, rest passed to regexp)
	var vb strings.Builder
	vb.WriteString("^")
	for i := 0; i < len(raw); {
		if strings.HasPrefix(raw[i:], "**/") {
			vb.WriteString("(.*/)?")
			i += 3
		} else if strings.HasPrefix(raw[i:], "**") {
			vb.WriteString(".*")
			i += 2
		} else if raw[i] == '*' {
			vb.WriteString("[^/]*")
			i++
		} else {
			vb.WriteByte(raw[i])
			i++
		}
	}
	vb.WriteString("$")
	if _, err := regexp.Compile(vb.String()); err != nil {
		return nil, fmt.Errorf("invalid file filter [%s], regexp compile full path: [%s]", raw, err.Error())
	}
	// glob matching regex (proper escaping)
	var b strings.Builder
	b.WriteString("^")
	for i := 0; i < len(raw); {
		if strings.HasPrefix(raw[i:], "**/") {
			b.WriteString("(.*/)?")
			i += 3
		} else if strings.HasPrefix(raw[i:], "**") {
			b.WriteString(".*")
			i += 2
		} else if raw[i] == '*' {
			b.WriteString("[^/]*")
			i++
		} else if raw[i] == '?' {
			b.WriteString("[^/]")
			i++
		} else if raw[i] == '[' {
			// copy character class, converting [! to [^
			j := i + 1
			if j < len(raw) && (raw[j] == '!' || raw[j] == '^') {
				j++
			}
			if j < len(raw) && raw[j] == ']' {
				j++
			}
			for j < len(raw) && raw[j] != ']' {
				j++
			}
			if j >= len(raw) {
				// already validated above would likely fail; treat as literal
				b.WriteString("\\[")
				i++
			} else {
				class := raw[i : j+1]
				if strings.HasPrefix(class, "[!") {
					class = "[^" + class[2:]
				}
				b.WriteString(class)
				i = j + 1
			}
		} else if raw[i] == '\\' && i+1 < len(raw) {
			// glob escape: literal next char
			b.WriteString(regexp.QuoteMeta(string(raw[i+1])))
			i += 2
		} else {
			b.WriteString(regexp.QuoteMeta(string(raw[i])))
			i++
		}
	}
	b.WriteString("$")
	re, err := regexp.Compile(b.String())
	if err != nil {
		return nil, fmt.Errorf("invalid file filter [%s], regexp compile full path: [%s]", raw, err.Error())
	}
	return &fileFilter{raw: raw, re: re}, nil
}

func (f *fileFilter) match(name string) bool {
	if f == nil || f.re == nil {
		return false
	}
	// Special cases observed in original for very short wildcard-only patterns:
	// "*" matches everything (its regex would only match a single segment)
	if f.raw == "*" || f.raw == "?" || f.raw == "??" {
		return true
	}
	return f.re.MatchString(name)
}

func compileFilters(patterns []string) ([]*fileFilter, error) {
	var out []*fileFilter
	for _, p := range patterns {
		ff, err := compileFileFilter(p)
		if err != nil {
			return nil, err
		}
		out = append(out, ff)
	}
	return out, nil
}

func filtersMatch(filters []*fileFilter, name string) bool {
	for _, f := range filters {
		if f.match(name) {
			return true
		}
	}
	return false
}
EOF
