{"command":"cat > lint.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type FileContext struct {
	Display string
	Abs     string
	Mode    string
	Content []byte
	AST     *ast.File
	Fset    *token.FileSet
	Pkg     *PackageContext
	IsTest  bool
	invalid *Failure // if parse error (after package clause)
	parseErrStr string
	directives []directive
}

type PackageContext struct {
	Name  string
	Dir   string // display dir (clean)
	AbsDir string
	Files []*FileContext
	TypesInfo *types.Info
	TypesPkg  *types.Package
	Fset  *token.FileSet
}

type directive struct {
	line  int
	kind  string // "disable","enable","disable-next-line","disable-line"
	rules []string // empty = all
}

var generatedRe = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.$`)

type failingImporter struct{}

func (failingImporter) Import(path string) (*types.Package, error) {
	return nil, fmt.Errorf("can't import %s", path)
}

var _ = importer.Default

func lintFiles(resolved []ResolvedFile, cfg *Config, enabled []*RuleInstance) []Failure {
	// Group by abs dir + package name (determined after parse). Files with no package are logged/dropped in recursive/dir modes.
	// First pass: read + parse
	var fileCtxs []*FileContext
	fset := token.NewFileSet()
	for _, rf := range resolved {
		content, err := os.ReadFile(rf.Abs)
		if err != nil {
			// treated as invalid? Skip
			continue
		}
		if !cfg.IgnoreGeneratedHeader && generatedRe.Match(content) {
			// skip generated file entirely
			continue
		}
		fc := &FileContext{Display: rf.Display, Abs: rf.Abs, Mode: rf.Mode, Content: content, Fset: fset, IsTest: strings.HasSuffix(rf.Display, "_test.go")}
		fileCtxs = append(fileCtxs, fc)
	}
	// Parse each
	type dirGroup struct {
		absDir string
		files  []*FileContext
	}
	dirGroups := map[string]*dirGroup{}
	var dirOrder []*dirGroup
	for _, fc := range fileCtxs {
		astFile, err := parser.ParseFile(fset, fc.Display, fc.Content, parser.ParseComments)
		if err != nil {
			// create error string
			fc.parseErrStr = err.Error()
			if astFile == nil || astFile.Name == nil {
				// no package clause
				if fc.Mode == "file" {
					// invalid file failure handled later as its own package
					fc.AST = astFile
				} else if fc.Mode == "dir" {
					// should have been caught by resolver, but treat as invalid file
					fc.AST = astFile
				} else {
					// recursive: will log & drop dir group
					fc.AST = astFile
				}
			} else {
				fc.AST = astFile
				// invalid file failure
				line, col := extractErrLineCol(err.Error(), fc.Display)
				fc.invalid = &Failure{
					Severity: normalizeSeverity(cfg.Severity),
					Failure:  fmt.Sprintf("invalid file %s: %s", fc.Display, err.Error()),
					RuleName: "",
					Category: "validity",
					Position: FailurePosition{Start: Position{Filename: fc.Display, Offset: 0, Line: line, Column: col}, End: Position{}},
					Confidence: 1,
					rawSeverity: cfg.Severity,
				}
			}
		} else {
			fc.AST = astFile
		}
		absDir := filepath.Dir(fc.Abs)
		dg := dirGroups[absDir]
		if dg == nil {
			dg = &dirGroup{absDir: absDir}
			dirGroups[absDir] = dg
			dirOrder = append(dirOrder, dg)
		}
		dg.files = append(dg.files, fc)
	}
	var failures []Failure
	// Process per directory
	for _, dg := range dirOrder {
		// check for package-clause errors & package conflicts in recursive/dir modes
		hasClauseError := false
		var clauseErrFile *FileContext
		for _, fc := range dg.files {
			if fc.parseErrStr != "" && (fc.AST == nil || fc.AST.Name == nil) {
				hasClauseError = true
				clauseErrFile = fc
				break
			}
		}
		if hasClauseError && dg.files[0].Mode != "file" {
			// log and drop whole directory
			if dg.files[0].Mode == "recursive" {
				log.Printf("%s", clauseErrFile.parseErrStr)
				continue
			}
			// dir mode: resolver should have errored earlier; fallthrough as invalid
		}
		// package name grouping
		pkgFiles := map[string][]*FileContext{}
		var pkgNames []string
		pkgFirstFileName := map[string]string{}
		for _, fc := range dg.files {
			if fc.AST == nil || fc.AST.Name == nil {
				// file mode invalid etc: create a solo package group keyed by display
				key := "\x00invalid\x00" + fc.Display
				pkgFiles[key] = []*FileContext{fc}
				pkgNames = append(pkgNames, key)
				continue
			}
			pn := fc.AST.Name.Name
			if _, ok := pkgFiles[pn]; !ok {
				pkgNames = append(pkgNames, pn)
				pkgFirstFileName[pn] = filepath.Base(fc.Display)
			}
			pkgFiles[pn] = append(pkgFiles[pn], fc)
		}
		// conflict detection for recursive mode: non-test packages differing
		if len(dg.files) > 0 && dg.files[0].Mode == "recursive" {
			var nonTest []string
			for _, pn := range pkgNames {
				if strings.HasPrefix(pn, "\x00") {
					continue
				}
				if strings.HasSuffix(pn, "_test") {
					continue
				}
				nonTest = append(nonTest, pn)
			}
			if len(nonTest) > 1 {
				p1, p2 := nonTest[0], nonTest[1]
				dirDisp := displayDirOf(dg.files[0].Display)
				// original message uses "." when display dir is "."? In recursive walking from ".", dirDisp for root is "."; for subdir it's "sub"
				if dirDisp == "" {
					dirDisp = "."
				}
				log.Printf("found packages %s (%s) and %s (%s) in %s", p1, pkgFirstFileName[p1], p2, pkgFirstFileName[p2], dirDisp)
				continue
			}
		}
		// For each package group, typecheck and lint
		for _, pn := range pkgNames {
			files := pkgFiles[pn]
			pkgName := pn
			if strings.HasPrefix(pn, "\x00") {
				// solo invalid files
				for _, fc := range files {
					if fc.invalid != nil {
						failures = append(failures, *fc.invalid)
					} else if fc.parseErrStr != "" {
						line, col := extractErrLineCol(fc.parseErrStr, fc.Display)
						failures = append(failures, Failure{
							Severity:   normalizeSeverity(cfg.Severity),
							Failure:    fmt.Sprintf("invalid file %s: %s", fc.Display, fc.parseErrStr),
							RuleName:   "",
							Category:   "validity",
							Position:   FailurePosition{Start: Position{Filename: fc.Display, Offset: 0, Line: line, Column: col}},
							Confidence: 1,
						})
					}
				}
				continue
			}
			// sort files by display for determinism (first-file semantics)
			sort.SliceStable(files, func(i, j int) bool { return files[i].Display < files[j].Display })
			pkg := &PackageContext{Name: pkgName, AbsDir: dg.absDir, Fset: fset}
			if len(files) > 0 {
				pkg.Dir = displayDirOf(files[0].Display)
			}
			pkg.Files = files
			for _, fc := range files {
				fc.Pkg = pkg
			}
			// typecheck if any valid AST
			var astFiles []*ast.File
			for _, fc := range files {
				if fc.AST != nil {
					astFiles = append(astFiles, fc.AST)
				}
			}
			if len(astFiles) > 0 {
				info := &types.Info{
					Types:      map[ast.Expr]types.TypeAndValue{},
					Defs:       map[*ast.Ident]types.Object{},
					Uses:       map[*ast.Ident]types.Object{},
					Implicits:  map[ast.Node]types.Object{},
					Selections: map[*ast.SelectorExpr]*types.Selection{},
					Scopes:     map[ast.Node]*types.Scope{},
				}
				conf := types.Config{Importer: failingImporter{}, Error: func(err error) {}, FakeImportC: true}
				// package path: use package name as path (local)
				tpkg, _ := conf.Check(pkgName, fset, astFiles, info)
				pkg.TypesInfo = info
				pkg.TypesPkg = tpkg
			}
			// lint files in package
			for idx, fc := range files {
				fc.directives = parseDirectives(fc)
				if fc.invalid != nil {
					failures = append(failures, *fc.invalid)
					continue
				}
				if fc.AST == nil {
					continue
				}
				isFirst := idx == 0
				for _, rule := range enabled {
					if filtersMatch(rule.filters, fc.Display) {
						continue
					}
					ruleFailures := rule.apply(fc, pkg, isFirst, cfg)
					for _, f := range ruleFailures {
						if f.Confidence < cfg.Confidence {
							continue
						}
						if isDisabledByDirective(fc, f) {
							continue
						}
						failures = append(failures, f)
					}
				}
			}
		}
	}
	return failures
}

func displayDirOf(display string) string {
	d := filepath.Dir(display)
	return d
}

func extractErrLineCol(errStr string, display string) (int, int) {
	// errStr like "a.go:2:11: expected..."
	// Find "display:" prefix
	rest := errStr
	if idx := strings.Index(rest, ":"); idx >= 0 {
		// parse line:col after filename
		// scanner error may contain multiple; take first occurrence pattern :line:col:
		parts := strings.SplitN(rest, ":", 4)
		if len(parts) >= 3 {
			var line, col int
			fmt.Sscanf(parts[1], "%d", &line)
			fmt.Sscanf(parts[2], "%d", &col)
			return line, col
		}
	}
	return 1, 1
}

func parseDirectives(fc *FileContext) []directive {
	if fc.AST == nil {
		return nil
	}
	var out []directive
	for _, cg := range fc.AST.Comments {
		for _, c := range cg.List {
			text := c.Text
			var content string
			if strings.HasPrefix(text, "//") {
				content = strings.TrimSpace(text[2:])
			} else if strings.HasPrefix(text, "/*") {
				content = strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(text, "/*"), "*/"))
			} else {
				continue
			}
			if !strings.HasPrefix(content, "revive:") {
				continue
			}
			rest := strings.TrimPrefix(content, "revive:")
			pos := fc.Fset.Position(c.Pos())
			d := directive{line: pos.Line}
			// order matters: disable-next-line, disable-line, disable, enable
			var remainder string
			switch {
			case strings.HasPrefix(rest, "disable-next-line"):
				d.kind = "disable-next-line"
				remainder = rest[len("disable-next-line"):]
			case strings.HasPrefix(rest, "disable-line"):
				d.kind = "disable-line"
				remainder = rest[len("disable-line"):]
			case strings.HasPrefix(rest, "disable"):
				d.kind = "disable"
				remainder = rest[len("disable"):]
			case strings.HasPrefix(rest, "enable"):
				d.kind = "enable"
				remainder = rest[len("enable"):]
			default:
				continue
			}
			remainder = strings.TrimSpace(remainder)
			if strings.HasPrefix(remainder, ":") {
				listStr := strings.TrimSpace(remainder[1:])
				// cut at " -"
				if idx := strings.Index(listStr, " -"); idx >= 0 {
					listStr = listStr[:idx]
				}
				// split by comma and/or whitespace
				fields := strings.FieldsFunc(listStr, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' })
				for _, f := range fields {
					f = strings.TrimSpace(f)
					if f != "" {
						d.rules = append(d.rules, f)
					}
				}
			}
			out = append(out, d)
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].line < out[j].line })
	return out
}

func directiveMatches(d directive, ruleName string) bool {
	if len(d.rules) == 0 {
		return true
	}
	for _, r := range d.rules {
		if r == ruleName {
			return true
		}
	}
	return false
}

func isDisabledByDirective(fc *FileContext, f Failure) bool {
	line := f.Position.Start.Line
	rule := f.RuleName
	disabled := false
	for _, d := range fc.directives {
		switch d.kind {
		case "disable-next-line":
			if line == d.line+1 && directiveMatches(d, rule) {
				return true
			}
		case "disable-line":
			if line == d.line && directiveMatches(d, rule) {
				return true
			}
		case "disable":
			if d.line <= line && directiveMatches(d, rule) {
				disabled = true
			}
		case "enable":
			if d.line <= line && directiveMatches(d, rule) {
				// enable with empty rules disables all states; enable specific removes that rule.
				// Simplification: if it matches, turn off.
				disabled = false
			}
		}
	}
	return disabled
}
EOF
gofmt -w lint.go && go vet ./... 2>&1 | head -n 20"}

