					}
				}
			}
			out = append(out, d)
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].line < out[j].line })
	return out
}

func directiveMatches(d directive, ruleName string) bool {
	if len(d.rules) == 0 {
		return true
	}
	for _, r := range d.rules {
		if r == ruleName {
			return true
		}
	}
	return false
}

func isDisabledByDirective(fc *FileContext, f Failure) bool {
	line := f.Position.Start.Line
	rule := f.RuleName
	disabled := false
	for _, d := range fc.directives {
		switch d.kind {
		case "disable-next-line":
			if line == d.line+1 && directiveMatches(d, rule) {
				return true
			}
		case "disable-line":
			if line == d.line && directiveMatches(d, rule) {
				return true
			}
		case "disable":
			if d.line <= line && directiveMatches(d, rule) {
				disabled = true
			}
		case "enable":
			if d.line <= line && directiveMatches(d, rule) {
				// enable with empty rules disables all states; enable specific removes that rule.
				// Simplification: if it matches, turn off.
				disabled = false
			}
		}
	}
	return disabled
}
