				seenCheck[n] = true
			}
		}
		// also any configured names not in all (unknown)
		for _, n := range cfg.RuleOrder {
			if !seenCheck[n] {
				namesToCheck = append(namesToCheck, n)
				seenCheck[n] = true
			}
		}
	} else {
		namesToCheck = append(namesToCheck, cfg.RuleOrder...)
	}
