// Build enabled rules. Also validates exclude filters before unknown rule (original order).
func buildRules(cfg *Config) ([]*RuleInstance, error) {
	// 1. validate exclude filters for all rules in cfg (including disabled), in RuleOrder
	for _, name := range cfg.RuleOrder {
		rcfg := cfg.Rules[name]
		if rcfg == nil {
			continue
		}
		if _, err := compileFilters(rcfg.Exclude); err != nil {
			// direct error, caller handles special printing
			return nil, &filterError{rule: name, err: err}
		}
	}
	// Also rules not in RuleOrder (shouldn't happen) - map iteration stable sorted
	// 2. Determine set of configured names to validate
	// Start with configured rules
	namesToCheck := []string{}
	seenCheck := map[string]bool{}
	if cfg.EnableAllRules {
		for _, n := range allRuleNames {
			if !seenCheck[n] {
				namesToCheck = append(namesToCheck, n)
				seenCheck[n] = true
			}
		}
		// also any configured names not in all (unknown)
		for _, n := range cfg.RuleOrder {
			if !seenCheck[n] {
				namesToCheck = append(namesToCheck, n)
				seenCheck[n] = true
			}
		}
	} else {
		namesToCheck = append(namesToCheck, cfg.RuleOrder...)
	}
	// Validate existence and configure for all namesToCheck that are configured or all when enableAll
	var enabled []*RuleInstance
	// effective rule config map for enableAll
	effective := map[string]*RuleConfig{}
	if cfg.EnableAllRules {
		for _, n := range allRuleNames {
			if rc, ok := cfg.Rules[n]; ok {
				effective[n] = rc
			} else {
				effective[n] = &RuleConfig{}
			}
		}
		// update cfg.Rules to include all for sarif etc, and raw severity
		for n, rc := range effective {
			if _, ok := cfg.Rules[n]; !ok {
				cfg.Rules[n] = rc
				// don't append to RuleOrder? Sarif uses map, not order.
			}
		}
		cfg.computeRaw()
	}
	// Unknown / configure in namesToCheck order (original used map random; file order is deterministic)
	for _, name := range namesToCheck {
		desc, ok := ruleRegistry[name]
		if !ok {
			// stub descriptor for known names not yet registered in code? registry should contain all; if missing from registry but in all list, treat as known no-op
			if isKnownRuleName(name) {
				desc = ruleDescriptor{Cat: "", Impl: nil}
				ok = true
			} else {
				return nil, fmt.Errorf("cannot find rule: %s", name)
			}
		}
		// Determine config for this rule
		var rcfg *RuleConfig
		if cfg.EnableAllRules {
			rcfg = effective[name]
			if rcfg == nil {
				rcfg = &RuleConfig{}
			}
		} else {
			rcfg = cfg.Rules[name]
		}
		if rcfg == nil {
			continue
		}
		// configure validation (even if disabled? Original: unknown checked even if disabled; configure for disabled? probe said export with bad arg... assume configure also for disabled/enableAll)
		if desc.Configure != nil && len(rcfg.Arguments) >= 0 && rcfg.Arguments != nil {
			if err := desc.Configure(rcfg.Arguments, rcfg); err != nil {
				return nil, &configureError{rule: name, err: err}
			}
		} else if desc.Configure != nil && rcfg.Arguments != nil {
			if err := desc.Configure(rcfg.Arguments, rcfg); err != nil {
				return nil, &configureError{rule: name, err: err}
			}
		}
		if !cfg.EnableAllRules && rcfg.Disabled {
			continue
		}
		if cfg.EnableAllRules && rcfg.Disabled {
			continue
		}
		filters, _ := compileFilters(rcfg.Exclude)
		inst := &RuleInstance{
			Name:        name,
			Cat:         desc.Cat,
			severity:    cfg.severityForRule(name),
			rawSeverity: cfg.rawSevForRule(name),
			cfg:         rcfg,
			desc:        desc,
			filters:     filters,
		}
		enabled = append(enabled, inst)
	}
	// For rules that are known but not yet in registry (no implementation), they are already accounted as desc stub above.
	return enabled, nil
}

func isKnownRuleName(name string) bool {
	for _, n := range allRuleNames {
		if n == name {
			return true
		}
	}
	for _, n := range defaultRuleNames {
		if n == name {
			return true
		}
	}
	return false
}

