		return nil
	}
	return failures
}

// MarshalJSON for Failure to ensure rawSeverity not exported and field order matches struct order.
// Default struct marshaling already respects field order; rawSeverity is unexported so omitted.

func formatFriendly(failures []Failure) error {
	if len(failures) == 0 {
		return nil
	}
	errCount := 0
	warnCount := 0
	errRules := map[string]int{}
	warnRules := map[string]int{}
	// per failure
	for _, f := range failures {
		icon := "⚠"
		if f.Severity == "error" {
			icon = "✘"
			errCount++
			errRules[f.RuleName]++
		} else {
			warnCount++
			warnRules[f.RuleName]++
		}
		fmt.Printf("  %s  https://revive.run/r#%s  %s\n", icon, f.RuleName, f.Failure)
		fmt.Printf("  %s\n\n", f.Position.Start.String())
	}
	total := len(failures)
	summaryIcon := "⚠"
	if errCount > 0 {
		summaryIcon = "✘"
	}
	problemWord := "problems"
	if total == 1 {
		problemWord = "problem"
	}
	fmt.Printf("%s %d %s (%d %s, %d %s)\n", summaryIcon, total, problemWord, errCount, plural(errCount, "error", "errors"), warnCount, plural(warnCount, "warning", "warnings"))
	fmt.Println()
	// Sections
	printSection := func(title string, m map[string]int) {
		fmt.Printf("%s:\n", title)
		for _, kv := range sortedRuleCounts(m) {
			fmt.Printf("  %d  %s\n", kv.count, kv.name)
		}
	}
	sections := []string{}
	_ = sections
	if errCount > 0 {
		printSection("Errors", errRules)
		fmt.Println()
	}
	if warnCount > 0 {
		printSection("Warnings", warnRules)
		fmt.Println()
	}
	fmt.Println()
	return nil
}

func plural(n int, singular, pluralForm string) string {
	if n == 1 {
		return singular
	}
	return pluralForm
}

type ruleCount struct {
	name  string
	count int
}

func sortedRuleCounts(m map[string]int) []ruleCount {
	var out []ruleCount
	for k, v := range m {
		out = append(out, ruleCount{k, v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].count != out[j].count {
			return out[i].count > out[j].count
		}
		return out[i].name < out[j].name
	})
	return out
}

func formatStylish(failures []Failure) error {
	if len(failures) == 0 {
		return nil
	}
	// group by file preserving sorted file names
	files := []string{}
	byFile := map[string][]Failure{}
	for _, f := range failures {
		fn := f.Position.Start.Filename
		if _, ok := byFile[fn]; !ok {
			files = append(files, fn)
		}
		byFile[fn] = append(byFile[fn], f)
	}
	sort.Strings(files)
	errCount, warnCount := 0, 0
	for _, f := range failures {
		if f.Severity == "error" {
			errCount++
		} else {
			warnCount++
		}
	}
	for idx, fn := range files {
		if idx > 0 {
			fmt.Println()
		}
		fmt.Println(fn)
		group := byFile[fn]
		sort.SliceStable(group, func(i, j int) bool {
			if group[i].Position.Start.Line != group[j].Position.Start.Line {
				return group[i].Position.Start.Line < group[j].Position.Start.Line
			}
			return group[i].Position.Start.Column < group[j].Position.Start.Column
		})
		maxURL := 0
		for _, f := range group {
			u := "https://revive.run/r#" + f.RuleName
			if len(u) > maxURL {
				maxURL = len(u)
			}
		}
		for _, f := range group {
			u := "https://revive.run/r#" + f.RuleName
			pad := strings.Repeat(" ", maxURL-len(u))
			fmt.Printf("  (%d, %d)  %s%s  %s\n", f.Position.Start.Line, f.Position.Start.Column, u, pad, f.Failure)
		}
	}
	total := len(failures)
	fmt.Println()
	fmt.Println()
	fmt.Printf(" ✖ %d %s (%d %s) (%d %s)\n", total, plural(total, "problem", "problems"), errCount, plural(errCount, "error", "errors"), warnCount, plural(warnCount, "warning", "warnings"))
	return nil
}

func formatCheckstyle(failures []Failure) error {
	fmt.Println("<?xml version='1.0' encoding='UTF-8'?>")
	fmt.Println(`<checkstyle version="5.0">`)
	// group by file sorted
	files := []string{}
	byFile := map[string][]Failure{}
	for _, f := range failures {
		fn := f.Position.Start.Filename
		if _, ok := byFile[fn]; !ok {
			files = append(files, fn)
		}
		byFile[fn] = append(byFile[fn], f)
	}
	sort.Strings(files)
	for _, fn := range files {
		fmt.Printf("    <file name=\"%s\">\n", xmlEscapeAttr(fn))
		group := byFile[fn]
		sort.SliceStable(group, func(i, j int) bool {
			if group[i].Position.Start.Line != group[j].Position.Start.Line {
				return group[i].Position.Start.Line < group[j].Position.Start.Line
			}
			return group[i].Position.Start.Column < group[j].Position.Start.Column
		})
		for _, f := range group {
			msg := fmt.Sprintf("%s (confidence %v)", f.Failure, formatConfidence(f.Confidence))
			fmt.Printf("      <error line=\"%d\" column=\"%d\" message=\"%s\" severity=\"%s\" source=\"revive/%s\"/>\n", f.Position.Start.Line, f.Position.Start.Column, xmlEscapeAttr(msg), xmlEscapeAttr(f.Severity), xmlEscapeAttr(f.RuleName))
		}
		fmt.Println("    </file>")
	}
	fmt.Println("</checkstyle>")
	return nil
}

func formatConfidence(c float64) string {
	// %v for float64 in Go prints 1 for 1, 0.8 etc.
	return fmt.Sprintf("%v", c)
}

func xmlEscapeAttr(s string) string {
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&quot;",
		"'", "&#39;", // Go xml escapes ' as &#39; ? encoding/xml uses &#39; for attribute? Need check later
	)
	// Actually checkstyle output from original likely uses encoding/xml which escapes " as &quot; (?) and ' may remain.
	// We'll use replacer but revert &#39; if needed later (test will compare).
	_ = r
	// Use encoding/xml-like escaping manually: & < > " and control
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	return s
}

// SARIF structures with field order matching original
type sarifOutput struct {
	Runs    []sarifRun `json:"runs"`
	Version string     `json:"version"`
}
type sarifRun struct {
	Results []sarifResult `json:"results,omitempty"`
	Tool    sarifTool     `json:"tool"`
}
type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}
type sarifDriver struct {
	InformationURI string       `json:"informationUri"`
	Name           string       `json:"name"`
	Rules          []sarifRule  `json:"rules,omitempty"`
}
type sarifRule struct {
	HelpURI    string          `json:"helpUri"`
	ID         string          `json:"id"`
	Properties sarifRuleProps  `json:"properties"`
}
type sarifRuleProps struct {
	Severity string `json:"severity"`
}
type sarifResult struct {
	Level     string          `json:"level,omitempty"`
	Locations []sarifLocation `json:"locations"`
	Message   sarifMessage    `json:"message"`
	RuleID    string          `json:"ruleId"`
}
type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}
type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           sarifRegion           `json:"region"`
}
type sarifArtifactLocation struct {
	URI string `json:"uri"`
}
type sarifRegion struct {
	StartColumn int `json:"startColumn"`
	StartLine   int `json:"startLine"`
}
type sarifMessage struct {
	Text string `json:"text"`
}

func formatSarif(failures []Failure, cfg *Config) error {
	var results []sarifResult
	for _, f := range failures {
		level := ""
		if cfg != nil {
			// raw severity for that rule
			if _, ok := cfg.Rules[f.RuleName]; ok {
				level = cfg.rawSevForRule(f.RuleName)
			}
		}
		res := sarifResult{
			Level: level,
			Locations: []sarifLocation{{PhysicalLocation: sarifPhysicalLocation{
				ArtifactLocation: sarifArtifactLocation{URI: f.Position.Start.Filename},
				Region:           sarifRegion{StartColumn: f.Position.Start.Column, StartLine: f.Position.Start.Line},
			}}},
			Message: sarifMessage{Text: f.Failure},
			RuleID:  f.RuleName,
		}
		results = append(results, res)
	}
	var rules []sarifRule
	if cfg != nil && len(cfg.Rules) > 0 {
		// Pick exactly one rule via Go map iteration (random), mimicking original bug
		for name := range cfg.Rules {
			rules = []sarifRule{{
				HelpURI: "https://revive.run/r#" + name,
				ID:      name,
				Properties: sarifRuleProps{Severity: cfg.rawSevForRule(name)},
			}}
			break
		}
	}
	out := sarifOutput{
		Runs: []sarifRun{{
			Results: results,
			Tool:    sarifTool{Driver: sarifDriver{InformationURI: "https://revive.run", Name: "revive", Rules: rules}},
		}},
		Version: "2.1.0",
	}
	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	_, err = os.Stdout.Write(append(data, '\n'))
	return err
}
EOF
