{"command":"cat > main.go <<'EOF'
package main

import (
	"flag"
	"fmt"
	"os"
	"strings"
)

const banner = `
 _ __ _____   _(_)__  _____
| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|

Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...
`

type stringListFlag []string

func (s *stringListFlag) String() string {
	if s == nil {
		return ""
	}
	return strings.Join(*s, ",")
}
func (s *stringListFlag) Set(v string) error {
	*s = append(*s, v)
	return nil
}

func main() {
	fs := flag.NewFlagSet(os.Args[0], flag.ExitOnError)
	// Go default output is stderr; custom Usage prints banner to stdout + usage to stderr
	fs.Usage = func() {
		fmt.Println(banner)
		fmt.Fprintf(fs.Output(), "Usage of %s:\n", os.Args[0])
		fs.PrintDefaults()
	}
	// Note: flag package uses fs.Output() for errors as well. Default is stderr.
	configPath := fs.String("config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	var excludes stringListFlag
	fs.Var(&excludes, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	formatterName := fs.String("formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	maxOpen := fs.Int("max_open_files", 0, "maximum number of open files at the same time")
	setExit := fs.Bool("set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	versionFlag := fs.Bool("version", false, "get revive version")
	fs.Parse(os.Args[1:])
	_ = maxOpen

	if *versionFlag {
		fmt.Println("Version:\t5570362")
		fmt.Println("Commit:\t\t5570362e88f0b23eb901a0ea856e77c3fd66ea95")
		fmt.Println("Built\t\t2026-06-11 22:12 UTC by build.sh")
		return
	}

	cfg, err := loadConfig(*configPath)
	if err != nil {
		if err == errCannotReadConfig {
			fmt.Fprintln(os.Stderr, "cannot read the config file")
			os.Exit(1)
		}
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	enabledRules, err := buildRules(cfg)
	if err != nil {
		if fe, ok := err.(*filterError); ok {
			fmt.Fprintf(os.Stderr, "error in config of rule [%s] : [%s]\n", fe.rule, fe.err.Error())
			os.Exit(1)
		}
		if ce, ok := err.(*configureError); ok {
			fmt.Fprintf(os.Stderr, "initializing revive - getting lint rules: cannot configure rule: \"%s\": %s\n", ce.rule, ce.err.Error())
			os.Exit(1)
		}
		fmt.Fprintf(os.Stderr, "initializing revive - getting lint rules: %s\n", err.Error())
		os.Exit(1)
	}

	patterns := fs.Args()
	resolved, err := resolvePatterns(patterns)
	if err != nil {
		fmt.Fprintf(os.Stderr, "linting - getting packages: getting packages - resolving packages in dots: %s\n", err.Error())
		os.Exit(1)
	}
	// Exclude patterns from CLI and config
	allExcludePatterns := []string{}
	allExcludePatterns = append(allExcludePatterns, cfg.Exclude...)
	allExcludePatterns = append(allExcludePatterns, excludes...)
	if len(allExcludePatterns) > 0 {
		excluded := resolveExcludePatterns(allExcludePatterns)
		filtered := resolved[:0]
		// need new slice to avoid mutating underlying during iteration? Use new
		filtered = nil
		for _, f := range resolved {
			if excluded[f.Display] {
				continue
			}
			filtered = append(filtered, f)
		}
		resolved = filtered
	}

	failures := lintFiles(resolved, cfg, enabledRules)

	// formatter selection
	fname := *formatterName
	if fname == "" {
		fname = "default"
	}
	// Validate formatter names
	validFormatters := map[string]bool{"default": true, "json": true, "ndjson": true, "friendly": true, "stylish": true, "checkstyle": true, "sarif": true, "plain": true, "unix": true}
	if !validFormatters[fname] {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: unknown formatter %s\n", fname)
		os.Exit(1)
	}
	if err := formatFailures(fname, failures, cfg); err != nil {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: %s\n", err.Error())
		os.Exit(1)
	}

	// exit status
	if *setExit {
		if len(failures) > 0 {
			os.Exit(1)
		}
		return
	}
	hasError := false
	hasWarning := false
	for _, f := range failures {
		if f.Severity == "error" {
			hasError = true
		} else {
			hasWarning = true
		}
	}
	if hasError {
		if cfg.ErrorCode != 0 {
			os.Exit(cfg.ErrorCode)
		}
