		if len(failures) > 0 {
			os.Exit(1)
		}
		return
	}
	hasError := false
	hasWarning := false
	for _, f := range failures {
		if f.Severity == "error" {
			hasError = true
		} else {
			hasWarning = true
		}
	}
	if hasError {
		if cfg.ErrorCode != 0 {
			os.Exit(cfg.ErrorCode)
		}
	} else if hasWarning {
		if cfg.WarningCode != 0 {
			os.Exit(cfg.WarningCode)
		}
	}
}
