package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strconv"
	"strings"
)

func (rc *RuleContext) source(node ast.Node) string {
	if node == nil {
		return ""
	}
	f := rc.File.Fset.File(node.Pos())
	if f == nil {
		return ""
	}
	start := f.Offset(node.Pos())
	end := f.Offset(node.End())
	if start < 0 || end > len(rc.File.Content) || start > end {
		return ""
	}
	return string(rc.File.Content[start:end])
}
func (rc *RuleContext) sourcePos(start, end token.Pos) string {
	f := rc.File.Fset.File(start)
	if f == nil {
		return ""
	}
	s := f.Offset(start)
	e := f.Offset(end)
	if s < 0 || e > len(rc.File.Content) || s > e {
		return ""
	}
	return string(rc.File.Content[s:e])
}

// exprString returns textual representation (source for current file, or unparsed approximation)
func (rc *RuleContext) exprString(e ast.Expr) string {
	if e == nil {
		return ""
	}
	// if in same file, use source
	f := rc.File.Fset.File(e.Pos())
	if f != nil {
		return rc.source(e)
	}
	// fallback: print ident/selector
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return rc.exprString(t.X) + "." + t.Sel.Name
	case *ast.StarExpr:
		return "*" + rc.exprString(t.X)
	}
	return ""
}

func isExportedName(name string) bool { return ast.IsExported(name) }

func receiverBaseName(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.StarExpr:
		return receiverBaseName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr:
		return receiverBaseName(t.X)
	case *ast.IndexListExpr:
		return receiverBaseName(t.X)
	case *ast.SelectorExpr:
		return t.Sel.Name
	}
	return ""
}
func receiverTypeString(rc *RuleContext, expr ast.Expr) string {
	// returns base name only
	return receiverBaseName(expr)
}

// typeOf helper
func (rc *RuleContext) typeOf(e ast.Expr) types.Type {
	if rc.Pkg == nil || rc.Pkg.TypesInfo == nil {
		return nil
	}
	if tv, ok := rc.Pkg.TypesInfo.Types[e]; ok {
		return tv.Type
	}
	return nil
}
func (rc *RuleContext) objectOf(id *ast.Ident) types.Object {
	if rc.Pkg == nil || rc.Pkg.TypesInfo == nil {
		return nil
	}
	if obj := rc.Pkg.TypesInfo.Defs[id]; obj != nil {
		return obj
	}
	return rc.Pkg.TypesInfo.Uses[id]
}

func selectorPkgSel(e ast.Expr) (string, string, bool) {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return "", "", false
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return "", "", false
	}
	return id.Name, sel.Sel.Name, true
}
func isCallTo(e ast.Expr, pkg, name string) bool {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return false
	}
	p, s, ok := selectorPkgSel(call.Fun)
	return ok && p == pkg && s == name
}

func unquoteString(lit *ast.BasicLit) (string, bool) {
	if lit.Kind != token.STRING {
		return "", false
	}
	s, err := strconv.Unquote(lit.Value)
	if err != nil {
		return "", false
	}
	return s, true
}

// walk with parent stack
func walkWithParent(node ast.Node, fn func(n ast.Node, parent ast.Node)) {
	var stack []ast.Node
	ast.Inspect(node, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return false
		}
		var parent ast.Node
		if len(stack) > 0 {
			parent = stack[len(stack)-1]
		}
		fn(n, parent)
		stack = append(stack, n)
		return true
	})
}

func lastStmt(block *ast.BlockStmt) ast.Stmt {
	if block == nil || len(block.List) == 0 {
		return nil
	}
	return block.List[len(block.List)-1]
}

func trimSpace(s string) string { return strings.TrimSpace(s) }

// commentText first meaningful... returns CommentGroup.Text()
func commentGroupText(cg *ast.CommentGroup) string {
	if cg == nil {
		return ""
	}
	return cg.Text()
}
