cat > rules_default.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	registerRule("blank-imports", "imports", ruleBlankImports)
	registerRule("context-as-argument", "arg-order", ruleContextAsArgument)
	registerRule("context-keys-type", "content", ruleContextKeysType)
	registerRule("dot-imports", "imports", ruleDotImports)
	registerRule("empty-block", "logic", ruleEmptyBlock)
	registerRule("error-naming", "naming", ruleErrorNaming)
	registerRule("error-return", "style", ruleErrorReturn)
	registerRule("error-strings", "errors", ruleErrorStrings)
	registerRule("errorf", "errors", ruleErrorf)
	registerRuleWithConfig("exported", "comments", ruleExported, configureExported)
	registerRule("increment-decrement", "unary-op", ruleIncrementDecrement)
	registerRule("indent-error-flow", "", ruleIndentErrorFlow)
	registerRule("package-comments", "comments", rulePackageComments)
	registerRule("range", "", ruleRange)
	registerRule("receiver-naming", "naming", ruleReceiverNaming)
	registerRule("superfluous-else", "", ruleSuperfluousElse)
	registerRule("time-naming", "time", ruleTimeNaming)
	registerRule("unexported-return", "unexported-type-in-api", ruleUnexportedReturn)
	registerRule("unreachable-code", "logic", ruleUnreachableCode)
	registerRule("unused-parameter", "bad practice", ruleUnusedParameter)
	registerRule("var-declaration", "type-inference", ruleVarDeclaration)
	registerRuleWithConfig("var-naming", "naming", ruleVarNaming, configureVarNaming)
}

func ruleBlankImports(rc *RuleContext) {
	if rc.File.AST.Name != nil && rc.File.AST.Name.Name == "main" {
		return
	}
	if rc.File.IsTest {
		return
	}
	for _, imp := range rc.File.AST.Imports {
		if imp.Name != nil && imp.Name.Name == "_" {
			if imp.Doc != nil || imp.Comment != nil {
				continue
			}
			rc.addNode(imp, "a blank import should be only in a main or test package, or have a comment justifying it", 1)
		}
	}
}

func ruleContextAsArgument(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Type == nil || fd.Type.Params == nil {
			continue
		}
		for i, field := range fd.Type.Params.List {
			if i == 0 {
				continue
			}
			pkg, sel, ok := selectorPkgSel(field.Type)
			if ok && pkg == "context" && sel == "Context" {
				rc.addNode(field, "context.Context should be the first parameter of a function", 0.9)
			}
		}
	}
	// also check func literals? original only FuncDecl per probing (func type was not flagged, literal unknown) - also inspect literals as fallback? skip
}

func ruleContextKeysType(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "context" || sel != "WithValue" {
			return true
		}
		if len(call.Args) < 2 {
			return true
		}
		key := call.Args[1]
		typ := rc.typeOf(key)
		if typ != nil {
			if basic, ok := typ.(*types.Basic); ok {
				name := basic.Name()
				// basic.Name() gives e.g. "untyped string", "string"
				rc.addNode(call, fmt.Sprintf("should not use basic type %s as key in context.WithValue", name), 1)
				return true
			}
			return true
		}
		// fallback for untyped constants when type info missing for literals
		if lit, ok := key.(*ast.BasicLit); ok {
			var tn string
			switch lit.Kind {
			case token.STRING:
				tn = "untyped string"
			case token.INT:
				tn = "untyped int"
			case token.FLOAT:
				tn = "untyped float64"
			case token.CHAR:
				tn = "untyped rune"
			}
			if tn != "" {
				rc.addNode(call, fmt.Sprintf("should not use basic type %s as key in context.WithValue", tn), 1)
			}
		}
		return true
	})
}

func ruleDotImports(rc *RuleContext) {
	for _, imp := range rc.File.AST.Imports {
		if imp.Name != nil && imp.Name.Name == "." {
			rc.addNode(imp, "should not use dot imports", 1)
		}
	}
}

func ruleEmptyBlock(rc *RuleContext) {
	walkWithParent(rc.File.AST, func(n ast.Node, parent ast.Node) {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) != 0 {
			return
		}
		switch parent.(type) {
		case *ast.FuncDecl, *ast.FuncLit, *ast.SelectStmt:
			return
		}
		rc.addNode(block, "this block is empty, you can remove it", 1)
	})
}

func ruleErrorNaming(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.VAR {
			continue
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for idx, name := range vs.Names {
				if name.Name == "_" {
					continue
				}
				// find value
				var val ast.Expr
				if len(vs.Values) == 1 {
					val = vs.Values[0]
				} else if idx < len(vs.Values) {
					val = vs.Values[idx]
				}
				if val == nil {
					continue
				}
				call, ok := val.(*ast.CallExpr)
				if !ok {
					continue
				}
				pkg, sel, ok := selectorPkgSel(call.Fun)
				if !ok || !((pkg == "errors" && sel == "New") || (pkg == "fmt" && sel == "Errorf")) {
					continue
				}
				nm := name.Name
				if strings.HasPrefix(nm, "err") || strings.HasPrefix(nm, "Err") {
					continue
				}
				form := "errFoo"
				if ast.IsExported(nm) {
					form = "ErrFoo"
				}
				rc.addNode(name, fmt.Sprintf("error var %s should have name of the form %s", nm, form), 0.9)
			}
		}
	}
}

func ruleErrorReturn(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Type == nil || fd.Type.Results == nil {
			continue
		}
		// flatten result types
		var resultTypes []ast.Expr
		for _, field := range fd.Type.Results.List {
			count := len(field.Names)
			if count == 0 {
				count = 1
			}
			for i := 0; i < count; i++ {
				resultTypes = append(resultTypes, field.Type)
			}
		}
		if len(resultTypes) < 2 {
			continue
		}
		isErr := func(e ast.Expr) bool {
			id, ok := e.(*ast.Ident)
			return ok && id.Name == "error"
		}
		if isErr(resultTypes[len(resultTypes)-1]) {
			continue
		}
		for _, e := range resultTypes {
			if isErr(e) {
				rc.addNode(fd, "error should be the last type when returning multiple items", 0.9)
				break
			}
		}
	}
}

func ruleErrorStrings(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || !((pkg == "errors" && sel == "New") || (pkg == "fmt" && sel == "Errorf")) {
			return true
		}
		if len(call.Args) == 0 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok {
			return true
		}
		s, ok := unquoteString(lit)
		if !ok || s == "" {
			return true
		}
		last := rune(s[len(s)-1])
		if last == '.' || last == '!' || last == '?' || last == ':' || last == '\n' {
			rc.addNode(lit, "error strings should not be capitalized or end with punctuation or a newline", 0.8)
		}
		return true
	})
}

func ruleErrorf(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "errors" || sel != "New" {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		inner, ok := call.Args[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		p2, s2, ok := selectorPkgSel(inner.Fun)
		if !ok || p2 != "fmt" || s2 != "Sprintf" {
			return true
		}
		// Build replacement line
		outerSrc := rc.source(call)
		innerArgsSrc := ""
		// args source of sprintf: reconstruct from file between '(' and ')'
		// Use source of inner call and extract inside parens
		innerSrc := rc.source(inner)
		if idx := strings.Index(innerSrc, "("); idx >= 0 && strings.HasSuffix(innerSrc, ")") {
			innerArgsSrc = innerSrc[idx+1 : len(innerSrc)-1]
		}
		replacementExpr := fmt.Sprintf("fmt.Errorf(%s)", innerArgsSrc)
		line := rc.lineContaining(call)
		replLine := strings.Replace(line, outerSrc, replacementExpr, 1)
		// Original replacement line appears trimmed
		replLine = strings.TrimSpace(replLine)
		rc.addNodeRepl(call, "should replace errors.New(fmt.Sprintf(...)) with fmt.Errorf(...)", 1, replLine)
		return true
	})
}

func (rc *RuleContext) lineContaining(node ast.Node) string {
	// get line text from content using node's line
	pos := rc.File.Fset.Position(node.Pos())
	if pos.Line < 1 {
		return rc.source(node)
	}
	lines := strings.Split(string(rc.File.Content), "\n")
	if pos.Line-1 < len(lines) {
		return lines[pos.Line-1]
	}
	return rc.source(node)
}

// ---- exported ----
var exportedDisableStuttering bool // not used; per instance config stored in RuleConfig generic? We handle via rc.Rule.cfg

func configureExported(args []interface{}, cfg *RuleConfig) error {
	for _, a := range args {
		s, ok := a.(string)
		if !ok {
			return fmt.Errorf("invalid argument for the exported rule: expecting a string, got %T", a)
		}
		switch s {
		case "disableStutteringCheck", "checkPrivateReceivers":
			// ok
		default:
			return fmt.Errorf("unknown configuration flag %s for exported rule", s)
		}
	}
	return nil
}

func exportedArgs(cfg *RuleConfig) (disableStutter bool, checkPrivateRec bool) {
	if cfg == nil {
		return
	}
	for _, a := range cfg.Arguments {
		if s, ok := a.(string); ok {
			if s == "disableStutteringCheck" {
				disableStutter = true
			}
			if s == "checkPrivateReceivers" {
				checkPrivateRec = true
			}
		}
	}
	return
}

func commentFormOK(text string, name string, allowArticle bool) bool {
	text = strings.TrimSpace(text)
	if text == "" {
		return false
	}
	// Check leading article
	if allowArticle {
		for _, art := range []string{"A ", "An ", "The ", "a ", "an ", "the "} {
			if strings.HasPrefix(text, art) {
				rest := text[len(art):]
				if strings.HasPrefix(rest, name+" ") || strings.HasPrefix(rest, name+"\n") {
					// need something after name's space? golint: name + space implies there is following word char?
					// If rest is exactly "Name " with nothing, still? Require rest longer than name+1
					if len(rest) > len(name)+1 {
						return true
					}
					return false
				}
			}
		}
	}
	if strings.HasPrefix(text, name+" ") {
		if len(text) > len(name)+1 {
			// Special: "Foo (Deprecated)": text also starts with "Foo "
			return true
		}
	}
	return false
}

func ruleExported(rc *RuleContext) {
	if rc.File.AST.Name != nil && rc.File.AST.Name.Name == "main" {
		return
	}
	if rc.File.IsTest {
		return
	}
	pkgName := rc.File.AST.Name.Name
	disableStutter, checkPrivate := exportedArgs(rc.Rule.cfg)
	_ = checkPrivate
	for _, decl := range rc.File.AST.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			isExp := ast.IsExported(d.Name.Name)
			shouldCheck := isExp
			kindWord := "function"
			displayName := d.Name.Name
			if d.Recv != nil && len(d.Recv.List) > 0 {
				kindWord = "method"
				recvBase := receiverBaseName(d.Recv.List[0].Type)
				displayName = recvBase + "." + d.Name.Name
				if !isExp {
					shouldCheck = false
				}
				if checkPrivate && isExp {
					shouldCheck = true
				}
				if !shouldCheck {
					break
				}
				if d.Doc == nil || len(d.Doc.List) == 0 {
					rc.addNode(d, fmt.Sprintf("exported method %s should have comment or be unexported", displayName), 1)
				} else if !commentFormOK(commentGroupText(d.Doc), d.Name.Name, false) {
					// But parenthetical deprecated accepted by commentFormOK because starts with Name+space
					rc.addNode(d, fmt.Sprintf("comment on exported method %s should be of the form \"%s ...\"", displayName, d.Name.Name), 0.8)
				}
				break
			}
			if !shouldCheck {
				break
			}
			if d.Doc == nil || len(d.Doc.List) == 0 {
				rc.addNode(d, fmt.Sprintf("exported function %s should have comment or be unexported", displayName), 1)
			} else if !commentFormOK(commentGroupText(d.Doc), d.Name.Name, false) {
				rc.addNode(d, fmt.Sprintf("comment on exported function %s should be of the form \"%s ...\"", displayName, d.Name.Name), 0.8)
			}
			if !disableStutter {
				checkStutter(rc, d.Name, pkgName, "func")
			}
		case *ast.GenDecl:
			switch d.Tok {
			case token.TYPE:
				for _, spec := range d.Specs {
					ts, ok := spec.(*ast.TypeSpec)
					if !ok || !ast.IsExported(ts.Name.Name) {
						continue
					}
					// Determine comment
					var doc *ast.CommentGroup
					var docNode ast.Node
					if ts.Doc != nil && len(ts.Doc.List) > 0 {
						doc = ts.Doc
						docNode = ts.Doc
					} else if d.Doc != nil && len(d.Doc.List) > 0 {
						doc = d.Doc
						docNode = d.Doc
					}
					if doc == nil {
						rc.addNode(ts, fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name), 1)
					} else if !commentFormOK(commentGroupText(doc), ts.Name.Name, true) {
						// position: if doc came from GenDecl (group or single), use doc node; else ?
						// For single type with doc from GenDecl, original position likely doc or spec? Use docNode
						rc.addPos(docNode.Pos(), docNode.End(), fmt.Sprintf("comment on exported type %s should be of the form \"%s ...\" (with optional leading article)", ts.Name.Name, ts.Name.Name), 0.8, "comments", "")
					}
					if !disableStutter {
						checkStutter(rc, ts.Name, pkgName, "type")
					}
				}
			case token.VAR, token.CONST:
				kind := "var"
				if d.Tok == token.CONST {
					kind = "const"
				}
				isGrouped := d.Lparen.IsValid()
				for _, spec := range d.Specs {
					vs, ok := spec.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, name := range vs.Names {
						if !ast.IsExported(name.Name) {
							continue
						}
						// Determine comment
						var doc *ast.CommentGroup
						var docNode ast.Node
						hasDoc := false
						formCheck := true
						if vs.Doc != nil && len(vs.Doc.List) > 0 {
							doc = vs.Doc
							docNode = vs.Doc
							hasDoc = true
						} else if !isGrouped && d.Doc != nil && len(d.Doc.List) > 0 {
							doc = d.Doc
							docNode = d.Doc
							hasDoc = true
						} else if isGrouped && d.Doc != nil && len(d.Doc.List) > 0 {
							// block comment covers, no form check
							hasDoc = true
							formCheck = false
						}
						if !hasDoc {
							if isGrouped {
								rc.addNode(vs, fmt.Sprintf("exported %s %s should have comment (or a comment on this block) or be unexported", kind, name.Name), 1)
							} else {
								rc.addNode(vs, fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name), 1)
							}
						} else if formCheck && doc != nil && !commentFormOK(commentGroupText(doc), name.Name, true) {
							// For var/const, article parenthetical in message? probing suggests no parenthetical for var; use without? But we pass allowArticle true.
							// Message for var: original "comment on exported var X should be of the form \"X ...\"" (seen in generated case)
							_ = docNode
							rc.addNode(vs, fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\"", kind, name.Name, name.Name), 0.8)
						}
					}
				}
			}
		}
	}
}

func checkStutter(rc *RuleContext, nameIdent *ast.Ident, pkgName string, kind string) {
	name := nameIdent.Name
	if len(pkgName) == 0 {
		return
	}
	prefix := strings.ToUpper(pkgName[:1]) + pkgName[1:]
	if !strings.HasPrefix(name, prefix) {
		return
	}
	rest := name[len(prefix):]
	if rest == "" {
		return
	}
	if rest[0] < 'A' || rest[0] > 'Z' {
		return
	}
	rc.addPos(nameIdent.Pos(), nameIdent.End(), fmt.Sprintf("%s name will be used as %s.%s by other packages, and that stutters; consider calling this %s", kind, pkgName, name, rest), 0.8, "naming", "")
}

func ruleIncrementDecrement(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if assign.Tok != token.ADD_ASSIGN && assign.Tok != token.SUB_ASSIGN {
			return true
		}
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lit, ok := assign.Rhs[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.INT || lit.Value != "1" {
			return true
		}
		lhsSrc := rc.source(assign.Lhs[0])
		op := "++"
		opStr := "+="
		if assign.Tok == token.SUB_ASSIGN {
			op = "--"
			opStr = "-="
		}
		rc.addNode(assign, fmt.Sprintf("should replace %s %s 1 with %s%s", lhsSrc, opStr, lhsSrc, op), 0.8)
		return true
	})
}

func ruleIndentErrorFlow(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		last := lastStmt(ifStmt.Body)
		if _, isRet := last.(*ast.ReturnStmt); isRet {
			rc.addNode(elseBlock, "if block ends with a return statement, so drop this else and outdent its block", 1)
		}
		return true
	})
}

func rulePackageComments(rc *RuleContext) {
	if rc.File.IsTest {
		return
	}
	// only evaluate on first file of package (package-level handling)
	// Find package doc among package files
	var docFile *FileContext
	for _, f := range rc.Pkg.Files {
		if f.AST != nil && f.AST.Doc != nil && len(f.AST.Doc.List) > 0 {
			docFile = f
			break
		}
	}
	pkgName := rc.File.AST.Name.Name
	if docFile == nil {
		if !rc.IsFirst {
			return
		}
		// position package clause: from Package token to Name end
		rc.addPos(rc.File.AST.Pos(), rc.File.AST.Name.End(), "should have a package comment", 1, "comments", "")
		return
	}
	if docFile != rc.File {
		return
	}
	doc := docFile.AST.Doc
	text := commentGroupText(doc)
	if strings.HasPrefix(text, fmt.Sprintf("Package %s ", pkgName)) && len(strings.TrimSpace(text)) > len("Package "+pkgName) {
		return
	}
	// Also accept "Package name\n..."? original fails for just "Package a" without description; with description on next line maybe starts with "Package a\n" - treat as ok if text contains space or newline after name and more content not only name
	// We'll use check: HasPrefix "Package pkg " only as above.
	rc.addPos(doc.Pos(), doc.End(), fmt.Sprintf("package comment should be of the form \"Package %s ...\"", pkgName), 1, "comments", "")
}

func ruleRange(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok || rs.Value == nil {
			return true
		}
		if id, ok := rs.Value.(*ast.Ident); ok && id.Name == "_" {
			keySrc := "_"
			if rs.Key != nil {
				keySrc = rc.source(rs.Key)
			}
			tokStr := ":="
			if rs.Tok == token.ASSIGN {
				tokStr = "="
			}
			xSrc := rc.source(rs.X)
			msg := fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s %s range ...`", keySrc, tokStr)
			repl := fmt.Sprintf("for %s %s range %s {", keySrc, tokStr, xSrc)
			rc.addPos(rs.Value.Pos(), rs.Value.End(), msg, 1, "", repl)
		}
		return true
	})
}

func ruleReceiverNaming(rc *RuleContext) {
	// Build package-wide first receiver names
	type recvInfo struct {
		firstName string
	}
	// Compute across package sorted files (Pkg.Files order is sorted)
	firstByType := map[string]string{}
	// We need to know for current method if it is not first; computed in apply loops below using map built globally.
	for _, f := range rc.Pkg.Files {
		if f.AST == nil {
			continue
		}
		for _, decl := range f.AST.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 {
				continue
			}
			recvField := fd.Recv.List[0]
			base := receiverBaseName(recvField.Type)
			if len(recvField.Names) == 0 {
				continue
			}
			nm := recvField.Names[0].Name
			if _, ok := firstByType[base]; !ok {
				firstByType[base] = nm
			}
		}
	}
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 {
			continue
		}
		recvField := fd.Recv.List[0]
		if len(recvField.Names) == 0 {
			continue
		}
		nameIdent := recvField.Names[0]
		nm := nameIdent.Name
		base := receiverBaseName(recvField.Type)
		if nm == "_" {
			rc.addNode(fd, "receiver name should not be an underscore, omit the name if it is unused", 1)
			continue
		}
		if nm == "this" || nm == "self" {
			rc.addNode(fd, "receiver name should be a reflection of its identity; don't use generic names such as \"this\" or \"self\"", 1)
			continue
		}
		if first, ok := firstByType[base]; ok && first != nm {
			// only flag if current is not the first occurrence: first occurrence is determined by order appearance.
			// Determine if this decl is the first for that type in package: we can check if fd is first by comparing file/pos order.
			// Simplification: if nm != first, it is a later one.
			rc.addNode(fd, fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", nm, first, base), 1)
		}
	}
}

func ruleSuperfluousElse(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		last := lastStmt(ifStmt.Body)
		if last == nil {
			return true
		}
		phrase := ""
		switch stmt := last.(type) {
		case *ast.BranchStmt:
			switch stmt.Tok {
			case token.BREAK:
				phrase = "a break statement"
			case token.CONTINUE:
				phrase = "a continue statement"
			case token.GOTO:
				phrase = "a goto statement"
			}
		case *ast.ExprStmt:
			if call, ok := stmt.X.(*ast.CallExpr); ok {
				if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "panic" {
					phrase = "call to panic function"
				} else if pkg, sel, ok := selectorPkgSel(call.Fun); ok {
					phrase = fmt.Sprintf("call to %s.%s function", pkg, sel)
					// only certain exiters considered
					if !((pkg == "os" && sel == "Exit") || (pkg == "log" && (strings.HasPrefix(sel, "Fatal") || strings.HasPrefix(sel, "Panic"))) || (pkg == "runtime" && sel == "Goexit") || (pkg == "syscall" && sel == "Exit")) {
						phrase = ""
					}
				}
			}
		}
		// also consider Expr at block level? panic is ExprStmt. Return handled by indent rule, not here.
		// What about a statement that is a call directly? In Go, calls are ExprStmt.
		if phrase != "" {
			rc.addNode(elseBlock, fmt.Sprintf("if block ends with %s, so drop this else and outdent its block", phrase), 1)
		}
		return true
	})
}

var timeUnitSuffixes = []string{
	"Milliseconds", "Millisecond", "Microseconds", "Microsecond", "Nanoseconds", "Nanosecond",
	"Seconds", "Second", "Minutes", "Minute", "Hours", "Hour",
	"Msecs", "Msec", "Usec", "Secs", "Sec", "Mins", "Min", "Ms", "MS",
	// Note: cases below determined by probe; Ns etc not included
}

func ruleTimeNaming(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		vs, ok := n.(*ast.ValueSpec)
		if !ok {
			return true
		}
		for _, name := range vs.Names {
			obj := rc.objectOf(name)
			if obj == nil {
				continue
			}
			typ := obj.Type()
			if typ == nil {
				continue
			}
			// named type time.Duration
			named, ok := typ.(*types.Named)
			if !ok {
				continue
			}
			o := named.Obj()
			if o == nil || o.Pkg() == nil || o.Pkg().Name() != "time" || o.Name() != "Duration" {
				continue
			}
			for _, suf := range timeUnitSuffixes {
				if strings.HasSuffix(name.Name, suf) && len(name.Name) > len(suf) {
					rc.addNode(vs, fmt.Sprintf("var %s is of type time.Duration; don't use unit-specific suffix \"%s\"", name.Name, suf), 0.9)
					break
				}
			}
		}
		return true
	})
}

func ruleUnexportedReturn(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || !ast.IsExported(fd.Name.Name) || fd.Type == nil || fd.Type.Results == nil {
			continue
		}
		kind := "func"
		if fd.Recv != nil {
			kind = "method"
		}
		for _, field := range fd.Type.Results.List {
			checkUnexpType(rc, field.Type, fd, kind)
		}
	}
}

func checkUnexpType(rc *RuleContext, e ast.Expr, fd *ast.FuncDecl, kind string) {
	switch t := e.(type) {
	case *ast.Ident:
		if !ast.IsExported(t.Name) && t.Name != "_" {
			pkgName := rc.File.AST.Name.Name
			rc.addNode(t, fmt.Sprintf("exported %s %s returns unexported type %s.%s, which can be annoying to use", kind, fd.Name.Name, pkgName, t.Name), 0.8)
		}
	case *ast.StarExpr:
		if id, ok := t.X.(*ast.Ident); ok && !ast.IsExported(id.Name) {
			pkgName := rc.File.AST.Name.Name
			rc.addNode(t, fmt.Sprintf("exported %s %s returns unexported type *%s.%s, which can be annoying to use", kind, fd.Name.Name, pkgName, id.Name), 0.8)
		}
	}
}

func ruleUnreachableCode(rc *RuleContext) {
	// check statement lists
	checkList := func(list []ast.Stmt) {
		for i, stmt := range list {
			if i >= len(list)-1 {
				break
			}
			// if next is labeled, skip
			if _, isLbl := list[i+1].(*ast.LabeledStmt); isLbl {
				continue
			}
			isTerm := false
			switch s := stmt.(type) {
			case *ast.ReturnStmt:
				isTerm = true
			case *ast.BranchStmt:
				if s.Tok == token.BREAK || s.Tok == token.CONTINUE || s.Tok == token.GOTO {
					isTerm = true
				}
			case *ast.ExprStmt:
				if call, ok := s.X.(*ast.CallExpr); ok {
					if pkg, sel, ok := selectorPkgSel(call.Fun); ok && pkg == "os" && sel == "Exit" {
						isTerm = true
					}
				}
			}
			if isTerm {
				rc.addNode(stmt, "unreachable code after this statement", 1)
				break
			}
		}
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BlockStmt:
			checkList(node.List)
		case *ast.CaseClause:
			checkList(node.Body)
		case *ast.CommClause:
			checkList(node.Body)
		}
		return true
	})
}

func ruleUnusedParameter(rc *RuleContext) {
	checkFunc := func(body *ast.BlockStmt, typ *ast.FuncType) {
		if body == nil || typ == nil || typ.Params == nil {
			return
		}
		for _, field := range typ.Params.List {
			for _, name := range field.Names {
				if name.Name == "_" {
					continue
				}
				used := false
				ast.Inspect(body, func(n ast.Node) bool {
					if used {
						return false
					}
					if id, ok := n.(*ast.Ident); ok && id.Name == name.Name && id != name {
						used = true
						return false
					}
					return true
				})
				if !used {
					rc.addNode(name, fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name), 1)
				}
			}
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			checkFunc(fd.Body, fd.Type)
		}
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if fl, ok := n.(*ast.FuncLit); ok {
			checkFunc(fl.Body, fl.Type)
		}
		return true
	})
}

func ruleVarDeclaration(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		gen, ok := n.(*ast.GenDecl)
		if !ok || gen.Tok != token.VAR {
			return true
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || vs.Type == nil || len(vs.Names) != 1 || len(vs.Values) != 1 {
				continue
			}
			typeSrc := rc.source(vs.Type)
			rc.addNode(vs.Type, fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeSrc, vs.Names[0].Name), 0.8)
		}
		return true
	})
}

