		rc.addNode(ident, fmt.Sprintf("%s %s should be %s", kind, name, should), 0.8)
	}
}

func snakeToCamel(name string) string {
	parts := strings.Split(name, "_")
	var b strings.Builder
	for i, part := range parts {
		if i == 0 {
			b.WriteString(part)
			continue
		}
		if part == "" {
			b.WriteString("_")
			continue
		}
		r := []rune(part)
		r[0] = unicode.ToUpper(r[0])
		b.WriteString(string(r))
	}
	return b.String()
}

func splitNameWords(name string) []string {
	var words []string
	runes := []rune(name)
	start := 0
	for i := 1; i < len(runes); i++ {
		prev := runes[i-1]
		cur := runes[i]
		var next rune
		if i+1 < len(runes) {
			next = runes[i+1]
		}
		shouldBreak := false
		if unicode.IsUpper(cur) && (unicode.IsLower(prev) || unicode.IsDigit(prev)) {
			shouldBreak = true
		} else if unicode.IsUpper(cur) && unicode.IsUpper(prev) && next != 0 && unicode.IsLower(next) {
			shouldBreak = true
		}
		if shouldBreak {
			words = append(words, string(runes[start:i]))
			start = i
		}
	}
	words = append(words, string(runes[start:]))
	return words
}

func applyInitialisms(name string, vcfg varNamingConfig) (string, bool) {
	words := splitNameWords(name)
	bad := false
	var out []string
	isExported := len(name) > 0 && unicode.IsUpper([]rune(name)[0])
	for idx, w := range words {
		upper := strings.ToUpper(w)
		expected := upper
		isInit := defaultInitialisms[upper] || vcfg.block[upper]
		prefixUpper := ""
		if !isInit && len(w) > 1 && (strings.HasSuffix(w, "s") || strings.HasSuffix(w, "S")) {
			prefixUpper = strings.ToUpper(w[:len(w)-1])
			if defaultInitialisms[prefixUpper] || vcfg.block[prefixUpper] {
				isInit = true
				expected = strings.ToUpper(w)
			}
		}
		if !isInit {
			out = append(out, w)
			continue
		}
		if vcfg.allow[upper] || (prefixUpper != "" && vcfg.allow[prefixUpper]) {
			out = append(out, w)
			continue
		}
		if w == expected {
			out = append(out, w)
			continue
		}
		if idx == 0 && !isExported && w == strings.ToLower(w) {
			out = append(out, w)
			continue
		}
		bad = true
		out = append(out, expected)
	}
	return strings.Join(out, ""), bad
}

func ruleVarNaming(rc *RuleContext) {
	// package name
	if rc.File.AST.Name != nil {
		pkgName := rc.File.AST.Name.Name
		if strings.Contains(pkgName, "_") {
			rc.addPos(rc.File.AST.Name.Pos(), rc.File.AST.Name.End(), "don't use an underscore in package name", 1, "naming", "")
		}
	}
	handledParams := map[*ast.Ident]bool{}
	// Declarations
	for _, decl := range rc.File.AST.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			kind := "func"
			if d.Recv != nil {
				kind = "method"
			}
			checkName(rc, d.Name, kind)
			if d.Type != nil {
				if d.Type.Params != nil {
					for _, field := range d.Type.Params.List {
						for _, n := range field.Names {
							handledParams[n] = true
							checkName(rc, n, "func parameter")
						}
					}
				}
				if d.Type.Results != nil {
					for _, field := range d.Type.Results.List {
						for _, n := range field.Names {
							handledParams[n] = true
							checkName(rc, n, "func result")
						}
					}
				}
			}
		case *ast.GenDecl:
			// handled in generic inspect below to include local GenDecls too
			_ = d
		}
	}
	// Generic inspection for specs, struct fields, short vars, range vars
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.GenDecl:
			for _, spec := range node.Specs {
				switch sp := spec.(type) {
				case *ast.ValueSpec:
					kind := "var"
					if node.Tok == token.CONST {
						kind = "const"
					}
					for _, name := range sp.Names {
						checkName(rc, name, kind)
					}
				case *ast.TypeSpec:
					checkName(rc, sp.Name, "type")
				case *ast.ImportSpec:
					// not checked
				}
			}
		case *ast.StructType:
			if node.Fields != nil {
				for _, field := range node.Fields.List {
					for _, name := range field.Names {
						checkName(rc, name, "struct field")
					}
				}
			}
		case *ast.RangeStmt:
			if node.Tok == token.DEFINE {
				if id, ok := node.Key.(*ast.Ident); ok {
					checkName(rc, id, "range var")
				}
				if id, ok := node.Value.(*ast.Ident); ok {
					checkName(rc, id, "range var")
				}
			}
			// avoid double counting assign below (RangeStmt isn't Assign)
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						checkName(rc, id, "var")
					}
				}
			}
		}
		return true
	})
	_ = handledParams
}
