{"command":"cat > rules_batch1.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	registerRule("bool-literal-in-expr", "style", ruleBoolLiteral)
	registerRule("empty-lines", "style", ruleEmptyLines)
	registerRule("redundant-build-tag", "style", ruleRedundantBuildTag)
	registerRule("use-any", "naming", ruleUseAny)
	registerRule("string-of-int", "", ruleStringOfInt)
	registerRule("call-to-gc", "bad practice", ruleCallToGC)
	registerRule("deep-exit", "bad practice", ruleDeepExit)
	registerRule("defer", "bad practice", ruleDefer)
	registerRule("flag-parameter", "bad practice", ruleFlagParameter)
	registerRule("get-return", "logic", ruleGetReturn)
	registerRule("modifies-value-receiver", "", ruleModifiesValueReceiver)
	registerRule("nested-structs", "style", ruleNestedStructs)
	registerRule("unconditional-recursion", "logic", ruleUnconditionalRecursion)
	registerRule("useless-break", "", ruleUselessBreak)
	registerRule("useless-fallthrough", "style", ruleUselessFallthrough)
	registerRule("bare-return", "", ruleBareReturn)
	registerRule("early-return", "", ruleEarlyReturn)
	registerRule("unnecessary-stmt", "style", ruleUnnecessaryStmt)
}

func isBoolLit(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && (id.Name == "true" || id.Name == "false")
}
func ruleBoolLiteral(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch be.Op {
		case token.EQL, token.NEQ, token.LAND, token.LOR:
			if isBoolLit(be.X) || isBoolLit(be.Y) {
				rc.addNode(be, "omit Boolean literal in expression", 1)
			}
		}
		return true
	})
}

func ruleEmptyLines(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) == 0 {
			return true
		}
		lbraceLine := rc.File.Fset.Position(block.Lbrace).Line
		rbraceLine := rc.File.Fset.Position(block.Rbrace).Line
		firstLine := rc.File.Fset.Position(block.List[0].Pos()).Line
		lastEndLine := rc.File.Fset.Position(block.List[len(block.List)-1].End()).Line
		if firstLine > lbraceLine+1 {
			rc.addNode(block, "extra empty line at the start of a block", 1)
		}
		if lastEndLine < rbraceLine-1 {
			rc.addNode(block, "extra empty line at the end of a block", 1)
		}
		return true
	})
}

func ruleRedundantBuildTag(rc *RuleContext) {
	hasGoBuild := false
	var plusBuild []*ast.Comment
	for _, cg := range rc.File.AST.Comments {
		for _, c := range cg.List {
			txt := strings.TrimSpace(c.Text)
			if strings.HasPrefix(txt, "//go:build") {
				hasGoBuild = true
			}
			if strings.HasPrefix(txt, "// +build") {
				plusBuild = append(plusBuild, c)
			}
		}
	}
	if !hasGoBuild {
		return
	}
	for _, c := range plusBuild {
		rc.addNode(c, `The build tag "// +build" is redundant since Go 1.17 and can be removed`, 1)
	}
}

func ruleUseAny(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		it, ok := n.(*ast.InterfaceType)
		if !ok {
			return true
		}
		if it.Methods == nil || len(it.Methods.List) == 0 {
			rc.addNode(it, "since Go 1.18 'interface{}' can be replaced by 'any'", 1)
		}
		return true
	})
}

func ruleStringOfInt(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		id, ok := call.Fun.(*ast.Ident)
		if !ok || id.Name != "string" {
			return true
		}
		arg := call.Args[0]
		typ := rc.typeOf(arg)
		flag := false
		if typ != nil {
			if basic, ok := typ.Underlying().(*types.Basic); ok {
				switch basic.Kind() {
				case types.Int, types.Int8, types.Int16, types.Int32, types.Int64, types.Uint, types.Uint8, types.Uint16, types.Uint32, types.Uint64, types.Uintptr, types.UntypedInt:
					// exclude byte/rune named types: their Basic name is "uint8"/"int32" but type name differs
					tn := typ.String()
					if tn == "byte" || tn == "rune" || tn == "uint8" && rc.source(arg) == "" {
						_ = tn
					}
					if basic.Kind() == types.Uint8 && typ.String() == "byte" {
						flag = false
					} else if basic.Kind() == types.Int32 && typ.String() == "rune" {
						flag = false
					} else {
						flag = true
					}
				}
			}
		} else if lit, ok := arg.(*ast.BasicLit); ok && lit.Kind == token.INT {
			flag = true
		}
		if flag {
			rc.addNode(call, "dubious conversion of an integer into a string, use strconv.Itoa", 1)
		}
		return true
	})
}

func ruleCallToGC(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if pkg, sel, ok := selectorPkgSel(call.Fun); ok && pkg == "runtime" && sel == "GC" {
			rc.addNode(call, "explicit call to the garbage collector", 1)
		}
		return true
	})
}

func ruleDeepExit(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		if fd.Name.Name == "main" || fd.Name.Name == "init" {
			continue
		}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			if pkg, sel, ok := selectorPkgSel(call.Fun); ok {
				if (pkg == "os" && sel == "Exit") || (pkg == "log" && (sel == "Fatal" || sel == "Fatalf" || sel == "Fatalln")) {
					rc.addNode(call, fmt.Sprintf("calls to %s.%s only in main() or init() functions", pkg, sel), 1)
				}
			}
			return true
		})
	}
}

func ruleDefer(rc *RuleContext) {
	// Track whether a defer is inside a loop (within same function)
	var stack []ast.Node
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return false
		}
		if ds, ok := n.(*ast.DeferStmt); ok {
			inLoop := false
			crossedFunc := false
			for i := len(stack) - 1; i >= 0; i-- {
				switch stack[i].(type) {
				case *ast.FuncLit:
					crossedFunc = true
				case *ast.ForStmt, *ast.RangeStmt:
					if !crossedFunc {
						inLoop = true
					}
				}
				if inLoop {
					break
				}
			}
			if inLoop {
				rc.addNode(ds, "prefer not to defer inside loops", 1)
			}
		}
		stack = append(stack, n)
		return true
	})
}

func ruleFlagParameter(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil || fd.Type == nil || fd.Type.Params == nil {
			continue
		}
		// collect bool params
		type bp struct {
			field *ast.Field
			name  string
		}
		var params []bp
		for _, field := range fd.Type.Params.List {
			if id, ok := field.Type.(*ast.Ident); ok && id.Name == "bool" {
				for _, n := range field.Names {
					params = append(params, bp{field, n.Name})
				}
			}
		}
		if len(params) == 0 {
			continue
		}
		// find if conditions
		used := map[string]*ast.Field{}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			ifStmt, ok := n.(*ast.IfStmt)
			if !ok {
				return true
			}
			cond := stripParens(ifStmt.Cond)
			if id, ok := cond.(*ast.Ident); ok {
				for _, p := range params {
					if p.name == id.Name {
						used[p.name] = p.field
					}
				}
			}
			return true
		})
		// report in param order, once per field
		reported := map[*ast.Field]bool{}
		for _, p := range params {
			if f, ok := used[p.name]; ok && !reported[f] {
				reported[f] = true
				rc.addNode(f, fmt.Sprintf("parameter '%s' seems to be a control flag, avoid control coupling", p.name), 1)
			}
		}
	}
}

func stripParens(e ast.Expr) ast.Expr {
	for {
		if p, ok := e.(*ast.ParenExpr); ok {
			e = p.X
		} else {
			return e
		}
	}
}

func ruleGetReturn(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		name := fd.Name.Name
		if !strings.HasPrefix(name, "Get") || len(name) <= 3 {
			continue
		}
		// 4th char must be uppercase? observed GetX; Get alone excluded by length
		r := []rune(name)
		if len(r) > 3 && r[3] >= 'a' && r[3] <= 'z' {
			// Getsomething might still be getter? original check may be different; skip lower for now
			continue
		}
		numResults := 0
		if fd.Type != nil && fd.Type.Results != nil {
			for _, f := range fd.Type.Results.List {
				if len(f.Names) == 0 {
					numResults++
				} else {
					numResults += len(f.Names)
				}
			}
		}
		if numResults == 0 {
			rc.addNode(fd, fmt.Sprintf("function '%s' seems to be a getter but it does not return any result", name), 0.8)
		}
	}
}

func exprRootIdent(e ast.Expr) *ast.Ident {
	switch t := e.(type) {
	case *ast.Ident:
		return t
	case *ast.SelectorExpr:
		return exprRootIdent(t.X)
	case *ast.IndexExpr:
		return exprRootIdent(t.X)
	case *ast.IndexListExpr:
		return exprRootIdent(t.X)
	case *ast.StarExpr:
		return exprRootIdent(t.X)
	}
	return nil
}

func ruleModifiesValueReceiver(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 || fd.Body == nil {
			continue
		}
		recvField := fd.Recv.List[0]
		if _, isStar := recvField.Type.(*ast.StarExpr); isStar {
			continue
		}
		// receiver type may be Index etc; if it contains *? Star is top only.
		if len(recvField.Names) == 0 {
			continue
		}
		recvName := recvField.Names[0].Name
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			switch stmt := n.(type) {
			case *ast.AssignStmt:
				for _, lhs := range stmt.Lhs {
					if root := exprRootIdent(lhs); root != nil && root.Name == recvName {
						// need LHS be selector/index based on receiver, or receiver itself
						if _, isIdent := lhs.(*ast.Ident); !isIdent {
							rc.addNode(stmt, "suspicious assignment to a by-value method receiver", 1)
						} else {
							rc.addNode(stmt, "suspicious assignment to a by-value method receiver", 1)
						}
						break
					}
				}
			case *ast.IncDecStmt:
				if root := exprRootIdent(stmt.X); root != nil && root.Name == recvName {
					rc.addNode(stmt, "suspicious assignment to a by-value method receiver", 1)
				}
			}
			return true
		})
	}
}

func ruleNestedStructs(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		st, ok := n.(*ast.StructType)
		if !ok || st.Fields == nil {
			return true
		}
		for _, field := range st.Fields.List {
			if inner, ok := field.Type.(*ast.StructType); ok {
				rc.addNode(inner, "no nested structs are allowed", 1)
			}
			if inner, ok := field.Type.(*ast.StarExpr); ok {
				if _ , ok2 := inner.X.(*ast.StructType); ok2 {
					// pointer to nested struct? not sure; skip
				}
			}
		}
		return true
	})
}

func ruleUnconditionalRecursion(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		// walk with condition tracking: calls directly in unconditional context
		var visit func(n ast.Node, conditional bool)
		// Simpler: inspect and determine if call is inside If/For/Range/Switch/Case etc using stack
		var stack []ast.Node
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if n == nil {
				stack = stack[:len(stack)-1]
				return false
			}
			if call, ok := n.(*ast.CallExpr); ok {
				isSelf := false
				if id, ok := call.Fun.(*ast.Ident); ok && id.Name == fd.Name.Name && fd.Recv == nil {
					isSelf = true
				}
				if sel, ok := call.Fun.(*ast.SelectorExpr); ok && fd.Recv != nil && sel.Sel.Name == fd.Name.Name {
					// method call on any receiver counts?
					isSelf = true
				}
				if isSelf {
					conditional := false
					for _, anc := range stack {
						switch anc.(type) {
						case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.CaseClause, *ast.BinaryExpr:
							// BinaryExpr ancestor for && ||: if call is in RHS of conditional logic? approximate only if ancestor binary op is &&/||
							conditional = true
						}
					}
					// BinaryExpr check refine: if any binary ancestor has LAND/LOR
					if conditional {
						// verify binary case: if conditional was set only by If/For etc it's fine
					} else {
						rc.addNode(call, "unconditional recursive call", 0.8)
					}
				}
			}
			stack = append(stack, n)
			return true
		})
		_ = visit
	}
}

func ruleUselessBreak(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		clause, ok := n.(*ast.CaseClause)
		if !ok || len(clause.Body) == 0 {
			return true
		}
		last := clause.Body[len(clause.Body)-1]
		if bs, ok := last.(*ast.BranchStmt); ok && bs.Tok == token.BREAK {
			rc.addNode(bs, "useless break in case clause", 1)
		}
		return true
	})
}

func ruleUselessFallthrough(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		list := sw.Body.List
		for i, stmt := range list {
			clause, ok := stmt.(*ast.CaseClause)
			if !ok || i >= len(list)-1 || len(clause.Body) != 1 {
				continue
			}
			if bs, ok := clause.Body[0].(*ast.BranchStmt); ok && bs.Tok == token.FALLTHROUGH {
				rc.addNode(bs, `this "fallthrough" can be removed by consolidating this case clause with the next one`, 1)
			}
		}
		// TypeSwitch same structure but Body list also CaseClause? TypeSwitch body cases are CaseClause too handled above when inspecting switch only. Also inspect clauses directly below.
		return true
	})
	// also for type switches, fallthrough not allowed in Go, ignore
}

func ruleBareReturn(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil || fd.Type == nil || fd.Type.Results == nil {
			continue
		}
		hasNamed := false
		for _, f := range fd.Type.Results.List {
			if len(f.Names) > 0 {
				hasNamed = true
			}
		}
		if !hasNamed {
			continue
		}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if ret, ok := n.(*ast.ReturnStmt); ok && len(ret.Results) == 0 {
				rc.addNode(ret, "avoid using bare returns, please add return expressions", 1)
			}
			return true
		})
	}
	// func lits with named results?
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		fl, ok := n.(*ast.FuncLit)
		if !ok || fl.Type == nil || fl.Type.Results == nil {
			return true
		}
		hasNamed := false
		for _, f := range fl.Type.Results.List {
			if len(f.Names) > 0 {
				hasNamed = true
			}
		}
		if !hasNamed {
			return true
		}
		ast.Inspect(fl.Body, func(m ast.Node) bool {
			if ret, ok := m.(*ast.ReturnStmt); ok && len(ret.Results) == 0 {
				// avoid double-reporting FuncDecl bodies: FuncLit inside FuncDecl would be reported in both loops if decl traversal visited lit
				// dedup via position check skip if already? Accept potential duplicate for now (rare)
				rc.addNode(ret, "avoid using bare returns, please add return expressions", 1)
			}
			return true
		})
		return true
	})
}

func ruleEarlyReturn(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		// else block ends with return? observed else { return } single
		last := lastStmt(elseBlock)
		if _, isRet := last.(*ast.ReturnStmt); isRet {
			rc.addNode(ifStmt, "if c { ... } else { ... return } can be simplified to if !c { ... return } ...", 1)
		}
		return true
	})
}

func ruleUnnecessaryStmt(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) == 0 {
			return true
		}
		last := block.List[len(block.List)-1]
		if ret, ok := last.(*ast.ReturnStmt); ok && len(ret.Results) == 0 {
			// Only if this block is a function body with no return values? Probe shows void function trailing return.
			// Determine parent function: we can't easily know here; Inspect ancestors not available.
			// Heuristic: report all trailing bare returns in blocks that are function bodies by checking in FuncDecl loop below instead.
			_ = ret
		}
		return true
	})
	// function bodies
	checkBody := func(body *ast.BlockStmt, typ *ast.FuncType) {
		if body == nil || len(body.List) == 0 || typ == nil {
			return
		}
		// only void functions
		if typ.Results != nil && len(typ.Results.List) > 0 {
			return
		}
		last := body.List[len(body.List)-1]
		if ret, ok := last.(*ast.ReturnStmt); ok && len(ret.Results) == 0 {
			rc.addNode(ret, "omit unnecessary return statement", 1)
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			checkBody(fd.Body, fd.Type)
		}
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if fl, ok := n.(*ast.FuncLit); ok {
			checkBody(fl.Body, fl.Type)
		}
		return true
	})
}
