import subprocess, tempfile, pathlib, json
ORACLE="/workspace/executable"; MINE="/tmp/myrevive"
def run(exe, rule, code, args=None, filename="a.go", extra_files=None, cfg_extra=""):
    d=tempfile.mkdtemp()
    pathlib.Path(d, filename).write_text(code)
    if extra_files:
        for n,c in extra_files.items():
            p=pathlib.Path(d,n); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(c)
    cfg=f"[rule.{rule}]
"
    if args is not None: cfg+=f"arguments = {args}
"
    cfg+=cfg_extra
    pathlib.Path(d,"c.toml").write_text(cfg)
    r=subprocess.run([exe,"-config","c.toml","-formatter","json","./..."], cwd=d, capture_output=True, text=True)
    if r.returncode!=0:
        return (r.returncode, r.stderr.strip())
    data=json.loads(r.stdout) or []
    out=[]
    for f in data:
        s=f['Position']['Start']; e=f['Position']['End']
        out.append((s['Filename'],s['Line'],s['Column'],e['Line'],e['Column'],s['Offset'],e['Offset'],f['RuleName'],f['Category'],f['Confidence'],f['Failure'],f['ReplacementLine']))
    return (0, sorted(out))
def compare(cases):
    bad=0
    for case in cases:
        rule,code = case[0],case[1]
