func countParams(typ *ast.FuncType) int {
	if typ == nil || typ.Params == nil {
		return 0
	}
	n := 0
	for _, f := range typ.Params.List {
		if len(f.Names) == 0 {
			n++
		} else {
			n += len(f.Names)
		}
	}
	return n
}
func countResults(typ *ast.FuncType) int {
	if typ == nil || typ.Results == nil {
		return 0
	}
	n := 0
	for _, f := range typ.Results.List {
		if len(f.Names) == 0 {
			n++
		} else {
			n += len(f.Names)
		}
	}
	return n
}

func ruleArgumentLimit(rc *RuleContext) {
	max := intArg(rc.Rule.cfg, 8)
	check := func(node ast.Node, typ *ast.FuncType, name string) {
		got := countParams(typ)
		if got > max {
			rc.addPos(node.Pos(), node.End(), fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", max, got), 1, rc.Rule.Cat, "")
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			check(fd, fd.Type, fd.Name.Name)
		}
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if fl, ok := n.(*ast.FuncLit); ok {
			check(fl, fl.Type, "")
		}
		return true
	})
}

