	total := 0
	// Stack tracking nesting and nodes. Use recursive traversal via Inspect with explicit stack of (node, nestingAtEntry) can't be done easily,
	// so implement recursive walk using reflection-like child enumeration via ast.Inspect collecting direct children with a helper that walks and prunes.
	// We implement recursion by using a function that enumerates children by inspecting and cutting after direct children are recorded using depth tracking.
	type frame struct{ nesting int }
	// Recursive implementation using manual stack of iterators is overkill; use direct recursion with childNodesReal.
	var visit func(n ast.Node, nesting int)
	visit = func(n ast.Node, nesting int) {
		if n == nil {
			return
		}
		newNesting := nesting
		switch t := n.(type) {
		case *ast.IfStmt:
			total += 1 + nesting
			newNesting = nesting + 1
			if t.Init != nil { visit(t.Init, nesting) }
			if t.Cond != nil { visit(t.Cond, nesting) }
			if t.Body != nil { visit(t.Body, newNesting) }
			if t.Else != nil {
				if elseIf, ok := t.Else.(*ast.IfStmt); ok {
					total += 1
					if elseIf.Init != nil { visit(elseIf.Init, nesting) }
					if elseIf.Cond != nil { visit(elseIf.Cond, nesting) }
					if elseIf.Body != nil { visit(elseIf.Body, newNesting) }
					if elseIf.Else != nil { visit(elseIf.Else, nesting) }
				} else {
					total += 1
					visit(t.Else, newNesting)
				}
			}
			return
