			newNesting = nesting + 1
		case *ast.FuncLit:
			newNesting = nesting + 1
		}
		for _, child := range childNodesReal(n) {
			visit(child, newNesting)
		}
	}
	visit(node, 0)
	total += countBoolSequences(node)
	return total
}

func childNodesReal(n ast.Node) []ast.Node {
	// Collect direct children by walking the subtree and recording nodes whose path length is 1.
	// Use ast.Inspect with depth tracking: Inspect calls in pre-order and nil markers for exits.
	var children []ast.Node
	depth := 0
	ast.Inspect(n, func(c ast.Node) bool {
		if c == nil {
			depth--
			return false
		}
		depth++
		if depth == 2 {
			children = append(children, c)
			// do not descend into this child in this collection pass
			// Returning true would descend and depth would go >2, but we manage by allowing and ignoring >2.
			return true
		}
		return true
	})
	// The above collects also deeper nodes as depth>2 ignored in code? Actually children only appended at depth==2.
	var out []ast.Node
	// Re-run with proper pruning: we need to prevent Inspect from descending into depth2 nodes' children being counted - they are not appended because depth>2.
	out = append(out, children...)
	return out
}

