func cyclomaticComplexity(fd *ast.FuncDecl, fl *ast.FuncLit) int {
	complexity := 1
	var body *ast.BlockStmt
	if fd != nil {
		body = fd.Body
	} else {
		body = fl.Body
	}
	if body == nil {
		return complexity
	}
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt:
			complexity++
		case *ast.CaseClause:
			// count cases with expressions (not default)
			if node.List != nil {
				complexity++
			}
		case *ast.CommClause:
			if node.Comm != nil {
				complexity++
			}
		case *ast.BinaryExpr:
			if node.Op == token.LAND || node.Op == token.LOR {
				complexity++
			}
		}
		return true
	})
	return complexity
}

func ruleCyclomatic(rc *RuleContext) {
	max := intArg(rc.Rule.cfg, 10)
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		c := cyclomaticComplexity(fd, nil)
		if c > max {
			rc.addNode(fd, fmt.Sprintf("function %s has cyclomatic complexity %d (> max enabled %d)", fd.Name.Name, c, max), 1)
		}
	}
}

func cognitiveComplexityOf(node ast.Node) int {
	// Simplified Sonar cognitive complexity
	total := 0
	var visit func(n ast.Node, nesting int)
	visit = func(n ast.Node, nesting int) {
		if n == nil {
			return
		}
		// We'll use Inspect with manual stack is complex; use recursive via ast.Inspect and tracking increments in a closure based on node type and nesting param by re-walking children.
		// Instead implement direct recursion over children using ast.Inspect for children with adjusted nesting when n is a nesting increaser.
		increment := 0
		newNesting := nesting
		switch t := n.(type) {
		case *ast.IfStmt:
			// Determine if this is else-if: parent handling not available; approximate: if nodes are handled separately in recursion below for Else.
			increment = 1 + nesting
			newNesting = nesting + 1
			total += increment
			// visit init, cond at same nesting, body at new nesting, else specially
			if t.Init != nil {
				visit(t.Init, nesting)
			}
			if t.Cond != nil {
				visit(t.Cond, nesting)
			}
			if t.Body != nil {
				visit(t.Body, newNesting)
			}
			if t.Else != nil {
				if elseIf, ok := t.Else.(*ast.IfStmt); ok {
					// else-if gets +1 without nesting increase
					total += 1
					if elseIf.Init != nil {
						visit(elseIf.Init, nesting)
					}
					if elseIf.Cond != nil {
						visit(elseIf.Cond, nesting)
					}
					if elseIf.Body != nil {
						visit(elseIf.Body, newNesting)
					}
					if elseIf.Else != nil {
						visit(elseIf.Else, nesting)
					}
				} else {
					total += 1 // else
					visit(t.Else, newNesting)
				}
			}
			return
		case *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
			total += 1 + nesting
			newNesting = nesting + 1
		case *ast.BinaryExpr:
			// handled below for sequences: we count at top? Simplify counting in generic child walk: if op is &&/|| add 1 if parent not same op - not tracked.
			// We'll count each binary operator node individually except nested same op counted once per sequence in a separate pass; for now do not add here.
		case *ast.FuncLit:
			// nested function increases nesting for its body but no increment itself
			newNesting = nesting + 1
		}
		// generic children
		for _, child := range childNodes(n) {
			visit(child, newNesting)
		}
	}
	visit(node, 0)
	// Add boolean operator sequences
	total += countBoolSequences(node)
	return total
}

func childNodes(n ast.Node) []ast.Node {
	var out []ast.Node
	ast.Inspect(n, func(c ast.Node) bool {
		if c == n {
			return true
		}
		// We need only direct children; ast.Inspect doesn't provide depth easily. Use a trick: collect nodes and stop at first level by tracking?
		return false
	})
	// The above approach doesn't work; implement direct children via reflection-free type switches for common nodes fallback: use a stack walk collecting immediate children by comparing ?
	// Simpler: return all descendants and let visit handle? That would double count. Instead use custom: we will reimplement visit using ast.Inspect in cognitiveComplexityOf2.
	_ = out
	return nil
}

func countBoolSequences(node ast.Node) int {
	// Count sequences of && / || : each maximal sequence of same operator adds 1
	count := 0
	// Walk binary exprs: if a BinaryExpr with LAND/LOR whose parent binary is not same op, count 1. Need parent map.
	parents := map[ast.Node]ast.Node{}
	var stack []ast.Node
	ast.Inspect(node, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return false
		}
		if len(stack) > 0 {
			parents[n] = stack[len(stack)-1]
		}
		if be, ok := n.(*ast.BinaryExpr); ok && (be.Op == token.LAND || be.Op == token.LOR) {
			p := parents[n]
			if pbe, ok := p.(*ast.BinaryExpr); !ok || pbe.Op != be.Op {
				count++
			}
		}
		stack = append(stack, n)
		return true
	})
	return count
}

func ruleCognitiveComplexity(rc *RuleContext) {
	max := intArg(rc.Rule.cfg, 7)
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		c := cognitiveComplexityOf(fd)
		if c > max {
			rc.addNode(fd, fmt.Sprintf("function %s has cognitive complexity %d (> max enabled %d)", fd.Name.Name, c, max), 1)
		}
	}
}

func ruleMaxControlNesting(rc *RuleContext) {
	max := intArg(rc.Rule.cfg, 5)
	// Walk function bodies tracking control nesting depth
	var walk func(n ast.Node, depth int, inFunc bool)
	// Use stack inspection
	var stack []ast.Node
	depthOf := func() int {
		d := 0
		for _, anc := range stack {
			switch anc.(type) {
			case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
				d++
			}
		}
		return d
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return false
		}
		switch n.(type) {
		case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
			// depth of this node is ancestors control count +1
			ancDepth := depthOf()
			// stack currently doesn't include n
			if ancDepth+1 > max {
				rc.addNode(n, fmt.Sprintf("control flow nesting exceeds %d", max), 1)
			}
		}
		stack = append(stack, n)
		return true
	})
	_ = walk
}

func ruleFunctionLength(rc *RuleContext) {
	maxStmts := 0
	maxLines := 0
	if rc.Rule.cfg != nil && len(rc.Rule.cfg.Arguments) == 2 {
		if v, ok := rc.Rule.cfg.Arguments[0].(int64); ok {
			maxStmts = int(v)
		}
		if v, ok := rc.Rule.cfg.Arguments[1].(int64); ok {
			maxLines = int(v)
		}
	} else {
		// defaults unknown; use large to avoid false positives when no args? Original with enableAll uses defaults (likely 50, 75?). Set 50 statements, 75 lines?
		maxStmts = 50
		maxLines = 75
	}
	check := func(node ast.Node, body *ast.BlockStmt) {
		if body == nil {
			return
		}
		stmtCount := 0
		lines := map[int]bool{}
		ast.Inspect(body, func(n ast.Node) bool {
			if stmt, ok := n.(ast.Stmt); ok {
				if _, isBlock := n.(*ast.BlockStmt); !isBlock {
					stmtCount++
				}
			}
			if n != nil {
				pos := rc.File.Fset.Position(n.Pos())
				if pos.Line > 0 {
					// lines counting statements only? We'll add lines for statement nodes below
				}
			}
			return true
		})
		// lines: count distinct lines that contain a statement start (excluding block braces)
		ast.Inspect(body, func(n ast.Node) bool {
			if stmt, ok := n.(ast.Stmt); ok {
				if _, isBlock := n.(*ast.BlockStmt); !isBlock {
					lines[rc.File.Fset.Position(stmt.Pos()).Line] = true
				}
			}
			return true
		})
		lineCount := len(lines)
		if maxStmts > 0 && stmtCount > maxStmts {
			rc.addPos(node.Pos(), node.End(), fmt.Sprintf("maximum number of statements per function exceeded; max %d but got %d", maxStmts, stmtCount), 1, rc.Rule.Cat, "")
		}
		if maxLines > 0 && lineCount > maxLines {
			rc.addPos(node.Pos(), node.End(), fmt.Sprintf("maximum number of lines per function exceeded; max %d but got %d", maxLines, lineCount), 1, rc.Rule.Cat, "")
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			check(fd, fd.Body)
		}
	}
}

func ruleFileLengthLimit(rc *RuleContext) {
	var max int64 = -1
	skipComments := false
	skipBlank := false
	if rc.Rule.cfg != nil && len(rc.Rule.cfg.Arguments) > 0 {
		if m, ok := rc.Rule.cfg.Arguments[0].(map[string]interface{}); ok {
			if v, ok := m["max"].(int64); ok {
				max = v
			}
			if v, ok := m["skipComments"].(bool); ok {
				skipComments = v
			}
			if v, ok := m["skipBlankLines"].(bool); ok {
				skipBlank = v
			}
		}
	}
	if max < 0 {
		return
	}
	content := string(rc.File.Content)
	lines := strings.Split(content, "\n")
	// trailing newline pseudo line excluded if content ends with \n and last element empty? Original count: file "package a\nvar A...\n" with 5 lines counted 5 (not 6) - split gives 6 with final empty, so drop final empty.
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(content, "\n") {
		lines = lines[:len(lines)-1]
	}
	totalPhysical := len(lines)
	count := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if skipBlank && trimmed == "" {
			continue
		}
		if skipComments && (strings.HasPrefix(trimmed, "//") || strings.HasPrefix(trimmed, "/*") || strings.HasPrefix(trimmed, "*")) {
			continue
		}
		count++
	}
	if int64(count) > max {
		start := Position{Filename: rc.File.Display, Offset: 0, Line: totalPhysical, Column: 0}
		end := Position{Filename: "", Offset: 0, Line: 0, Column: 0}
		rc.addRaw(start, end, fmt.Sprintf("file length is %d lines, which exceeds the limit of %d", count, max), 1, rc.Rule.Cat, "")
	}
}

func ruleFileHeader(rc *RuleContext) {
	if rc.Rule.cfg == nil || len(rc.Rule.cfg.Arguments) == 0 {
		return
	}
	pattern, ok := rc.Rule.cfg.Arguments[0].(string)
	if !ok {
		return
	}
	re, err := regexp.Compile(pattern)
	if err != nil {
		return
	}
	// header is content before package keyword
	pkgPos := rc.File.Fset.Position(rc.File.AST.Package)
	// offset of package in content: use Fset file offset
	f := rc.File.Fset.File(rc.File.AST.Package)
	header := ""
	if f != nil {
		off := f.Offset(rc.File.AST.Package)
		if off >= 0 && off <= len(rc.File.Content) {
			header = string(rc.File.Content[:off])
		}
	}
	_ = pkgPos
	if !re.MatchString(header) {
		rc.addPos(rc.File.AST.Pos(), rc.File.AST.Name.End(), "the file doesn't have an appropriate header", 1, rc.Rule.Cat, "")
	}
}

func ruleFilenameFormat(rc *RuleContext) {
	if rc.Rule.cfg == nil || len(rc.Rule.cfg.Arguments) == 0 {
		return
	}
	format, ok := rc.Rule.cfg.Arguments[0].(string)
	if !ok {
		return
	}
	filename := rc.File.Display
	// base name
	base := filename
	if idx := strings.LastIndex(base, "/"); idx >= 0 {
		base = base[idx+1:]
	}
	nameNoExt := strings.TrimSuffix(base, ".go")
	matched := false
	switch format {
	case "snake_case":
		matched = regexp.MustCompile(`^[a-z0-9]+(_[a-z0-9]+)*$`).MatchString(nameNoExt)
	case "camelCase":
		matched = regexp.MustCompile(`^[a-z][a-zA-Z0-9]*$`).MatchString(nameNoExt)
	case "PascalCase":
		matched = regexp.MustCompile(`^[A-Z][a-zA-Z0-9]*$`).MatchString(nameNoExt)
	case "kebab-case":
		matched = regexp.MustCompile(`^[a-z0-9]+(-[a-z0-9]+)*$`).MatchString(nameNoExt)
	default:
		// treat as regex against full base filename
		if re, err := regexp.Compile(format); err == nil {
			matched = re.MatchString(base)
		} else {
			matched = false
		}
	}
	if !matched {
		rc.addPos(rc.File.AST.Name.Pos(), rc.File.AST.Name.End(), fmt.Sprintf("Filename %s is not of the format %s.", base, format), 1, rc.Rule.Cat, "")
	}
}

func ruleBannedCharacters(rc *RuleContext) {
	if rc.Rule.cfg == nil {
		return
	}
	var banned []string
	for _, a := range rc.Rule.cfg.Arguments {
		if s, ok := a.(string); ok {
			banned = append(banned, s)
		}
	}
	if len(banned) == 0 {
		return
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		id, ok := n.(*ast.Ident)
		if !ok {
			return true
		}
		for _, b := range banned {
			if b != "" && strings.Contains(id.Name, b) {
				rc.addNode(id, fmt.Sprintf("banned character found: %s", b), 1)
			}
		}
		return true
	})
}

func ruleCommentsDensity(rc *RuleContext) {
	if rc.Rule.cfg == nil || len(rc.Rule.cfg.Arguments) == 0 {
		return
	}
	minPct := intArg(rc.Rule.cfg, 0)
	// count comment lines and code lines
	content := string(rc.File.Content)
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(content, "\n") {
		lines = lines[:len(lines)-1]
	}
	commentLines := 0
	// Use AST comments to determine comment line numbers (distinct)
	commentLineSet := map[int]bool{}
	for _, cg := range rc.File.AST.Comments {
		for _, c := range cg.List {
			startLine := rc.File.Fset.Position(c.Pos()).Line
			endLine := rc.File.Fset.Position(c.End()).Line
			for l := startLine; l <= endLine; l++ {
				commentLineSet[l] = true
			}
		}
	}
	commentLines = len(commentLineSet)
	// code lines = total lines excluding comment lines? Probe: 1 comment, file 3 lines, message says 3 code lines - we need infer.
	// Alternative interpretation: code lines = number of lines that are not empty? Let's compute density as comment/(comment+code)
	// Our probe file: package a (code), // hi (comment), func ... (code) => code=2, comment=1 => density 33%, but original said 25% and "(1 comment lines for 3 code lines)"
	// That suggests code lines = 3 (maybe they count statements: package + 2 println statements =3). Statement counting - AST statements: FuncDecl body has 2 ExprStmt + package clause counts as 1.
	// Let's count code as: number of AST nodes lines? We'll count statements (excluding blocks) + package line as 1.
	codeLines := 1 // package?
	stmtLines := map[int]bool{}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if stmt, ok := n.(ast.Stmt); ok {
			if _, isBlock := n.(*ast.BlockStmt); !isBlock {
				stmtLines[rc.File.Fset.Position(stmt.Pos()).Line] = true
			}
		}
		return true
	})
	// stmtLines are distinct stmt lines; code lines for message = ? probe had statements on same line: 2 println on one line each counted as separate statement but said 3 code lines total (package+2 statements). So codeLines = 1 + number of statements (not distinct lines)
	numStmts := 0
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if stmt, ok := n.(ast.Stmt); ok {
			if _, isBlock := n.(*ast.BlockStmt); !isBlock {
				numStmts++
			}
		}
		return true
	})
	codeLines = codeLines + numStmts
	// But FuncDecl itself maybe counted? Our file: package 1 + ExprStmt 2 =3 matches message.
	total := commentLines + codeLines
	if total == 0 {
		return
	}
	density := 0
	if total > 0 {
		density = commentLines * 100 / total
	}
	if density < minPct {
		rc.addNode(rc.File.AST, fmt.Sprintf("the file has a comment density of %d%% (%d comment lines for %d code lines) but expected a minimum of %d%%", density, commentLines, codeLines, minPct), 1)
	}
}

func ruleAddConstant(rc *RuleContext) {
	// Configuration parsing: optional map with maxLitCount, allowStr, allowFloat, allowInt etc. Defaults for now:
	maxLitCount := int64(-1) // -1 means flag all? probing shows even single uses flagged when no args.
	allowStr := ""
	allowInt := ""
	allowFloat := ""
	if rc.Rule.cfg != nil && len(rc.Rule.cfg.Arguments) > 0 {
		if m, ok := rc.Rule.cfg.Arguments[0].(map[string]interface{}); ok {
			if v, ok := m["maxLitCount"].(string); ok {
				// it's a string in add-constant config per docs
				var parsed int64
				fmt.Sscanf(v, "%d", &parsed)
				maxLitCount = parsed
			} else if v, ok := m["maxLitCount"].(int64); ok {
				maxLitCount = v
			}
			if v, ok := m["allowStr"].(string); ok {
				allowStr = v
			}
			if v, ok := m["allowInt"].(string); ok {
				allowInt = v
			}
			if v, ok := m["allowFloat"].(string); ok {
				allowFloat = v
			}
		}
	}
	// Count literals occurrences in file (excluding const declarations)
	// First count
	type litInfo struct {
		node *ast.BasicLit
	}
	counts := map[string]int{}
	var lits []*ast.BasicLit
	var inspect func(n ast.Node, inConst bool)
	_ = inspect
	// Walk with stack to know if inside GenDecl CONST or inside a const ValueSpec or inside function const?
	var stack []ast.Node
	inConstDecl := func() bool {
		for _, anc := range stack {
			if gen, ok := anc.(*ast.GenDecl); ok && gen.Tok == token.CONST {
				return true
			}
		}
		return false
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return false
		}
		if lit, ok := n.(*ast.BasicLit); ok {
			if !inConstDecl() {
				// Only numeric literals (INT/FLOAT) ? add-constant also strings reported as magic? It says magic numbers.
				if lit.Kind == token.INT || lit.Kind == token.FLOAT {
					key := lit.Kind.String() + ":" + lit.Value
					counts[key]++
					lits = append(lits, lit)
				} else if lit.Kind == token.STRING {
					// strings may also be considered? We'll include only if allowed configs say - but original add-constant includes str/float/int separate
					// Probe shows numbers only tested; we'll also count strings as their own category? Keep for now not flag strings.
				}
			}
		}
		stack = append(stack, n)
		return true
	})
	allowed := func(lit *ast.BasicLit) bool {
		switch lit.Kind {
		case token.INT:
			if allowInt != "" {
				for _, part := range strings.Split(allowInt, ",") {
					if strings.TrimSpace(part) == lit.Value {
						return true
					}
				}
			}
			// common allowed values?
			if lit.Value == "0" || lit.Value == "1" || lit.Value == "-1" {
				// But probe showed 1 flagged. So no built-in allowance when no config? Keep false.
			}
		case token.FLOAT:
			if allowFloat != "" {
				for _, part := range strings.Split(allowFloat, ",") {
					if strings.TrimSpace(part) == lit.Value {
						return true
					}
				}
			}
		case token.STRING:
			if allowStr != "" {
				unq, _ := unquoteString(lit)
				for _, part := range strings.Split(allowStr, ",") {
					if strings.TrimSpace(part) == unq {
						return true
					}
				}
			}
		}
		return false
	}
	for _, lit := range lits {
		if allowed(lit) {
			continue
		}
		key := lit.Kind.String() + ":" + lit.Value
		if maxLitCount >= 0 && int64(counts[key]) <= maxLitCount {
			continue
		}
		// if maxLitCount is -1 (default with no args), original flags every occurrence (probe). So report.
		msg := fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", lit.Value)
		if lit.Kind == token.STRING {
			msg = fmt.Sprintf("avoid magic strings like '%s', create a named constant for it", lit.Value)
		}
		rc.addNode(lit, msg, 1)
	}
}
