func ruleLineLengthLimit(rc *RuleContext) {
	limit := intArg(rc.Rule.cfg, 80)
	content := string(rc.File.Content)
	lines := strings.Split(content, "\n")
	// If file ends with newline, last split element is empty pseudo-line; original likely uses scanner lines and does not count trailing empty.
	for i, line := range lines {
		if i == len(lines)-1 && line == "" && strings.HasSuffix(content, "\n") {
			continue
		}
		// line length in runes? Use rune count to be safe for unicode? Original likely len(line). We'll use len in runes? Test unicode later.
		length := len([]rune(strings.TrimSuffix(line, "\r")))
		if length > limit {
			start := Position{Filename: rc.File.Display, Offset: 0, Line: i + 1, Column: 0}
			end := Position{Filename: rc.File.Display, Offset: 0, Line: i + 1, Column: length}
			rc.addRaw(start, end, fmt.Sprintf("line is %d characters, out of limit %d", length, limit), 1, rc.Rule.Cat, "")
		}
	}
}

