func cyclomaticComplexity(fd *ast.FuncDecl, fl *ast.FuncLit) int {
	complexity := 1
	var body *ast.BlockStmt
	if fd != nil {
		body = fd.Body
	} else {
		body = fl.Body
	}
	if body == nil {
		return complexity
	}
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt:
			complexity++
		case *ast.CaseClause:
			// count cases with expressions (not default)
			if node.List != nil {
				complexity++
			}
		case *ast.CommClause:
			if node.Comm != nil {
				complexity++
			}
		case *ast.BinaryExpr:
			if node.Op == token.LAND || node.Op == token.LOR {
				complexity++
			}
		}
		return true
	})
	return complexity
}

