func ruleCommentSpacings(rc *RuleContext) {
	for _, cg := range rc.File.AST.Comments {
		for _, c := range cg.List {
			text := c.Text
			bad := false
			if strings.HasPrefix(text, "//") {
				rest := text[2:]
				if rest == "" {
					bad = false
				} else if rest[0] == ' ' || rest[0] == '\t' || rest[0] == '\n' {
					bad = false
				} else if strings.HasPrefix(rest, "/") || strings.HasPrefix(rest, "-") {
					// /// or //- comments are often separators - need probe; assume allowed
					bad = false
				} else if isDirectiveComment(rest) {
					bad = false
				} else {
					bad = true
				}
			} else if strings.HasPrefix(text, "/*") {
				rest := strings.TrimPrefix(text, "/*")
				if rest == "" || strings.HasPrefix(rest, "*") {
					bad = false
				} else if rest[0] == ' ' || rest[0] == '\t' || rest[0] == '\n' {
					bad = false
				} else {
					bad = true
				}
			}
			if bad {
				rc.addNode(c, "no space between comment delimiter and comment text", 1)
			}
		}
	}
}

func isDirectiveComment(rest string) bool {
	// //go:..., // +build handled as rest starts with space for +build, go: etc
	if strings.HasPrefix(rest, "go:") || strings.HasPrefix(rest, "revive:") || strings.HasPrefix(rest, "export ") {
		return true
	}
	// cgo/export etc directives like "//export" have no space by design
	if strings.HasPrefix(rest, "export") {
		return true
	}
	return false
}

func rulePackageDirectoryMismatch(rc *RuleContext) {
	if rc.File.AST == nil || rc.File.AST.Name == nil {
		return
	}
	pkgName := rc.File.AST.Name.Name
	dir := filepath.Base(rc.Pkg.AbsDir)
	// For test package foo_test, directory should match foo?
	cmpPkg := pkgName
	if strings.HasSuffix(cmpPkg, "_test") {
		// Original may compare full? We'll compare trimmed?
		// Keep full for now if dir doesn't match either
		if dir == strings.TrimSuffix(cmpPkg, "_test") {
			return
		}
	}
	if dir == "." || dir == "/" || dir == "" {
		return
	}
	if pkgName != dir {
		rc.addNode(rc.File.AST.Name, fmt.Sprintf("package name \"%s\" does not match directory name \"%s\"", pkgName, dir), 1)
	}
}
