func ruleStructTag(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		field, ok := n.(*ast.Field)
		if !ok || field.Tag == nil {
			return true
		}
		tag, err := strconv.Unquote(field.Tag.Value)
		if err != nil {
			rc.addNode(field.Tag, "malformed tag", 1)
			return true
		}
		if !validStructTag(tag) {
			rc.addNode(field.Tag, "malformed tag", 1)
		}
		return true
	})
}

func validStructTag(tag string) bool {
	// Copied logic equivalent to reflect.StructTag parsing
	for tag != "" {
		// skip leading spaces
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			return true
		}
		// scan key name
		i = 0
		for i < len(tag) && tag[i] > ' ' && tag[i] != ':' && tag[i] != '"' && tag[i] != 0x7f {
			i++
		}
		if i == 0 || i+1 >= len(tag) || tag[i] != ':' || tag[i+1] != '"' {
			return false
		}
		key := tag[:i]
		_ = key
		tag = tag[i+1:]
		// scan quoted value
		i = 1
		for i < len(tag) && tag[i] != '"' {
			if tag[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(tag) {
			return false
		}
		// validate quoted
		qvalue := tag[:i+1]
		if _, err := strconv.Unquote(qvalue); err != nil {
			return false
		}
		tag = tag[i+1:]
	}
	return true
}

var _ = reflect.TypeOf

func ruleUseFmtPrint(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		id, ok := call.Fun.(*ast.Ident)
		if !ok || (id.Name != "print" && id.Name != "println") {
			return true
		}
		fn := "Fprint"
		if id.Name == "println" {
			fn = "Fprintln"
		}
		var args []string
		for _, a := range call.Args {
			args = append(args, rc.source(a))
		}
		suggestion := fmt.Sprintf("fmt.%s(os.Stderr, %s)", fn, strings.Join(args, ", "))
		if len(args) == 0 {
			suggestion = fmt.Sprintf("fmt.%s(os.Stderr, )", fn)
			// likely special; will probe if needed
		}
		rc.addNode(call, fmt.Sprintf("avoid using built-in function \"%s\", replace it by \"%s\"", id.Name, suggestion), 1)
		return true
	})
