func ruleUncheckedTypeAssertion(rc *RuleContext) {
	walkWithParent(rc.File.AST, func(n ast.Node, parent ast.Node) {
		ta, ok := n.(*ast.TypeAssertExpr)
		if !ok {
			return
		}
		// safe contexts
		switch p := parent.(type) {
		case *ast.AssignStmt:
			if len(p.Lhs) == 2 && len(p.Rhs) == 1 {
				return
			}
		case *ast.ValueSpec:
			if len(p.Names) == 2 && len(p.Values) == 1 {
				return
			}
		case *ast.TypeSwitchStmt:
			return
		}
		// TypeSwitch guard AssignStmt is a TypeSwitchStmt.Init/Assign? In ast, TypeSwitchStmt.Assign is a Stmt; parent of assert in that assign is AssignStmt with ?? LHS 1.
		// The TypeSwitchStmt case above covers assert directly under it, but assert under AssignStmt in a type switch: check grandparent not available. Detect via source? We'll check if parent AssignStmt is inside a type switch by looking at its statement: if RHS is assert and Assign is the Assign field of a TypeSwitchStmt - our walker parent chain not accessible here.
