	})
}

func localFuncSignatures(rc *RuleContext) map[string]*ast.FuncType {
	sigs := map[string]*ast.FuncType{}
	for _, f := range rc.Pkg.Files {
		if f.AST == nil {
			continue
		}
		for _, decl := range f.AST.Decls {
			if fd, ok := decl.(*ast.FuncDecl); ok {
				if fd.Recv == nil {
					sigs[fd.Name.Name] = fd.Type
				} else {
					// method key by method name (unique approximation)
					sigs["."+fd.Name.Name] = fd.Type
				}
			}
			if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
				for _, spec := range gen.Specs {
					if ts, ok := spec.(*ast.TypeSpec); ok {
						if ft, ok := ts.Type.(*ast.FuncType); ok {
							sigs[ts.Name.Name] = ft
						}
					}
				}
			}
		}
	}
	return sigs
}

func funcTypeReturnsError(rc *RuleContext, ft *ast.FuncType) bool {
	if ft == nil || ft.Results == nil {
		return false
	}
	for _, field := range ft.Results.List {
		if id, ok := field.Type.(*ast.Ident); ok && id.Name == "error" {
			return true
		}
	}
	return false
}

func ruleUnhandledError(rc *RuleContext) {
	sigs := localFuncSignatures(rc)
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		stmt, ok := n.(*ast.ExprStmt)
		if !ok {
			return true
		}
		call, ok := stmt.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		var ft *ast.FuncType
		var funSrc string
		switch fun := call.Fun.(type) {
		case *ast.Ident:
			ft = sigs[fun.Name]
			funSrc = fun.Name
		case *ast.SelectorExpr:
			ft = sigs["."+fun.Sel.Name]
			funSrc = rc.source(fun)
			// Also function variable field etc not.
		}
		if ft != nil && funcTypeReturnsError(rc, ft) {
			rc.addNode(call.Fun, fmt.Sprintf("Unhandled error in call to function %s", funSrc), 1)
		}
		return true
	})
}

func ruleUnusedReceiver(rc *RuleContext) {
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 || fd.Body == nil {
			continue
		}
		field := fd.Recv.List[0]
		if len(field.Names) == 0 {
			continue
		}
		nameIdent := field.Names[0]
		if nameIdent.Name == "_" {
			continue
		}
		used := false
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok && id.Name == nameIdent.Name {
				used = true
			}
			return true
		})
		if !used {
			rc.addNode(nameIdent, fmt.Sprintf("method receiver '%s' is not referenced in method's body, consider removing or renaming it as _", nameIdent.Name), 1)
		}
	}
}

func ruleWaitgroupByValue(rc *RuleContext) {
	check := func(typ *ast.FuncType) {
		if typ == nil || typ.Params == nil {
			return
		}
		for _, field := range typ.Params.List {
			if pkg, sel, ok := selectorPkgSel(field.Type); ok && pkg == "sync" && sel == "WaitGroup" {
				rc.addNode(field, "sync.WaitGroup passed by value, the function will get a copy of the original one", 1)
			}
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			check(fd.Type)
		}
	}
}

func normalizedSrc(rc *RuleContext, n ast.Node) string {
	s := rc.source(n)
	// remove all whitespace for comparison
	var b strings.Builder
	for _, r := range s {
		if r != ' ' && r != '\t' && r != '\n' && r != '\r' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func ruleConstantLogicalExpr(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch be.Op {
		case token.LAND, token.LOR, token.EQL, token.NEQ:
			if normalizedSrc(rc, be.X) == normalizedSrc(rc, be.Y) && normalizedSrc(rc, be.X) != "" {
				rc.addNode(be, "left and right hand-side sub-expressions are the same", 1)
			}
		}
		return true
	})
}

func stmtListSource(rc *RuleContext, list []ast.Stmt) string {
	var parts []string
	for _, s := range list {
		parts = append(parts, normalizedSrc(rc, s))
	}
	return strings.Join(parts, ";")
}

func ruleIdenticalBranches(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if stmtListSource(rc, ifStmt.Body.List) == stmtListSource(rc, elseBlock.List) {
			rc.addNode(ifStmt, "both branches of the if are identical", 1)
		}
		return true
	})
}

func ruleIdenticalSwitchBranches(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		var clauses []*ast.CaseClause
		var node ast.Node
		switch sw := n.(type) {
		case *ast.SwitchStmt:
			node = sw
			for _, stmt := range sw.Body.List {
				if cc, ok := stmt.(*ast.CaseClause); ok {
					clauses = append(clauses, cc)
				}
			}
		case *ast.TypeSwitchStmt:
			node = sw
			for _, stmt := range sw.Body.List {
				if cc, ok := stmt.(*ast.CaseClause); ok {
					clauses = append(clauses, cc)
				}
			}
		default:
			return true
		}
		seen := map[string]*ast.CaseClause{}
		for _, cc := range clauses {
			key := stmtListSource(rc, cc.Body)
			if prev, ok := seen[key]; ok {
				linePrev := rc.File.Fset.Position(prev.Pos()).Line
				lineCurr := rc.File.Fset.Position(cc.Pos()).Line
				kind := "switch"
				if _, isType := node.(*ast.TypeSwitchStmt); isType {
					kind = "switch"
				}
				rc.addNode(node, fmt.Sprintf("\"%s\" with identical branches (lines %d and %d)", kind, linePrev, lineCurr), 1)
				break
			}
			seen[key] = cc
		}
		return true
	})
}
