func validStructTag(tag string) bool {
	// Copied logic equivalent to reflect.StructTag parsing
	for tag != "" {
		// skip leading spaces
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			return true
		}
		// scan key name
		i = 0
		for i < len(tag) && tag[i] > ' ' && tag[i] != ':' && tag[i] != '"' && tag[i] != 0x7f {
			i++
		}
		if i == 0 || i+1 >= len(tag) || tag[i] != ':' || tag[i+1] != '"' {
			return false
		}
		key := tag[:i]
		_ = key
		tag = tag[i+1:]
		// scan quoted value
		i = 1
		for i < len(tag) && tag[i] != '"' {
			if tag[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(tag) {
			return false
		}
		// validate quoted
		qvalue := tag[:i+1]
		if _, err := strconv.Unquote(qvalue); err != nil {
			return false
		}
		tag = tag[i+1:]
	}
	return true
