	registerRule("identical-ifelseif-conditions", "logic", ruleIdenticalIfElseIfConditions)
	registerRule("identical-switch-conditions", "logic", ruleIdenticalSwitchConditions)
	registerRule("range-val-in-closure", "", ruleRangeValInClosure)
	registerRule("range-val-address", "", ruleRangeValAddress)
	registerRule("redundant-test-main-exit", "style", ruleRedundantTestMainExit)
	registerRule("unnecessary-format", "optimization", ruleUnnecessaryFormat)
