// Flatten an if-else-if chain
type ifChainItem struct {
	ifStmt *ast.IfStmt
	body   *ast.BlockStmt
}

func flattenIfChain(start *ast.IfStmt) ([]*ast.IfStmt, *ast.BlockStmt) {
	var chain []*ast.IfStmt
	cur := start
	for cur != nil {
		chain = append(chain, cur)
		if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
			cur = elseIf
		} else {
			break
		}
	}
	// check start is not itself an else-if of a parent: caller should only invoke on top-level encountered but Inspect visits nested else-ifs too.
	return chain, nil
}

func isElseIf(rc *RuleContext, target *ast.IfStmt) bool {
	found := false
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if ifs, ok := n.(*ast.IfStmt); ok && ifs.Else == ast.Node(target) {
			found = true
		}
		return true
	})
	return found
}

func ruleIdenticalIfElseIfBranches(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// only process chain heads: ensure this If is Else of another?
		// Detect if this node is an else-if child
		if isElseIf(rc, ifStmt) {
			return true
		}
		chain, _ := flattenIfChain(ifStmt)
		if len(chain) < 2 {
			return true
		}
		// compare bodies of all in chain plus final else block?
		type bodyInfo struct {
			block *ast.BlockStmt
			src   string
		}
		var bodies []bodyInfo
		for _, item := range chain {
			bodies = append(bodies, bodyInfo{item.Body, stmtListSource(rc, item.Body.List)})
		}
		// final else
		last := chain[len(chain)-1]
		if elseBlock, ok := last.Else.(*ast.BlockStmt); ok {
			bodies = append(bodies, bodyInfo{elseBlock, stmtListSource(rc, elseBlock.List)})
		}
		seen := map[string]*ast.BlockStmt{}
		for _, b := range bodies {
			if prev, ok := seen[b.src]; ok {
				linePrev := rc.File.Fset.Position(prev.Pos()).Line
				lineCurr := rc.File.Fset.Position(b.block.Pos()).Line
				rc.addNode(prev, fmt.Sprintf("\"if...else if\" chain with identical branches (lines %d and %d)", linePrev, lineCurr), 1)
				break
			}
			seen[b.src] = b.block
		}
		return true
	})
}

func ruleIdenticalIfElseIfConditions(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if isElseIf(rc, ifStmt) {
			return true
		}
		chain, _ := flattenIfChain(ifStmt)
		if len(chain) < 2 {
			return true
		}
		seen := map[string]*ast.IfStmt{}
		for _, item := range chain {
			key := normalizedSrc(rc, item.Cond)
			if prev, ok := seen[key]; ok {
				linePrev := rc.File.Fset.Position(prev.Cond.Pos()).Line
				lineCurr := rc.File.Fset.Position(item.Cond.Pos()).Line
				rc.addNode(item, fmt.Sprintf("\"if...else if\" chain with identical conditions (lines %d and %d)", linePrev, lineCurr), 1)
				break
			}
			seen[key] = item
		}
		return true
	})
}

func ruleIdenticalSwitchConditions(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Tag != nil {
			return true
		}
		seen := map[string]*ast.CaseClause{}
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok || cc.List == nil {
				continue
			}
			var exprs []string
			for _, e := range cc.List {
				exprs = append(exprs, normalizedSrc(rc, e))
			}
			key := strings.Join(exprs, ",")
			if _, ok := seen[key]; ok {
				lineCurr := rc.File.Fset.Position(cc.Pos()).Line
				rc.addNode(cc, fmt.Sprintf("case clause at line %d has the same condition", lineCurr), 1)
			} else {
				seen[key] = cc
			}
		}
		return true
	})
}

func ruleRangeValInClosure(rc *RuleContext) {
	// For each range statement, find FuncLits in its body and Closure references to range vars
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		vars := map[string]bool{}
		if id, ok := rs.Key.(*ast.Ident); ok && id.Name != "_" {
			vars[id.Name] = true
		}
		if id, ok := rs.Value.(*ast.Ident); ok && id.Name != "_" {
			vars[id.Name] = true
		}
		if len(vars) == 0 {
			return true
		}
		// inspect body for FuncLit
		ast.Inspect(rs.Body, func(m ast.Node) bool {
			fl, ok := m.(*ast.FuncLit)
			if !ok {
				return true
			}
			// Inside FuncLit, find idents referencing range vars (exclude param names inside lit shadowing)
			// collect shadowed names in lit params
			shadow := map[string]bool{}
			if fl.Type != nil && fl.Type.Params != nil {
				for _, f := range fl.Type.Params.List {
					for _, nm := range f.Names {
						shadow[nm.Name] = true
					}
				}
			}
			ast.Inspect(fl.Body, func(x ast.Node) bool {
				if id, ok := x.(*ast.Ident); ok && vars[id.Name] && !shadow[id.Name] {
					rc.addNode(id, fmt.Sprintf("loop variable %s captured by func literal", id.Name), 1)
				}
				return true
			})
			return false // don't descend into nested lits twice? Inner lits will be visited by outer Inspect as separate nodes, but captures inside inner would be reported multiple times if we continue. Returning false prunes.
		})
		return true
	})
}

func ruleRangeValAddress(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		vars := map[string]bool{}
		if id, ok := rs.Key.(*ast.Ident); ok {
			vars[id.Name] = true
		}
		if id, ok := rs.Value.(*ast.Ident); ok {
			vars[id.Name] = true
		}
		ast.Inspect(rs.Body, func(m ast.Node) bool {
			if unary, ok := m.(*ast.UnaryExpr); ok && unary.Op == token.AND {
				if id, ok := unary.X.(*ast.Ident); ok && vars[id.Name] {
					rc.addNode(unary, fmt.Sprintf("suspicious assignment of '%s'. range-loop variables always have the same address", id.Name), 1)
				}
			}
			return true
		})
		return true
	})
}

func ruleRedundantTestMainExit(rc *RuleContext) {
	if !rc.File.IsTest {
		return
	}
	for _, decl := range rc.File.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Name.Name != "TestMain" || fd.Body == nil {
			continue
		}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			if pkg, sel, ok := selectorPkgSel(call.Fun); ok && pkg == "os" && sel == "Exit" {
				// check argument is a call to Run method (selector .Run)
				if len(call.Args) == 1 {
					if inner, ok := call.Args[0].(*ast.CallExpr); ok {
						if _, sel2, ok := selectorPkgSel(inner.Fun); ok && sel2 == "Run" {
							rc.addNode(call, "redundant call to os.Exit in TestMain function, the test runner will handle it automatically as of Go 1.15", 1)
						}
					}
				}
			}
			return true
		})
	}
}

func hasFormattingDirective(format string) bool {
	// return true if there is a % directive other than %%
	for i := 0; i < len(format); i++ {
		if format[i] != '%' {
			continue
		}
		if i+1 < len(format) && format[i+1] == '%' {
			i++
			continue
		}
		return true
	}
	return false
}

func ruleUnnecessaryFormat(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "fmt" {
			return true
		}
		if sel != "Printf" && sel != "Sprintf" && sel != "Errorf" && sel != "Fprintf" {
			return true
		}
		// format argument index: for Fprintf, format is 2nd argument
		formatIdx := 0
		if sel == "Fprintf" {
			formatIdx = 1
		}
		if len(call.Args) <= formatIdx {
			return true
		}
		lit, ok := call.Args[formatIdx].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		formatStr, ok := unquoteString(lit)
		if !ok {
			return true
		}
		if hasFormattingDirective(formatStr) {
			return true
		}
		// Also if there are extra arguments beyond format, then formatting is used? Still unnecessary if no directives? Original maybe checks nargs. We'll only flag when no extra args? Probe form with args later.
		// Message mapping
		switch sel {
		case "Printf":
			rc.addPos(call.Fun.Pos(), call.Fun.End(), "unnecessary use of formatting function \"fmt.Printf\", you can replace it with \"fmt.Print\" or \"fmt.Println\"", 0.8, rc.Rule.Cat, "")
		case "Sprintf":
			rc.addPos(call.Fun.Pos(), call.Fun.End(), "unnecessary use of formatting function \"fmt.Sprintf\", you can replace it with \"fmt.Sprint\" or just the string itself\"", 0.8, rc.Rule.Cat, "")
		case "Errorf":
			// original may not include Errorf; tentative skip
			return true
		case "Fprintf":
			rc.addPos(call.Fun.Pos(), call.Fun.End(), "unnecessary use of formatting function \"fmt.Fprintf\", you can replace it with \"fmt.Fprint\" or \"fmt.Fprintln\"", 0.8, rc.Rule.Cat, "")
		}
		return true
	})
}

func ruleUseErrorsNew(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "fmt" || sel != "Errorf" {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		formatStr, ok := unquoteString(lit)
		if !ok || hasFormattingDirective(formatStr) {
			return true
		}
		rc.addNode(call, "replace fmt.Errorf by errors.New", 1)
		return true
	})
}
