package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"strings"
)

type reviveImporter struct {
	fset     *token.FileSet
	inModule bool
	modPath  string
	modRoot  string
	def      types.Importer
	cache    map[string]*types.Package
	loading  map[string]bool
}

func findModule(startDir string) (string, string, bool) {
	dir := startDir
	for {
		gomod := filepath.Join(dir, "go.mod")
		if data, err := os.ReadFile(gomod); err == nil {
			// parse module line
			for _, line := range strings.Split(string(data), "\n") {
				line = strings.TrimSpace(line)
				if strings.HasPrefix(line, "module ") {
					return strings.TrimSpace(strings.TrimPrefix(line, "module ")), dir, true
				}
				if strings.HasPrefix(line, "module\t") {
					return strings.TrimSpace(line[len("module"):]), dir, true
				}
			}
			return "", dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", "", false
		}
		dir = parent
	}
}

func newImporterForPackage(absDir string, fset *token.FileSet) *reviveImporter {
	modPath, modRoot, ok := findModule(absDir)
	return &reviveImporter{
		fset:     fset,
		inModule: ok,
		modPath:  modPath,
		modRoot:  modRoot,
		def:      importer.Default(),
		cache:    map[string]*types.Package{},
		loading:  map[string]bool{},
	}
}

func (imp *reviveImporter) Import(path string) (*types.Package, error) {
	if !imp.inModule {
		return nil, fmt.Errorf("can't import %s", path)
	}
	if pkg, ok := imp.cache[path]; ok {
		return pkg, nil
	}
	// Try default importer first (stdlib, external compiled)
	if pkg, err := imp.def.Import(path); err == nil {
		imp.cache[path] = pkg
		return pkg, nil
	}
	// Local module package
	if imp.modPath != "" && (path == imp.modPath || strings.HasPrefix(path, imp.modPath+"/")) {
		rel := strings.TrimPrefix(path, imp.modPath)
		rel = strings.TrimPrefix(rel, "/")
		dir := filepath.Join(imp.modRoot, filepath.FromSlash(rel))
		pkg, err := imp.loadLocalPackage(path, dir)
		if err != nil {
			return nil, err
		}
		imp.cache[path] = pkg
		return pkg, nil
	}
	return nil, fmt.Errorf("can't import %s", path)
}

func (imp *reviveImporter) loadLocalPackage(path string, dir string) (*types.Package, error) {
	if imp.loading[path] {
		return nil, fmt.Errorf("import cycle %s", path)
	}
	imp.loading[path] = true
	defer delete(imp.loading, path)
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var files []*ast.File
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
			continue
		}
		// build constraints not evaluated here (approximation)
		f, err := parser.ParseFile(imp.fset, filepath.Join(dir, e.Name()), nil, parser.ParseComments)
		if err != nil {
			continue
		}
		files = append(files, f)
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("no Go files in %s", dir)
	}
	conf := types.Config{Importer: imp, Error: func(err error) {}, FakeImportC: true}
	pkg, err := conf.Check(path, imp.fset, files, nil)
	if pkg == nil {
		return nil, err
	}
	// conf.Check may return incomplete pkg even with errors; original type info would have it
	return pkg, nil
}
