package main

import (
	"fmt"
	"go/ast"
	"strings"
)

func init() {
	registerRuleWithConfig("enforce-slice-style", "style", ruleEnforceSliceStyle, configureEnforceSlice)
	registerRuleWithConfig("enforce-map-style", "style", ruleEnforceMapStyle, configureEnforceMap)
	registerRuleWithConfig("enforce-switch-style", "style", ruleEnforceSwitchStyle, configureEnforceSwitch)
	registerRuleWithConfig("enforce-repeated-arg-type-style", "style", ruleEnforceRepeatedArgType, configureEnforceRepeated)
}

func styleArg(rc *RuleContext, def string) string {
	if rc.Rule.cfg == nil || len(rc.Rule.cfg.Arguments) == 0 {
		return def
	}
	if s, ok := rc.Rule.cfg.Arguments[0].(string); ok {
		return s
	}
	return def
}
func configureEnforceSlice(args []interface{}, cfg *RuleConfig) error {
	if len(args) == 0 {
		return nil
	}
	s, ok := args[0].(string)
	if !ok {
		return fmt.Errorf("invalid argument to the enforce-slice-style rule: invalid slice style: %v (expecting one of [any make literal nil])", args[0])
	}
	switch s {
	case "any", "make", "literal", "nil":
		return nil
	default:
		return fmt.Errorf("invalid argument to the enforce-slice-style rule: invalid slice style: %s (expecting one of [any make literal nil])", s)
	}
}
func configureEnforceMap(args []interface{}, cfg *RuleConfig) error {
	if len(args) == 0 {
		return nil
	}
	s, ok := args[0].(string)
	if !ok {
		return fmt.Errorf("invalid argument to the enforce-map-style rule: invalid map style: %v (expecting one of [any make literal])", args[0])
	}
	switch s {
	case "any", "make", "literal":
		return nil
	default:
		return fmt.Errorf("invalid argument to the enforce-map-style rule: invalid map style: %s (expecting one of [any make literal])", s)
	}
}
func configureEnforceSwitch(args []interface{}, cfg *RuleConfig) error {
	for _, a := range args {
		s, ok := a.(string)
		if !ok {
			return fmt.Errorf("invalid argument \"%v\" for rule enforce-switch-style; expected \"allowNoDefault\" or \"allowDefaultNotLast\"", a)
		}
		if s != "allowNoDefault" && s != "allowDefaultNotLast" {
			return fmt.Errorf("invalid argument \"%s\" for rule enforce-switch-style; expected \"allowNoDefault\" or \"allowDefaultNotLast\"", s)
		}
	}
	return nil
}
func configureEnforceRepeated(args []interface{}, cfg *RuleConfig) error {
	if len(args) == 0 {
		return nil
	}
	s, ok := args[0].(string)
	if !ok {
		return fmt.Errorf("invalid argument to the enforce-repeated-arg-type-style rule: invalid repeated arg type style: %v (expecting one of [any short full])", args[0])
	}
	switch s {
	case "any", "short", "full":
		return nil
	default:
		return fmt.Errorf("invalid argument to the enforce-repeated-arg-type-style rule: invalid repeated arg type style: %s (expecting one of [any short full])", s)
	}
}

func isEmptyCompositeLit(rc *RuleContext, e ast.Expr) (*ast.CompositeLit, bool) {
	cl, ok := e.(*ast.CompositeLit)
	if !ok || len(cl.Elts) != 0 {
		return nil, false
	}
	return cl, true
}
func makeCallInfo(rc *RuleContext, e ast.Expr) (*ast.CallExpr, bool) {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return nil, false
	}
	id, ok := call.Fun.(*ast.Ident)
	return call, ok && id.Name == "make"
}

func ruleEnforceSliceStyle(rc *RuleContext) {
	style := styleArg(rc, "any")
	if style == "any" {
		return
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		// Composite literals empty slice
		if cl, ok := n.(*ast.CompositeLit); ok && len(cl.Elts) == 0 {
			// check type is slice/array? Composite type source starts with []
			typeSrc := ""
			if cl.Type != nil {
				typeSrc = rc.source(cl.Type)
			}
			if strings.HasPrefix(typeSrc, "[]") {
				switch style {
				case "nil":
					rc.addNode(cl, "use nil slice declaration (e.g. var args []type) instead of []type{}", 1)
				case "make":
					rc.addNode(cl, "use make([]type) instead of []type{} (or declare nil slice)", 1)
				}
			}
			return true
		}
		if call, ok := n.(*ast.CallExpr); ok {
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "make" && len(call.Args) >= 1 {
				// slice type only
				typeSrc := rc.source(call.Args[0])
				if !strings.HasPrefix(typeSrc, "[]") {
					return true
				}
				isZeroLen := false
				if len(call.Args) == 1 {
					isZeroLen = true
				} else if len(call.Args) >= 2 {
					if lit, ok := call.Args[1].(*ast.BasicLit); ok && lit.Value == "0" {
						isZeroLen = true
					}
					if id2, ok := call.Args[1].(*ast.Ident); ok && id2.Name == "0" {
						isZeroLen = true
					}
				}
				if isZeroLen {
					switch style {
					case "nil":
						rc.addNode(call.Fun, "use nil slice declaration (e.g. var args []type) instead of make([]type, 0)", 1)
					case "literal":
						rc.addNode(call.Fun, "use []type{} instead of make([]type, 0) (or declare nil slice)", 1)
					}
				}
			}
		}
		return true
	})
}

func ruleEnforceMapStyle(rc *RuleContext) {
	style := styleArg(rc, "any")
	if style == "any" {
		return
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if cl, ok := n.(*ast.CompositeLit); ok && len(cl.Elts) == 0 {
			typeSrc := ""
			if cl.Type != nil {
				typeSrc = rc.source(cl.Type)
			}
			if strings.HasPrefix(typeSrc, "map[") {
				if style == "make" {
					rc.addNode(cl, "use make(map[type]type) instead of map[type]type{}", 1)
				}
			}
			return true
		}
		if call, ok := n.(*ast.CallExpr); ok {
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "make" && len(call.Args) >= 1 {
				typeSrc := rc.source(call.Args[0])
				if strings.HasPrefix(typeSrc, "map[") {
					if style == "literal" {
						rc.addNode(call.Fun, "use map[type]type{} instead of make(map[type]type)", 1)
					}
				}
			}
		}
		return true
	})
}

func ruleEnforceSwitchStyle(rc *RuleContext) {
	allowNoDefault := false
	allowDefaultNotLast := false
	if rc.Rule.cfg != nil {
		for _, a := range rc.Rule.cfg.Arguments {
			if s, ok := a.(string); ok {
				if s == "allowNoDefault" {
					allowNoDefault = true
				}
				if s == "allowDefaultNotLast" {
					allowDefaultNotLast = true
				}
			}
		}
	}
	checkBody := func(node ast.Node, body *ast.BlockStmt) {
		if body == nil {
			return
		}
		var defaultClause *ast.CaseClause
		defaultIndex := -1
		total := 0
		for i, stmt := range body.List {
			if cc, ok := stmt.(*ast.CaseClause); ok {
				total++
				if cc.List == nil {
					defaultClause = cc
					defaultIndex = i
				}
			}
		}
		if defaultClause == nil {
			if !allowNoDefault {
				rc.addNode(node, "switch must have a default case clause", 1)
			}
			return
		}
		if defaultIndex != total-1 && !allowDefaultNotLast {
			rc.addNode(defaultClause, "default case clause must be the last one", 1)
		}
		_ = body
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		switch sw := n.(type) {
		case *ast.SwitchStmt:
			checkBody(sw, sw.Body)
		case *ast.TypeSwitchStmt:
			checkBody(sw, sw.Body)
		}
		return true
	})
}

func ruleEnforceRepeatedArgType(rc *RuleContext) {
	style := styleArg(rc, "any")
	if style == "any" {
		return
	}
	checkList := func(list []*ast.Field, isResult bool) {
		if style == "full" {
			for _, field := range list {
				if len(field.Names) > 1 {
					if isResult {
						rc.addNode(field, "return types should not be omitted", 1)
					} else {
						rc.addNode(field, "argument types should not be omitted", 1)
					}
				}
			}
			return
		}
		// short: consecutive fields with same type source, each field has (probably 1) name, flag type node of field that repeats later.
		for i := 0; i+1 < len(list); i++ {
			cur := list[i]
			next := list[i+1]
			if rc.source(cur.Type) == rc.source(next.Type) && rc.source(cur.Type) != "" {
				typeSrc := rc.source(cur.Type)
				if isResult {
					rc.addNode(cur.Type, fmt.Sprintf("repeated return type \"%s\" can be omitted", typeSrc), 1)
				} else {
					rc.addNode(cur.Type, fmt.Sprintf("repeated argument type \"%s\" can be omitted", typeSrc), 1)
				}
			}
		}
	}
	checkFuncType := func(ft *ast.FuncType) {
		if ft == nil {
			return
		}
		if ft.Params != nil {
			checkList(ft.Params.List, false)
		}
		if ft.Results != nil {
			checkList(ft.Results.List, true)
		}
	}
	for _, decl := range rc.File.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			checkFuncType(fd.Type)
		}
		if gen, ok := decl.(*ast.GenDecl); ok {
			for _, spec := range gen.Specs {
				if ts, ok := spec.(*ast.TypeSpec); ok {
					if ft, ok := ts.Type.(*ast.FuncType); ok {
						checkFuncType(ft)
					}
				}
			}
		}
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if fl, ok := n.(*ast.FuncLit); ok {
			checkFuncType(fl.Type)
		}
		return true
	})
}
