{"command":"cat > rules_batch7.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"strconv"
	"strings"
)

func init() {
	registerRule("time-equal", "time", ruleTimeEqual)
	registerRule("time-date", "time", ruleTimeDate)
	registerRule("unsecure-url-scheme", "", ruleUnsecureURL)
	registerRule("unnecessary-if", "logic", ruleUnnecessaryIf)
	registerRuleWithConfig("string-format", "", ruleStringFormat, configureStringFormat)
	registerRule("atomic", "", ruleAtomic)
	registerRule("datarace", "logic", ruleDatarace)
	registerRule("use-slices-sort", "maintenance", ruleUseSlicesSort)
	registerRule("use-waitgroup-go", "style", ruleUseWaitgroupGo)
	registerRule("forbidden-call-in-wg-go", "errors", ruleForbiddenCallInWGGo)
}

func ruleTimeEqual(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok || (be.Op != token.EQL && be.Op != token.NEQ) {
			return true
		}
		if !isTimeTimeType(rc, be.X) {
			return true
		}
		xSrc := rc.source(be.X)
		ySrc := rc.source(be.Y)
		if be.Op == token.EQL {
			rc.addNode(be, fmt.Sprintf("use %s.Equal(%s) instead of \"==\" operator", xSrc, ySrc), 1)
		} else {
			rc.addNode(be, fmt.Sprintf("use !%s.Equal(%s) instead of \"!=\" operator", xSrc, ySrc), 1)
		}
		return true
	})
}

func isTimeTimeType(rc *RuleContext, e ast.Expr) bool {
	typ := rc.typeOf(e)
	if typ == nil {
		return false
	}
	named, ok := typ.(*types.Named)
	if !ok {
		return false
	}
	obj := named.Obj()
	return obj != nil && obj.Pkg() != nil && obj.Pkg().Name() == "time" && obj.Name() == "Time"
}

func ruleTimeDate(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "time" || sel != "Date" {
			return true
		}
		if len(call.Args) < 7 {
			return true
		}
		// helpers to get literal int
		getInt := func(idx int) (int64, *ast.BasicLit, bool) {
			if idx >= len(call.Args) {
				return 0, nil, false
			}
			lit, ok := call.Args[idx].(*ast.BasicLit)
			if !ok || lit.Kind != token.INT {
				return 0, nil, false
			}
			v, err := strconv.ParseInt(lit.Value, 10, 64)
			if err != nil {
				// try base 0
				v2, err2 := strconv.ParseInt(lit.Value, 0, 64)
				if err2 != nil {
					return 0, lit, false
				}
				v = v2
			}
			return v, lit, true
		}
		year, _, hasYear := getInt(0)
		month, monthLit, hasMonth := getInt(1)
		day, dayLit, hasDay := getInt(2)
		monthNames := []string{"", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}
		if hasMonth {
			if month == 0 {
				rc.addNode(monthLit, "time.Date month argument should not be zero", 1)
			} else if month < 1 || month > 12 {
				rc.addNode(monthLit, fmt.Sprintf("time.Date month argument should be between 1 and 12: %d", month), 0.8)
			}
		}
		if hasDay {
			if day == 0 {
				rc.addNode(dayLit, "time.Date day argument should not be zero", 1)
			} else if hasMonth && month >= 1 && month <= 12 {
				daysIn := daysInMonth(int(month), int(year), hasYear)
				if day > int64(daysIn) {
					if month == 2 {
						rc.addNode(dayLit, fmt.Sprintf("time.Date day argument is %d, but %s %d has only %d days", day, monthNames[month], year, daysIn), 0.8)
					} else {
						rc.addNode(dayLit, fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", day, monthNames[month], daysIn), 0.8)
					}
				}
			}
		}
		if v, lit, ok := getInt(3); ok && v > 23 {
			rc.addNode(lit, fmt.Sprintf("time.Date hour argument should be between 0 and 23: %d", v), 0.8)
		}
		if v, lit, ok := getInt(4); ok && v > 59 {
			rc.addNode(lit, fmt.Sprintf("time.Date minute argument should be between 0 and 59: %d", v), 0.8)
		}
		// second argument (5) not checked by original (allows 60 leap second?)
		if v, lit, ok := getInt(6); ok && v > 999999999 {
			rc.addNode(lit, fmt.Sprintf("time.Date nanosecond argument should be between 0 and 999999999: %d", v), 0.8)
		}
		return true
	})
}

func daysInMonth(month int, year int, hasYear bool) int {
	switch month {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		y := year
		if !hasYear {
			y = 2000
		}
		if isLeapYear(y) {
			return 29
		}
		return 28
	}
	return 31
}
func isLeapYear(y int) bool { return y%4 == 0 && (y%100 != 0 || y%400 == 0) }

func ruleUnsecureURL(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		s, ok := unquoteString(lit)
		if !ok {
			return true
		}
		if strings.HasPrefix(s, "http://") {
			rc.addNode(lit, fmt.Sprintf("prefer secure protocol https over http in \"%s\"", s), 1)
		}
		return true
	})
}

func ruleUnnecessaryIf(rc *RuleContext) {
	// patterns returning/assigning bool literals
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		condSrc := rc.source(ifStmt.Cond)
		// Check return pattern
		getBoolReturn := func(block *ast.BlockStmt) (bool, bool) {
			if len(block.List) != 1 {
				return false, false
			}
			ret, ok := block.List[0].(*ast.ReturnStmt)
			if !ok || len(ret.Results) != 1 {
				return false, false
			}
			if id, ok := ret.Results[0].(*ast.Ident); ok && (id.Name == "true" || id.Name == "false") {
				return id.Name == "true", true
			}
			return false, false
		}
		ifVal, ok1 := getBoolReturn(ifStmt.Body)
		elseVal, ok2 := getBoolReturn(elseBlock)
		if ok1 && ok2 && ifVal != elseVal {
			if ifVal {
				rc.addNode(ifStmt, fmt.Sprintf("replace this conditional by: return %s", condSrc), 1)
			} else {
				rc.addNode(ifStmt, fmt.Sprintf("replace this conditional by: return !(%s)", condSrc), 1)
			}
			return true
		}
		// Assign pattern
		getBoolAssign := func(block *ast.BlockStmt) (string, bool, bool) {
			if len(block.List) != 1 {
				return "", false, false
			}
			assign, ok := block.List[0].(*ast.AssignStmt)
			if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
				return "", false, false
			}
			if id, ok := assign.Rhs[0].(*ast.Ident); ok && (id.Name == "true" || id.Name == "false") {
				return rc.source(assign.Lhs[0]), id.Name == "true", true
			}
			return "", false, false
		}
		lhs1, v1, ok1a := getBoolAssign(ifStmt.Body)
		lhs2, v2, ok2a := getBoolAssign(elseBlock)
		if ok1a && ok2a && lhs1 == lhs2 && v1 != v2 {
			if v1 {
				rc.addNode(ifStmt, fmt.Sprintf("replace this conditional by: %s = %s", lhs1, condSrc), 1)
			} else {
				rc.addNode(ifStmt, fmt.Sprintf("replace this conditional by: %s = !(%s)", lhs1, condSrc), 1)
			}
		}
		return true
	})
}

// string-format
type stringFormatOption struct {
	scopeParts []string
	pattern    string // inner compiled pattern string
	regexStr   string // original for message
	msg        string // custom or empty
	re         *regexp.Regexp
}

func parseStringFormatRegex(opt string) (string, *regexp.Regexp, error) {
	// Option is expected delimited: first and last characters are delimiters (/.../ typical)
	var inner string
	if strings.HasPrefix(opt, "/") {
		// find last slash
		last := strings.LastIndex(opt, "/")
		if last > 0 {
			inner = opt[1:last]
			flags := opt[last+1:]
			if strings.Contains(flags, "i") {
				inner = "(?i)" + inner
			}
		} else {
			inner = opt
		}
	} else {
		if len(opt) >= 2 {
			inner = opt[1 : len(opt)-1]
		} else {
			inner = opt
		}
	}
	re, err := regexp.Compile(inner)
	if err != nil {
		return inner, nil, err
	}
	return inner, re, nil
}

func configureStringFormat(args []interface{}, cfg *RuleConfig) error {
	for ai, arg := range args {
		slice, ok := arg.([]interface{})
		if !ok {
			return fmt.Errorf("invalid configuration for string-format: argument is not a slice [argument %d, option 0]", ai)
		}
		if len(slice) < 2 {
			return fmt.Errorf("invalid configuration for string-format: less than two slices found in argument, scope and regex are required [argument %d, option 0]", ai)
		}
		for oi, elem := range slice {
			if _, ok := elem.(string); !ok {
				return fmt.Errorf("invalid configuration for string-format: element is not a string [argument %d, option %d]", ai, oi)
			}
		}
		scope := slice[0].(string)
		parts := strings.Split(scope, ".")
		for idx, part := range parts {
			if part == "" {
				return fmt.Errorf("failed to parse configuration for string-format: unable to parse rule scope [argument %d, option 0, scope index %d]", ai, idx)
			}
		}
		reStr := slice[1].(string)
		if _, _, err := parseStringFormatRegex(reStr); err != nil {
			return fmt.Errorf("failed to parse configuration for string-format: unable to compile %s as regexp [argument %d, option 1]", reStr, ai)
		}
	}
	return nil
}

func getStringFormatOptions(rc *RuleContext) []stringFormatOption {
	var out []stringFormatOption
	if rc.Rule.cfg == nil {
		return out
	}
	for _, arg := range rc.Rule.cfg.Arguments {
		slice, ok := arg.([]interface{})
		if !ok || len(slice) < 2 {
			continue
		}
		scope := slice[0].(string)
		reStr := slice[1].(string)
		_, re, err := parseStringFormatRegex(reStr)
		if err != nil {
			continue
		}
		msg := ""
		if len(slice) >= 3 {
			msg = slice[2].(string)
		}
		out = append(out, stringFormatOption{scopeParts: strings.Split(scope, "."), pattern: re.String(), regexStr: reStr, msg: msg, re: re})
	}
	return out
}

func callComponents(rc *RuleContext, call *ast.CallExpr) [][]string {
	var candidates [][]string
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		candidates = append(candidates, []string{fun.Name})
		candidates = append(candidates, []string{rc.File.AST.Name.Name, fun.Name})
	case *ast.SelectorExpr:
		// pkg.Func
		if id, ok := fun.X.(*ast.Ident); ok {
			// check if ident is a package name from imports
			isPkg := false
			for _, imp := range rc.File.AST.Imports {
				path, _ := unquoteString(imp.Path)
				name := path
				if idx := strings.LastIndex(name, "/"); idx >= 0 {
					name = name[idx+1:]
				}
				if imp.Name != nil {
					name = imp.Name.Name
				}
				if name == id.Name {
					isPkg = true
				}
			}
			if isPkg {
				candidates = append(candidates, []string{id.Name, fun.Sel.Name})
			} else {
				// method on variable: type inference via local receiver types
				candidates = append(candidates, []string{fun.Sel.Name})
				// try infer type name of receiver variable
				if obj := rc.objectOf(id); obj != nil && obj.Type() != nil {
					t := obj.Type()
					// strip pointer
					typeName := namedTypeName(t)
					if typeName != "" {
						candidates = append(candidates, []string{typeName, fun.Sel.Name})
						if pkgName := namedTypePkgName(t); pkgName != "" {
							candidates = append(candidates, []string{pkgName, typeName, fun.Sel.Name})
						}
					}
				}
				// Also receiver type could be field / selector expression
				candidates = append(candidates, []string{rc.source(fun.X), fun.Sel.Name})
			}
		} else {
			candidates = append(candidates, []string{fun.Sel.Name})
		}
	}
	return candidates
}

func namedTypeName(t interface{ String() string }) string { return "" }

func ruleStringFormat(rc *RuleContext) {
	options := getStringFormatOptions(rc)
	if len(options) == 0 {
		return
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		candidates := callComponents(rc, call)
		for _, opt := range options {
			matched := false
			for _, cand := range candidates {
				if equalSlice(cand, opt.scopeParts) {
					matched = true
				}
				// scope can be suffix of candidate (e.g., candidate pkg.Type.Method vs scope Type.Method)
				if len(opt.scopeParts) < len(cand) && equalSlice(cand[len(cand)-len(opt.scopeParts):], opt.scopeParts) {
					matched = true
				}
			}
			if !matched {
				continue
			}
			lit, ok := call.Args[0].(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				continue
			}
			strVal, ok := unquoteString(lit)
			if !ok {
				continue
			}
			if !opt.re.MatchString(strVal) {
				msg := opt.msg
				if msg == "" {
					msg = fmt.Sprintf("string literal doesn't match user defined regex /%s/", opt.re.String())
					// For slash delimited original, original message shows original string
					if strings.HasPrefix(opt.regexStr, "/") {
						msg = fmt.Sprintf("string literal doesn't match user defined regex %s", opt.regexStr)
					}
				}
				rc.addNode(lit, msg, 1)
			}
		}
		return true
	})
}

func equalSlice(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func ruleAtomic(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhsIdent, ok := assign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		call, ok := assign.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, _, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "atomic" {
			return true
		}
		if len(call.Args) == 0 {
			return true
		}
		if unary, ok := call.Args[0].(*ast.UnaryExpr); ok && unary.Op == token.AND {
			if id, ok := unary.X.(*ast.Ident); ok && id.Name == lhsIdent.Name {
				rc.addNode(assign, "direct assignment to atomic value", 1)
			}
		}
		return true
	})
}

func ruleDatarace(rc *RuleContext) {
	// range variables captured in goroutines
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		type varInfo struct {
			name string
			kind string // "value" or "key" wording?
		}
		var vars []varInfo
		if id, ok := rs.Value.(*ast.Ident); ok && id.Name != "_" {
			vars = append(vars, varInfo{id.Name, "value"})
		}
		if id, ok := rs.Key.(*ast.Ident); ok && id.Name != "_" {
			vars = append(vars, varInfo{id.Name, "key"})
		}
		if len(vars) == 0 {
			return true
		}
		ast.Inspect(rs.Body, func(m ast.Node) bool {
			goStmt, ok := m.(*ast.GoStmt)
			if !ok {
				return true
			}
			// go func literal
			var lit *ast.FuncLit
			if fl, ok := goStmt.Call.Fun.(*ast.FuncLit); ok {
				lit = fl
			}
			if lit == nil {
				return true
			}
			shadow := map[string]bool{}
			if lit.Type != nil && lit.Type.Params != nil {
				for _, f := range lit.Type.Params.List {
					for _, nm := range f.Names {
						shadow[nm.Name] = true
					}
				}
			}
			ast.Inspect(lit.Body, func(x ast.Node) bool {
				if id, ok := x.(*ast.Ident); ok && !shadow[id.Name] {
					for _, v := range vars {
						if id.Name == v.name {
							wording := "range value"
							if v.kind == "key" {
								wording = "range key"
							}
							// Original message for key may be different; we'll refine after probe
							rc.addNode(id, fmt.Sprintf("datarace: %s %s is captured (by-reference) in goroutine", wording, id.Name), 1)
						}
					}
				}
				return true
			})
			return true
		})
		return true
	})
	// Loop variables in for statements captured?
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		fs, ok := n.(*ast.ForStmt)
		if !ok {
			return true
		}
		// init var
		var loopVars []string
		if assign, ok := fs.Init.(*ast.AssignStmt); ok {
			for _, lhs := range assign.Lhs {
				if id, ok := lhs.(*ast.Ident); ok {
					loopVars = append(loopVars, id.Name)
				}
			}
		}
		if len(loopVars) == 0 {
			return true
		}
		ast.Inspect(fs.Body, func(m ast.Node) bool {
			goStmt, ok := m.(*ast.GoStmt)
			if !ok {
				return true
			}
			fl, ok := goStmt.Call.Fun.(*ast.FuncLit)
			if !ok {
				return true
			}
			ast.Inspect(fl.Body, func(x ast.Node) bool {
				if id, ok := x.(*ast.Ident); ok {
					for _, v := range loopVars {
						if id.Name == v {
							rc.addNode(id, fmt.Sprintf("datarace: loop variable %s is captured (by-reference) in goroutine", id.Name), 1)
						}
					}
				}
				return true
			})
			return true
		})
		return true
	})
}

func goVersionForFile(rc *RuleContext) (int, int, bool) {
	_, root, ok := findModule(rc.Pkg.AbsDir)
	if !ok {
		return 0, 0, false
	}
	data, err := readFileBytes(root + "/go.mod")
	if err != nil {
		return 0, 0, false
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "go ") {
			ver := strings.Fields(line)
			if len(ver) >= 2 {
				parts := strings.Split(ver[1], ".")
				if len(parts) >= 2 {
					maj, _ := strconv.Atoi(parts[0])
					min, _ := strconv.Atoi(parts[1])
					return maj, min, true
				}
			}
		}
	}
	return 0, 0, false
}

func readFileBytes(path string) ([]byte, error) {
	return osReadFile(path)
}

func ruleUseSlicesSort(rc *RuleContext) {
	maj, min, ok := goVersionForFile(rc)
	if !ok || maj < 1 || (maj == 1 && min < 21) {
		return
	}
	mapping := map[string]string{
		"Ints": "Sort", "Strings": "Sort", "Float64s": "Sort",
		"Slice": "SortFunc", "SliceStable": "SortStableFunc", "SliceIsSorted": "IsSortedFunc",
		"IntsAreSorted": "IsSorted", "StringsAreSorted": "IsSorted", "Float64sAreSorted": "IsSorted",
	}
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, sel, ok := selectorPkgSel(call.Fun)
		if !ok || pkg != "sort" {
			return true
		}
		if repl, ok := mapping[sel]; ok {
			rc.addNode(call, fmt.Sprintf("replace sort.%s by slices.%s", sel, repl), 1)
		}
		return true
	})
}

func ruleUseWaitgroupGo(rc *RuleContext) {
	maj, min, ok := goVersionForFile(rc)
	if !ok || maj < 1 || (maj == 1 && min < 25) {
		return
	}
	// Look in blocks for pattern wg.Add(1) followed by GoStmt with defer wg.Done
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i, stmt := range block.List {
			exprStmt, ok := stmt.(*ast.ExprStmt)
			if !ok {
				continue
			}
			addCall, ok := exprStmt.X.(*ast.CallExpr)
			if !ok {
				continue
			}
			recvSrc, sel, ok := methodCallInfo(rc, addCall)
			if !ok || sel != "Add" {
				continue
			}
			if len(addCall.Args) != 1 {
				continue
			}
			if lit, ok := addCall.Args[0].(*ast.BasicLit); !ok || lit.Value != "1" {
				continue
			}
			// find next GoStmt in same block (immediate next statement?)
			if i+1 >= len(block.List) {
				continue
			}
			goStmt, ok := block.List[i+1].(*ast.GoStmt)
			if !ok {
				continue
			}
			fl, ok := goStmt.Call.Fun.(*ast.FuncLit)
			if !ok || fl.Body == nil || len(fl.Body.List) == 0 {
				continue
			}
			// first statement should be defer wg.Done()
			deferStmt, ok := fl.Body.List[0].(*ast.DeferStmt)
			if !ok {
				continue
			}
			recv2, sel2, ok := methodCallInfo(rc, deferStmt.Call)
			if ok && sel2 == "Done" && recv2 == recvSrc {
				rc.addNode(addCall, fmt.Sprintf("replace %s.Add()...go {...%s.Done()...} with %s.Go(...)", recvSrc, recvSrc, recvSrc), 1)
			}
		}
		return true
	})
}

func methodCallInfo(rc *RuleContext, call *ast.CallExpr) (string, string, bool) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return "", "", false
	}
	return rc.source(sel.X), sel.Sel.Name, true
}

func ruleForbiddenCallInWGGo(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		recvSrc, sel, ok := methodCallInfo(rc, call)
		if !ok || sel != "Go" {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		fl, ok := call.Args[0].(*ast.FuncLit)
		if !ok || fl.Body == nil {
			return true
		}
		ast.Inspect(fl.Body, func(m ast.Node) bool {
			inner, ok := m.(*ast.CallExpr)
			if !ok {
				return true
			}
			// wg.Done()
			if recv2, sel2, ok := methodCallInfo(rc, inner); ok && recv2 == recvSrc && sel2 == "Done" {
				rc.addNode(inner, fmt.Sprintf("do not call %s.Done inside %s.Go", recvSrc, recvSrc), 1)
				return true
			}
			if id, ok := inner.Fun.(*ast.Ident); ok && id.Name == "panic" {
				rc.addNode(inner, fmt.Sprintf("do not call panic inside %s.Go", recvSrc), 1)
			}
			return true
		})
		return true
	})
}
