package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	registerRule("redefines-builtin-id", "logic", ruleRedefinesBuiltin)
	registerRule("inefficient-map-lookup", "style", ruleInefficientMapLookup)
}

var builtinFuncs = map[string]bool{
	"append": true, "cap": true, "clear": true, "close": true, "complex": true, "copy": true, "delete": true, "imag": true, "len": true, "make": true, "max": true, "min": true, "new": true, "panic": true, "print": true, "println": true, "real": true, "recover": true,
}
var builtinTypes = map[string]bool{
	"any": true, "bool": true, "byte": true, "comparable": true, "complex64": true, "complex128": true, "error": true, "float32": true, "float64": true, "int": true, "int8": true, "int16": true, "int32": true, "int64": true, "rune": true, "string": true, "uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true, "uintptr": true,
}
var builtinConsts = map[string]bool{
	"true": true, "false": true, "iota": true, "nil": true,
}

func builtinKind(name string) string {
	if builtinFuncs[name] {
		return "function"
	}
	if builtinTypes[name] {
		return "type"
	}
	if builtinConsts[name] {
		return "constant or variable"
	}
	return ""
}

func ruleRedefinesBuiltin(rc *RuleContext) {
	check := func(id *ast.Ident, node ast.Node) {
		if id == nil {
			return
		}
		kind := builtinKind(id.Name)
		if kind == "" {
			return
		}
		rc.addNode(node, fmt.Sprintf("redefinition of the built-in %s %s", kind, id.Name), 1)
	}
	// GenDecls & FuncDecls anywhere
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.GenDecl:
			if node.Tok == token.IMPORT {
				return true
			}
			for _, spec := range node.Specs {
				switch sp := spec.(type) {
				case *ast.ValueSpec:
					for _, name := range sp.Names {
						check(name, node)
					}
				case *ast.TypeSpec:
					check(sp.Name, node)
				}
			}
			// Don't descend into GenDecl again for Assign checks (none inside)
		case *ast.FuncDecl:
			check(node.Name, node)
			// params/results idents
			if node.Type != nil {
				if node.Type.Params != nil {
					for _, f := range node.Type.Params.List {
						for _, nm := range f.Names {
							check(nm, nm)
						}
					}
				}
				if node.Type.Results != nil {
					for _, f := range node.Type.Results.List {
						for _, nm := range f.Names {
							check(nm, nm)
						}
					}
				}
			}
		case *ast.FuncLit:
			if node.Type != nil && node.Type.Params != nil {
				for _, f := range node.Type.Params.List {
					for _, nm := range f.Names {
						check(nm, nm)
					}
				}
			}
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						check(id, node)
					}
				}
			}
		}
		return true
	})
}

func ruleInefficientMapLookup(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		keyIdent, ok := rs.Key.(*ast.Ident)
		if !ok {
			return true
		}
		// Value must be nil or _
		if rs.Value != nil {
			if id, ok := rs.Value.(*ast.Ident); !ok || id.Name != "_" {
				return true
			}
		}
		// X type must be a map
		xType := rc.typeOf(rs.X)
		isMap := false
		if xType != nil {
			if _, ok := xType.Underlying().(*types.Map); ok {
				isMap = true
			}
		} else {
			// fallback: X ident whose type expression in params/vars is map (handled by type checker usually)
			isMap = true // type checker should have set type for local variables; if nil due import failures, assume? We'll keep false-safe by checking AST declaration later
			// To avoid false positives for slices, we need better: check if X is Ident and decl type not available - set false
			// Determine via object type if available
			if id, ok := rs.X.(*ast.Ident); ok {
				if obj := rc.objectOf(id); obj != nil && obj.Type() != nil {
					if _, ok := obj.Type().Underlying().(*types.Map); ok {
						isMap = true
					} else {
						isMap = false
					}
				} else {
					isMap = false
				}
			} else {
				isMap = false
			}
		}
		if !isMap {
			return true
		}
		found := false
		ast.Inspect(rs.Body, func(m ast.Node) bool {
			if found {
				return false
			}
			if ifStmt, ok := m.(*ast.IfStmt); ok {
				if be, ok := ifStmt.Cond.(*ast.BinaryExpr); ok && be.Op == token.EQL {
					if (isIdent(be.X, keyIdent.Name) || isIdent(be.Y, keyIdent.Name)) {
						found = true
					}
				}
			}
			return true
		})
		if found {
			rc.addNode(rs, "inefficient lookup of map key", 1)
		}
		return true
	})
}

func isIdent(e ast.Expr, name string) bool {
	id, ok := e.(*ast.Ident)
	return ok && id.Name == name
}
