	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		vars := map[string]bool{}
		if id, ok := rs.Key.(*ast.Ident); ok && id.Name != "_" {
			vars[id.Name] = true
		}
		if id, ok := rs.Value.(*ast.Ident); ok && id.Name != "_" {
			vars[id.Name] = true
		}
		if len(vars) == 0 {
			return true
		}
		// Parent-aware walk of body
		var stack []ast.Node
		ast.Inspect(rs.Body, func(m ast.Node) bool {
			if m == nil {
				if len(stack) > 0 { stack = stack[:len(stack)-1] }
				return false
			}
			if fl, ok := m.(*ast.FuncLit); ok {
				// Determine if immediately invoked: parent is a CallExpr where Fun == fl and that call is a plain ExprStmt/Assign etc, not Go/Defer.
				isImmediate := false
