{"command":"cat > /tmp/fix_structtag.py <<'PY'
import pathlib
p=pathlib.Path("rules_batch4.go"); s=p.read_text()
start=s.index("func ruleStructTag")
end=s.index("func validStructTag")
new='''func ruleStructTag(rc *RuleContext) {
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		field, ok := n.(*ast.Field)
		if !ok || field.Tag == nil {
			return true
		}
		tag, err := strconv.Unquote(field.Tag.Value)
		if err != nil {
			rc.addNode(field.Tag, "malformed tag", 1)
			return true
		}
		if !validStructTag(tag) {
			rc.addNode(field.Tag, "malformed tag", 1)
			return true
		}
		// parse pairs and validate
		pairs := parseStructTagPairs(tag)
		for _, pair := range pairs {
			validateStructTagPair(rc, field.Tag, pair.key, pair.value)
		}
		return true
	})
}

type structTagPair struct{ key, value string }

func parseStructTagPairs(tag string) []structTagPair {
	var out []structTagPair
	rest := tag
	for rest != "" {
		rest = strings.TrimLeft(rest, " ")
		if rest == "" { break }
		// key up to :
		i := strings.Index(rest, ":")
		if i < 0 { break }
		key := rest[:i]
		rest = rest[i+1:]
		if len(rest)==0 || rest[0] != '"' { break }
		// find closing quote accounting escapes
		j := 1
		for j < len(rest) {
			if rest[j]=='\\\\' { j+=2; continue }
			if rest[j]=='"' { break }
			j++
		}
		if j >= len(rest) { break }
		q := rest[:j+1]
		val, err := strconv.Unquote(q)
		if err != nil { break }
		out = append(out, structTagPair{key, val})
		rest = rest[j+1:]
	}
	return out
}

var structTagOptions = map[string]map[string]bool{
	"json": {"omitempty": true, "string": true},
	"xml": {"attr": true, "chardata": true, "innerxml": true, "comment": true, "omitempty": true, "any": true, "cdata": true},
	"yaml": {"omitempty": true, "flow": true, "inline": true},
	"bson": {"omitempty": true, "minsize": true, "inline": true},
	"toml": {"omitempty": true},
	"url": {"omitempty": true},
	"mapstructure": {"omitempty": true, "squash": true},
	"asn1": {"optional": true, "explicit": true, "application": true, "private": true, "set": true, "utf8string": true, "ia5string": true, "visiblestring": true, "universalstring": true, "bmpstring": true, "generalized": true, "utc": true, "numericstring": true, "octetstring": true, "teletexstring": true, "videotexstring": true, "generalstring": true},
}

var validateTagOptions = map[string]bool{
	"required": true, "email": true, "omitempty": true, "url": true, "uri": true, "http_url": true, "uuid": true, "alpha": true, "alphanum": true, "numeric": true, "boolean": true, "min": true, "max": true, "len": true, "eq": true, "ne": true, "gt": true, "gte": true, "lt": true, "lte": true, "oneof": true, "datetime": true, "timezone": true, "ip": true, "ipv4": true, "ipv6": true, "mac": true, "hostname": true, "fqdn": true, "creditcard": true, "issn": true, "isbn": true, "uuid4": true, "uuid5": true, "ascii": true, "printascii": true, "multibyte": true, "datauri": true, "base64": true, "json": true, "jwt": true, "file": true, "dir": true, "image": true, "required_if": true, "required_unless": true, "required_with": true, "required_without": true, "excluded_with": true, "isdefault": true, "structonly": true, "nostructlevel": true, "dive": true, "keys": true, "endkeys": true,
	// options with parameters are handled by splitting at =
}

func validateStructTagPair(rc *RuleContext, tagNode *ast.BasicLit, key string, value string) {
	report := func(msg string) { rc.addNode(tagNode, msg, 1) }
	if key == "protobuf" {
		parts := strings.Split(value, ",")
		if len(parts)==0 { return }
		validTypes := map[string]bool{"varint":true,"fixed32":true,"fixed64":true,"sfixed32":true,"sfixed64":true,"zigzag32":true,"zigzag64":true,"bool":true,"string":true,"bytes":true,"group":true,"message":true,"enum":true,"double":true,"float":true}
		if !validTypes[parts[0]] {
			report(fmt.Sprintf("invalid tag name %q in protobuf tag", parts[0])); return
		}
		validOpts := map[string]bool{"opt":true,"req":true,"rep":true,"packed":true,"proto3":true,"json":true}
		for i, part := range parts[1:] {
			if i==0 {
				// field number must be numeric, otherwise reported as unknown option in original
				if _, err := strconv.Atoi(part); err != nil {
					report(fmt.Sprintf("unknown option %q in protobuf tag", part)); return
				}
				continue
			}
			base := part
			if idx := strings.Index(base, "="); idx>=0 { base = base[:idx] }
			if base=="name" || base=="json_name" || base=="label" || base=="wire" || base=="oneof" || validOpts[base] {
				continue
			}
			report(fmt.Sprintf("unknown option %q in protobuf tag", part)); return
		}
		return
	}
	if key == "validate" {
		if value=="" { return }
		for _, part := range strings.Split(value, ",") {
			base := part
			if idx := strings.Index(base, "="); idx>=0 { base = base[:idx] }
			if !validateTagOptions[base] {
				report(fmt.Sprintf("unknown option %q in validate tag", part)); return
			}
		}
		return
	}
	opts, ok := structTagOptions[key]
	if !ok { return }
	if value == "" { return }
	parts := strings.Split(value, ",")
	name := parts[0]
	options := parts[1:]
	// asn1: name may be absent? In asn1 values, first component is an option itself if it's in set.
	if key == "asn1" {
		// If first part looks like an option (optional/explicit/tag:/default:), treat whole as options.
		if isAsn1Option(name) {
			options = parts
			name = ""
		}
	}
	for _, opt := range options {
		if opt == "" {
