	for _, a := range args {
		if _, ok := a.(map[string]interface{}); !ok {
			return fmt.Errorf("invalid argument to the dot-imports rule. Expecting a k,v map, got %T", a)
		}
	}
	return nil
}
func configureErrorStrings(args []interface{}, cfg *RuleConfig) error {
	for _, a := range args {
		str, ok := a.(string)
		if !ok {
			continue
		}
		if !isValidCustomErrorFunc(str) {
			return fmt.Errorf("found invalid custom function: %s", str)
		}
	}
	return nil
}
func isValidCustomErrorFunc(s string) bool {
	parts := strings.Split(s, ".")
	if len(parts) < 2 {
		return false
	}
	for _, part := range parts {
		if part == "" { return false }
		for i, r := range part {
			if !(r == '_' || ('A' <= r && r <= 'Z') || ('a' <= r && r <= 'z') || ('0' <= r && r <= '9')) { return false }
			if i == 0 && '0' <= r && r <= '9' { return false }
		}
	}
	return true
}
func ruleDotImports(rc *RuleContext) {''')
# error-strings: include custom functions
old='''		pkg, sel, ok := selectorPkgSel(call.Fun)
