			return true
		}
		if len(call.Args) == 0 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)'''
new='''		if !isErrorStringFunc(rc, call) {
			return true
		}
		if len(call.Args) == 0 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)'''
assert old in s; s=s.replace(old,new)
# add helper before ruleErrorStrings
s=s.replace('''func ruleErrorStrings(rc *RuleContext) {''','''func isErrorStringFunc(rc *RuleContext, call *ast.CallExpr) bool {
	if pkg, sel, ok := selectorPkgSel(call.Fun); ok && ((pkg == "errors" && sel == "New") || (pkg == "fmt" && sel == "Errorf")) {
		return true
	}
	// custom functions configured as dotted names, compare to full dotted source of Fun
	if rc.Rule.cfg != nil {
		funSrc := rc.source(call.Fun)
		// normalize spaces
