start=s.index("func ruleDefer")
end=s.index("func ruleFlagParameter")
new='''func deferEnabledChecks(rc *RuleContext) map[string]bool {
	if rc.Rule.cfg == nil || len(rc.Rule.cfg.Arguments)==0 {
		return map[string]bool{"loop": true, "recover": true, "immediate-recover": true}
	}
	out := map[string]bool{}
	if slice, ok := rc.Rule.cfg.Arguments[0].([]interface{}); ok {
		for _, e := range slice {
			if str, ok := e.(string); ok { out[str]=true }
		}
	}
	return out
}

func ruleDefer(rc *RuleContext) {
	enabled := deferEnabledChecks(rc)
	// Loop defer check
	if enabled["loop"] {
		var stack []ast.Node
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if n == nil { stack = stack[:len(stack)-1]; return false }
			if ds, ok := n.(*ast.DeferStmt); ok {
				inLoop := false; crossedFunc := false
				for i:=len(stack)-1;i>=0;i-- {
					switch stack[i].(type) {
					case *ast.FuncLit: crossedFunc = true
					case *ast.ForStmt, *ast.RangeStmt: if !crossedFunc { inLoop = true }
					}
					if inLoop { break }
				}
				if inLoop { rc.addNode(ds, "prefer not to defer inside loops", 1) }
			}
			stack = append(stack, n); return true
		})
	}
	// Immediate recover
	if enabled["immediate-recover"] {
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if ds, ok := n.(*ast.DeferStmt); ok {
				if id, ok := ds.Call.Fun.(*ast.Ident); ok && id.Name=="recover" {
					rc.addPos(ds.Pos(), ds.End(), "recover must be called inside a deferred function, this is executing recover immediately", 1, "logic", "")
				}
			}
			return true
		})
	}
	// Recover misuse
	if enabled["recover"] {
		// Names of functions deferred in this file (named deferred functions)
		deferredFuncNames := map[string]bool{}
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if ds, ok := n.(*ast.DeferStmt); ok {
				switch f := ds.Call.Fun.(type) {
				case *ast.Ident: deferredFuncNames[f.Name]=true
				case *ast.SelectorExpr: deferredFuncNames[f.Sel.Name]=true
				}
			}
			return true
		})
		// Traverse with deferred context tracking
		type ctxInfo struct { deferred bool }
		// We'll do a recursive traversal manually using stack of markers: FuncDecl/FuncLit set a new context.
		var walk func(n ast.Node, deferred bool)
		walk = func(n ast.Node, deferred bool) {
			if n == nil { return }
			// If this node is a recover call
			if call, ok := n.(*ast.CallExpr); ok {
				if id, ok := call.Fun.(*ast.Ident); ok && id.Name=="recover" {
					// direct defer recover handled by immediate check; skip here if parent is defer (we cannot know parent - check if call is immediate child of a DeferStmt by seeing if deferred flag has special marker? We approximate: if this call's position is within a DeferStmt whose Fun is recover - that defer stmt traversal will have passed deferred=false and call is direct, we skip by checking via a separate set of positions computed.
					if !deferred && !isDirectDeferRecover(rc, call) {
						rc.addPos(call.Pos(), call.End(), "recover must be called inside a deferred function", 0.8, "logic", "")
					}
				}
			}
			switch node := n.(type) {
			case *ast.FuncDecl:
				d := deferredFuncNames[node.Name.Name]
				for _, child := range childNodesOf(node.Body) { walk(child, d) }
				// Also need traverse body itself including nested; use generic child walk on Body with context d (body node won't be a recover call)
				if node.Body != nil {
					// Avoid double: we already walked children, not body. That's fine.
				}
				return
			case *ast.FuncLit:
				d := isDeferredFuncLit(rc, node)
				if node.Body != nil {
					for _, child := range childNodesOf(node.Body) { walk(child, d) }
				}
				return
			}
			for _, child := range childNodesOf(n) { walk(child, deferred) }
		}
		// Start from file decls
		for _, decl := range rc.File.AST.Decls {
			walk(decl, false)
		}
		// Also need cover statements outside decls? Go files only decls.
	}
}

func isDirectDeferRecover(rc *RuleContext, target *ast.CallExpr) bool {
	found:=false
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if ds, ok:=n.(*ast.DeferStmt); ok && ds.Call==target { found=true }
		return true
	})
	return found
}
func isDeferredFuncLit(rc *RuleContext, lit *ast.FuncLit) bool {
	found:=false
	// A FuncLit is deferred if it is the Fun of a Call whose parent is a DeferStmt, i.e., `defer func(){...}()`
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if ds, ok:=n.(*ast.DeferStmt); ok {
			if call, ok:=ds.Call.Fun.(*ast.FuncLit); ok && call==lit { found=true }
			if ds.Call.Fun==ast.Node(lit) { found=true }
			// Also direct defer of func lit without call is not valid Go
		}
		return true
	})
	return found
}
func childNodesOf(n ast.Node) []ast.Node {
	// Reuse childNodesReal from batch2 (declared there)
	return childNodesReal(n)
}

