func ruleDefer(rc *RuleContext) {
	enabled := deferEnabledChecks(rc)
	// Loop defer check
	if enabled["loop"] {
		var stack []ast.Node
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if n == nil { stack = stack[:len(stack)-1]; return false }
			if ds, ok := n.(*ast.DeferStmt); ok {
				inLoop := false; crossedFunc := false
				for i:=len(stack)-1;i>=0;i-- {
					switch stack[i].(type) {
					case *ast.FuncLit: crossedFunc = true
					case *ast.ForStmt, *ast.RangeStmt: if !crossedFunc { inLoop = true }
					}
					if inLoop { break }
				}
				if inLoop { rc.addNode(ds, "prefer not to defer inside loops", 1) }
			}
			stack = append(stack, n); return true
		})
	}
	// Immediate recover
	if enabled["immediate-recover"] {
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if ds, ok := n.(*ast.DeferStmt); ok {
				if id, ok := ds.Call.Fun.(*ast.Ident); ok && id.Name=="recover" {
					rc.addPos(ds.Pos(), ds.End(), "recover must be called inside a deferred function, this is executing recover immediately", 1, "logic", "")
				}
			}
			return true
		})
	}
	// Recover misuse
	if enabled["recover"] {
		// Names of functions deferred in this file (named deferred functions)
		deferredFuncNames := map[string]bool{}
		ast.Inspect(rc.File.AST, func(n ast.Node) bool {
			if ds, ok := n.(*ast.DeferStmt); ok {
				switch f := ds.Call.Fun.(type) {
				case *ast.Ident: deferredFuncNames[f.Name]=true
				case *ast.SelectorExpr: deferredFuncNames[f.Sel.Name]=true
