new_rule='''func ruleAddConstant(rc *RuleContext) {
	maxLitCount := int64(2)
	allowInts := map[string]bool{}
	allowFloats := map[string]bool{}
	allowStrs := map[string]bool{}
	if rc.Rule.cfg != nil {
		for _, arg := range rc.Rule.cfg.Arguments {
			if m, ok := arg.(map[string]interface{}); ok {
				if v, ok := m["maxLitCount"].(string); ok {
					if n, err := strconv.Atoi(v); err == nil { maxLitCount = int64(n) }
				}
				for key, target := range map[string]map[string]bool{"allowInts": allowInts, "allowFloats": allowFloats, "allowStrs": allowStrs} {
					if v, ok := m[key].(string); ok {
						for _, part := range strings.Split(v, ",") {
							target[strings.TrimSpace(part)] = true
						}
					}
				}
			}
		}
	}
	// Collect literals walking whole AST, skipping const decls and direct ValueSpec values.
	stringCounts := map[string]int{}
	stringFirst := map[string]*ast.BasicLit{}
	stringOrder := []string{}
	// Walk with parent tracking
	var stack []ast.Node
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		if n == nil { stack = stack[:len(stack)-1]; return false }
		if lit, ok := n.(*ast.BasicLit); ok {
			skip := false
			for _, anc := range stack {
				if gen, ok := anc.(*ast.GenDecl); ok && gen.Tok == token.CONST { skip = true }
			}
			// direct ValueSpec value
			if len(stack)>0 {
				if vs, ok := stack[len(stack)-1].(*ast.ValueSpec); ok {
					for _, val := range vs.Values { if val == ast.Node(lit) { skip = true } }
				}
			}
			if !skip {
				switch lit.Kind {
				case token.INT:
					if !allowInts[lit.Value] {
						rc.addNode(lit, fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", lit.Value), 1)
					}
				case token.FLOAT, token.IMAG:
					if !allowFloats[lit.Value] {
						rc.addNode(lit, fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", lit.Value), 1)
					}
				case token.STRING:
					key := lit.Value // include quotes as in source
					if !allowStrs[key] {
						if _, seen := stringFirst[key]; !seen { stringFirst[key]=lit; stringOrder=append(stringOrder,key) }
						stringCounts[key]++
					}
				}
			}
		}
		stack = append(stack, n); return true
	})
	for _, key := range stringOrder {
		if int64(stringCounts[key]) > maxLitCount {
			lit := stringFirst[key]
			strVal, _ := unquoteString(lit)
			rc.addNode(lit, fmt.Sprintf("string literal %q appears, at least, %d times, create a named constant for it", strVal, maxLitCount+1), 1)
		}
	}
}
