import pathlib
p=pathlib.Path("rules_batch1.go"); s=p.read_text()
start=s.index("func ruleEmptyLines")
end=s.index("func ruleRedundantBuildTag")
new='''func ruleEmptyLines(rc *RuleContext) {
	contentLines := strings.Split(string(rc.File.Content), "\\n")
	ast.Inspect(rc.File.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		lbraceLine := rc.File.Fset.Position(block.Lbrace).Line
		rbraceLine := rc.File.Fset.Position(block.Rbrace).Line
		if rbraceLine-lbraceLine < 2 {
			return true
		}
		// line numbers are 1-based; contentLines index = line-1
		if lbraceLine+1 < rbraceLine || lbraceLine+1 == rbraceLine {
			// start check: first line inside block is blank
			idx := (lbraceLine + 1) - 1
			if idx >= 0 && idx < len(contentLines) && strings.TrimSpace(contentLines[idx]) == "" {
				rc.addNode(block, "extra empty line at the start of a block", 1)
			}
		}
		if rbraceLine-1 > lbraceLine {
			idx := (rbraceLine - 1) - 1
			if idx >= 0 && idx < len(contentLines) && strings.TrimSpace(contentLines[idx]) == "" {
				// avoid double reporting single blank line in an otherwise empty block as both start and end? Original handling unknown; if the same line is both start and end candidate, only report start.
				if !(lbraceLine+1 == rbraceLine-1) {
					rc.addNode(block, "extra empty line at the end of a block", 1)
				}
			}
		}
		return true
	})
}

'''
