end=s.index("func ruleConfusingResults")
new='''func ruleConfusingNaming(rc *RuleContext) {
	if !rc.IsFirst {
		return
	}
	type info struct {
		name string
		kind string
		ident *ast.Ident
		file string
	}
	seen := map[string]info{}
	// Iterate package files in sorted order (Pkg.Files already sorted)
	for _, f := range rc.Pkg.Files {
		if f.AST == nil { continue }
		for _, decl := range f.AST.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok { continue }
			key := strings.ToLower(fd.Name.Name)
			kindCurrent := "function"
			if fd.Recv != nil { kindCurrent = "method" }
			if prev, ok := seen[key]; ok {
				if prev.name != fd.Name.Name {
					var locPhrase string
					if prev.file == f.Display {
						locPhrase = "in the same source file"
					} else {
						locPhrase = fmt.Sprintf("in %s", prev.file)
					}
					// Report on current function's name using shared fset (filename resolved from its own file)
					rc.addPos(fd.Name.Pos(), fd.Name.End(), fmt.Sprintf("Method '%s' differs only by capitalization to %s '%s' %s", fd.Name.Name, prev.kind, prev.name, locPhrase), 1, rc.Rule.Cat, "")
				}
			} else {
				seen[key] = info{name: fd.Name.Name, kind: kindCurrent, ident: fd.Name, file: f.Display}
			}
		}
	}
}

'''
